// Convert Excel serial date → "YYYY-MM" string
function excelSerialToYYYYMM(serial) {
  if (typeof serial !== "number" || !isFinite(serial)) return null;
  // Excel epoch is 1899-12-30 (accounts for Lotus 1900 leap-year bug)
  const ms = (serial - 25569) * 86400 * 1000;
  const d = new Date(ms);
  if (isNaN(d.getTime())) return null;
  const y = d.getUTCFullYear();
  const m = String(d.getUTCMonth() + 1).padStart(2, "0");
  return `${y}-${m}`;
}

// Asset Class string → internal type code used by simulation
function mapAssetClassToType(ac) {
  const s = String(ac || "").toLowerCase();
  if (s.includes("money market") || s === "cash") return "cash";
  if (s.includes("inflation")) return "tips";
  if (s.includes("treasury") || s.includes("bond")) return "bond";
  if (s.includes("consumer staples")) return "equity-def";
  if (s.includes("dividend")) return "equity-div";
  if (s.includes("foreign") || s.includes("international")) return "equity-intl";
  if (s.includes("mid-cap") || s.includes("mid cap")) return "equity-mc";
  if (s.includes("large value")) return "equity-lv";
  if (s.includes("large blend") || s.includes("large growth")) return "equity-lb";
  if (s.includes("hedge") || s.includes("managed futures") || s.includes("trend")) return "hedge-trend";
  return "equity-lb"; // safe default
}

// Parse the xlsx file → { portfolio, expenses }
// Tolerant to section-header-driven layouts; skips blanks and sub-totals.
function _parseSpreadsheet(arrayBuffer) {
  const wb = XLSX.read(arrayBuffer, { type: "array" });
  const sheet = (name) => wb.Sheets[name] ? XLSX.utils.sheet_to_json(wb.Sheets[name], { header: 1, defval: null, raw: true }) : null;

  // ─── Sheet 1: Positions as of ───
  const posRows = sheet("Positions as of") || sheet(wb.SheetNames[0]);
  if (!posRows) throw new Error("Could not find the 'Positions as of' sheet.");

  // Find "Updated as of" line for asOf date
  let asOf = "2026-04-18";
  for (const r of posRows) {
    const cell = String(r?.[0] || "");
    const m = cell.match(/Updated as of\s+(\d+)\/(\d+)\/(\d+)/i);
    if (m) {
      const [_, mo, day, yr] = m;
      asOf = `${yr.length === 2 ? "20" + yr : yr}-${mo.padStart(2, "0")}-${day.padStart(2, "0")}`;
      break;
    }
  }

  // Find the 401(k) holdings table: header row has "Ticker" and "Total Balance"
  let holdingsHeaderIdx = -1;
  for (let i = 0; i < posRows.length; i++) {
    const row = posRows[i] || [];
    const rowStr = row.map(c => String(c || "").toLowerCase()).join("|");
    if (rowStr.includes("ticker") && rowStr.includes("total balance") && rowStr.includes("asset class")) {
      holdingsHeaderIdx = i;
      break;
    }
  }
  if (holdingsHeaderIdx === -1) throw new Error("Could not locate 401(k) holdings header row.");

  const header = posRows[holdingsHeaderIdx].map(c => String(c || "").trim());
  const colIdx = (label) => header.findIndex(h => h.toLowerCase() === label.toLowerCase());
  const iName = colIdx("Name"), iTicker = colIdx("Ticker"), iAsset = colIdx("Asset Class");
  const iRoth = header.findIndex(h => /roth.*balance/i.test(h));
  const iTrad = header.findIndex(h => /traditional.*balance/i.test(h));
  const iTotal = header.findIndex(h => /total balance/i.test(h));
  const iER = header.findIndex(h => /expense ratio/i.test(h));

  const positions = [];
  for (let i = holdingsHeaderIdx + 1; i < posRows.length; i++) {
    const r = posRows[i] || [];
    const firstCell = String(r[0] || "").trim();
    if (!firstCell) continue; // blank row
    if (/^totals?$/i.test(firstCell) || firstCell.toLowerCase().startsWith("weighted")) break;
    if (/^other accounts/i.test(firstCell)) break;

    const totalBal = Number(r[iTotal]) || 0;
    if (totalBal <= 0 && !r[iTicker]) continue;

    const ticker = String(r[iTicker] || firstCell).trim() || firstCell;
    const name = String(r[iName] || firstCell).trim();
    const roth = Number(r[iRoth]) || 0;
    const trad = Number(r[iTrad]) || 0;
    const assetClass = String(r[iAsset] || "").trim();
    // Expense ratio: spreadsheet stores it as a decimal (0.0051 = 0.51%); the app's `er` field is in percent units.
    const erRaw = iER >= 0 ? Number(r[iER]) : NaN;
    const er = isNaN(erRaw) ? 0 : (erRaw < 1 ? erRaw * 100 : erRaw);

    // Skip weighted-average expense ratio row (no ticker/name but has numeric total)
    if (!ticker && !name) continue;

    const type = mapAssetClassToType(assetClass);
    // Bucket assignment based on 401(k) sleeve classification in spreadsheet:
    // - Money Market / Cash → Bucket 1 (Safety)
    // - Any bond / TIPS / treasury → Bucket 2 (Income)
    // - Any equity → Bucket 3 (Growth)
    // - Managed futures / trend / hedge → Bucket 4 (Hedge)
    let bucket = 3;
    if (type === "cash") bucket = 1;
    else if (type === "tips" || type === "bond") bucket = 2;
    else if (type === "hedge-trend") bucket = 4;

    // Use a short display name if it exists (avoid cluttering the Positions table)
    const displayName = name.length > 28 ? name.substring(0, 26) + "…" : name;
    positions.push({
      ticker: ticker || name.slice(0, 10),
      name: displayName,
      balance: totalBal,
      bucket,
      type,
      roth,
      trad,
      er,
    });
  }

  // Parse "Other accounts and Investments" section.
  // Most sub-tables end with a row like [null, null, null, balance, "Total"] — Total marker in col 4.
  // Spouse B's investment sub-tables use [null, "Total", balance, ...] — Total in col 1.
  const otherAccounts = [];
  const sections = [
    { match: /^outside account/i,       name: "Outside Account (total)" },
    { match: /^growth sleeve/i,          name: "Brokerage - Growth" },
    { match: /^speculative$/i,           name: "Brokerage - Speculative" },
    { match: /^cash reserve$/i,          name: "Brokerage - Reserve" },
    { match: /^taxable/i,                name: "Taxable Brokerage (all accts)" },
    { match: /^my hsa investments/i,    name: "HSA" },
  ];
  for (const sec of sections) {
    for (let idx = 0; idx < posRows.length; idx++) {
      const c = String(posRows[idx]?.[0] || "").trim();
      if (!sec.match.test(c)) continue;
      // Scan down ~25 rows for the first Total-in-col-4 row
      for (let j = idx + 1; j < Math.min(posRows.length, idx + 25); j++) {
        const r = posRows[j] || [];
        if (/^total$/i.test(String(r[4] || "").trim())) {
          const bal = Number(r[3]) || 0;
          if (bal > 0) otherAccounts.push({ name: sec.name, balance: bal });
          break;
        }
      }
      break;
    }
  }
  // Spouse B's two consecutive sub-tables both under "Spouse B investments",
  // both ending with [null, "Total", balance, ...].
  const spouseBIdx = posRows.findIndex(r => /^spouse\s*b.*investments/i.test(String(r?.[0] || "")));
  if (spouseBIdx >= 0) {
    let hits = 0;
    for (let j = spouseBIdx + 1; j < posRows.length; j++) {
      const r = posRows[j] || [];
      if (/^total$/i.test(String(r[1] || "").trim())) {
        const bal = Number(r[2]) || 0;
        if (bal > 0) {
          const _nB = PORTFOLIO.nameB || "Spouse B";
          otherAccounts.push({ name: hits === 0 ? `${_nB} - Annuity` : `${_nB} - State Plan`, balance: bal });
          hits++;
        }
        if (hits >= 2) break;
      }
      if (/^my hsa/i.test(String(r[0] || "").trim())) break;
    }
  }

  // Total household: prefer the explicit "Entire combined investments Total"
  let household = 0;
  for (const r of posRows) {
    const label = String(r?.[0] || "");
    if (/entire combined investments/i.test(label)) {
      household = Number(r[1]) || 0;
      break;
    }
  }
  if (!household) {
    // Fallback: sum positions + otherAccounts
    household = positions.reduce((s, p) => s + p.balance, 0) +
                otherAccounts.reduce((s, a) => s + a.balance, 0);
  }

  // ─── Read bucket allocations from the dedicated "Bucket Allocations" sheet ───
  // This sheet is now the AUTHORITATIVE source for bucket dollar totals.
  // Layout:
  //   Row 1, Col C: Total for the Bucket Allocations  <- household-wide bucketed total
  //   Then for each bucket: a "Bucket #N - Goal is X%" header, position rows, and a
  //   "Totals in Bucket #N" row with the bucket dollar total in col C.
  //
  // The user has indicated this sheet now includes BOTH 401(k) holdings AND other
  // household accounts (outside/brokerage, HSA, etc.), so the C1 total is the full
  // household bucketed total — not just 401(k).
  //
  // Falls back to summing parsed positions if the sheet is missing or malformed.
  const bucketAllocRows = sheet("Bucket Allocations") || [];
  const bucketSums = { 1: 0, 2: 0, 3: 0, 4: 0 };
  // Per-bucket holdings list (from the Bucket Allocations sheet).
  // Each entry: { ticker, balance, bucket }. Used by the Buckets tab to show
  // both 401(k) holdings AND other accounts that have been bucketed.
  const bucketedHoldings = [];
  let bucketSheetTotal = 0;

  // Cell C1 (row 0, col 2 zero-indexed) holds the household bucketed total
  if (bucketAllocRows.length > 0) {
    const c1 = Number(bucketAllocRows[0]?.[2]);
    if (!isNaN(c1) && c1 > 0) bucketSheetTotal = c1;
  }

  // Walk the sheet looking for "Bucket #N" headers and position rows.
  // A bucket section ends at one of:
  //   - "Totals in Bucket #N" row (preferred terminator with explicit total)
  //   - Next "Bucket #N" header (so we never bleed positions across buckets)
  //   - "Total" row standalone (grand total — terminate without ingesting)
  let currentBucket = null;
  for (const r of bucketAllocRows) {
    const c0 = String(r?.[0] || "").trim();
    const headerMatch = c0.match(/^Bucket\s*#?\s*([1-4])/i);
    if (headerMatch) {
      currentBucket = Number(headerMatch[1]);
      continue;
    }
    if (currentBucket === null) continue;
    // Explicit totals row for this bucket — capture and reset
    if (/^Totals?\s+in\s+Bucket/i.test(c0)) {
      const total = Number(r[2]);
      if (!isNaN(total) && total > 0) bucketSums[currentBucket] = total;
      currentBucket = null;
      continue;
    }
    // Grand total row at end of sheet — terminate, do NOT ingest as a position
    if (/^Total\s*$/i.test(c0)) {
      currentBucket = null;
      continue;
    }
    // Skip the Symbol header row
    if (/^symbol$/i.test(c0)) continue;
    // Position row — capture if it has a label and a numeric balance
    if (c0) {
      const bal = Number(r[2]);
      if (!isNaN(bal) && bal > 0) {
        bucketedHoldings.push({ ticker: c0, balance: bal, bucket: currentBucket });
      }
    }
  }

  // For any bucket that has holdings but no explicit Totals row (e.g., Bucket 4 in some
  // spreadsheet layouts), derive its total by summing the captured holdings.
  [1, 2, 3, 4].forEach(b => {
    if (bucketSums[b] === 0) {
      const sumFromHoldings = bucketedHoldings.filter(h => h.bucket === b).reduce((s, h) => s + h.balance, 0);
      if (sumFromHoldings > 0) bucketSums[b] = sumFromHoldings;
    }
  });

  // Fall back to summing 401(k) positions if the Bucket Allocations sheet didn't yield data
  const sheetGaveData = (bucketSums[1] + bucketSums[2] + bucketSums[3] + bucketSums[4]) > 0;
  if (!sheetGaveData) {
    positions.forEach(p => { bucketSums[p.bucket] = (bucketSums[p.bucket] || 0) + p.balance; });
  }

  // total401k field (kept for backward compatibility; now actually represents the full
  // bucketed household total, not just 401k)
  let total401k = bucketSheetTotal;
  if (total401k <= 0) {
    total401k = bucketSums[1] + bucketSums[2] + bucketSums[3] + bucketSums[4];
  }

  const bucketActuals = {};
  Object.keys(bucketSums).forEach(k => {
    bucketActuals[k] = total401k > 0 ? bucketSums[k] / total401k : 0;
  });

  // ─── Sheet 2: 401K Contributions ───
  const contribRows = sheet("401K Contributions") || [];
  let monthly401k = 2692;
  for (const r of contribRows) {
    const label = String(r?.[0] || "").toLowerCase();
    if (label.includes("monthly contribution")) {
      // The "Monthly contribution total" label sits in col 3; value in col 4
      for (let ci = 1; ci < r.length; ci++) {
        const v = Number(r[ci]);
        if (!isNaN(v) && v > 500 && v < 20000) { monthly401k = v; break; }
      }
    }
  }

  // Parse per-ticker future contribution allocations.
  // Sheet has a header row "Symbol | | %" then ticker/percent rows, then a totals row (col[2] === 1).
  const contribAllocations = {};
  let inAllocBlock = false;
  for (const r of contribRows) {
    const c0 = String(r?.[0] || "").trim();
    const c2 = r?.[2];
    if (!inAllocBlock && /^symbol$/i.test(c0)) { inAllocBlock = true; continue; }
    if (inAllocBlock) {
      const v = Number(c2);
      if (c0 && !isNaN(v) && v > 0 && v <= 1) {
        if (/^[A-Z][A-Z0-9]{1,6}$/.test(c0)) contribAllocations[c0] = v;
      } else if (!c0 && Math.abs(Number(c2) - 1) < 0.001) {
        inAllocBlock = false;
      }
    }
  }

  // Spouse B's biweekly contributions (outside/state plan). Convert to monthly: × 26/12.
  let spouseBBiweekly = 0;
  for (const r of posRows) {
    const label = String(r?.[0] || "");
    if (/bencor.*aul fixed|frs.*retirement fund/i.test(label)) {
      const v = Number(r[3]) || 0; // "her bi-weekly contributions" column
      if (v > 0 && v < 1000) spouseBBiweekly += v;
    }
  }
  const spouseBMonthly = Math.round(spouseBBiweekly * 26 / 12);

  // HSA monthly: master prompt says $8,550/yr → ~$712/mo. Keep a reasonable default.
  const hsaMonthly = 712;

  // ─── Sheet 3: Monthly Expenses ───
  const expRows = sheet("Monthly Expenses") || [];
  const expenses = [];
  let curCategory = "Other";
  const categoryMap = {
    "home related": "Housing",
    "utilities and communication services": "Utilities",
    "family": "Family",
    "all insurance": "Insurance",
    "future expenses": "Retirement Life",
    "future home life": "Retirement Life",
    "future home": "Retirement Life",
  };

  for (let r = 0; r < expRows.length; r++) {
    const row = expRows[r] || [];
    const firstCell = String(row[0] || "").trim();
    const lower = firstCell.toLowerCase();
    if (categoryMap[lower]) { curCategory = categoryMap[lower]; continue; }
    if (!firstCell) continue;
    if (/^expenses$/i.test(firstCell)) continue;
    if (/^subcategory$/i.test(firstCell)) continue; // table header
    if (/^based on the above/i.test(firstCell)) break; // end of expenses section

    // Expense row: [Subcategory, Label, Frequency, Spend, "", Deductible, Start, End]
    const subcat = firstCell;
    const label = String(row[1] || "").trim();
    const freq = String(row[2] || "").trim().toLowerCase();
    const amount = Number(row[3]) || 0;
    const deductibleRaw = String(row[5] || "").trim().toLowerCase();
    const deductible = deductibleRaw.startsWith("yes");
    const startSerial = row[6];
    const endSerial = row[7];
    if (!label || (!freq && amount === 0)) continue;
    if (!["monthly", "once"].includes(freq)) continue;

    const start = excelSerialToYYYYMM(Number(startSerial));
    const end = excelSerialToYYYYMM(Number(endSerial));
    if (!start || !end) continue;

    // Category override for healthcare and transportation based on label text
    let cat = curCategory;
    if (/medicare|obama|aca|ltc/i.test(label) || /medicare|obama|aca/i.test(subcat)) {
      cat = /ltc/i.test(label) ? "Insurance" : "Healthcare";
    } else if (/^car (expense|payment|loan)$/i.test(label) || /car loan/i.test(subcat)) {
      cat = "Transportation";
    } else if (/golf/i.test(label) || /golf/i.test(subcat)) {
      cat = "Retirement Life";
    }

    // Phase: pre-retire (before the target retirement month), post-retire, or both.
    // Boundary defaults to April of target retire year to match historical convention.
    const _tgtYr = (PLAN_TIMELINE && PLAN_TIMELINE.targetRetireYear) || 2029;
    const RETIRE_BOUNDARY = `${_tgtYr}-04`;
    let phase;
    if (end < RETIRE_BOUNDARY) phase = "pre";
    else if (start >= RETIRE_BOUNDARY) phase = "post";
    else phase = "both";

    expenses.push({ cat, label, amount, freq, start, end, deductible, phase });
  }

  const portfolio = {
    asOf,
    household,
    total401k,
    nameA: PORTFOLIO.nameA || "Spouse A",   // Carried forward; overwritten by docx extraction in applyLoadedData
    nameB: PORTFOLIO.nameB || "Spouse B",
    positions,
    bucketedHoldings,                    // Per-bucket holdings from Bucket Allocations sheet (incl. non-401k)
    otherAccounts,
    contributions: { monthly401k, hsaMonthly, spouseBMonthly, contribPreTaxA: monthly401k, contribRothA: 0, contribPreTaxB: spouseBMonthly, contribRothB: 0, allocations: contribAllocations },
    bucketActuals,
  };

  return { portfolio, expenses };
}

// Parse the master prompt file. Handles:
//  - real .docx (mammoth extract)
//  - plain UTF-8 text with .docx extension (common with this particular user's file)
//  - .txt / .md
async function _parseMasterPromptFile(file) {
  const buf = await file.arrayBuffer();
  // Quick heuristic: a real docx starts with ZIP magic "PK\x03\x04"
  const head = new Uint8Array(buf.slice(0, 4));
  const isZip = head[0] === 0x50 && head[1] === 0x4b && head[2] === 0x03 && head[3] === 0x04;
  if (isZip) {
    try {
      const result = await mammoth.extractRawText({ arrayBuffer: buf });
      return result.value.trim();
    } catch (e) {
      // Fall through to plain text
    }
  }
  // Plain text fallback
  return new TextDecoder("utf-8").decode(buf).trim();
}

// Apply parsed data to module-level bindings and recompute derived values.
// Extract investor names from loaded docx text. Looks for "PROMPT — X & Y", or any "X & Y" / "X and Y" near the top.
function extractNamesFromDocx(text) {
  if (!text || typeof text !== "string") return null;
  const head = text.slice(0, 800);
  const m1 = head.match(/PROMPT\s*[—–\-|]\s*([A-Z][a-zA-Z]{1,20})\s*&\s*([A-Z][a-zA-Z]{1,20})/);
  if (m1) return { nameA: m1[1], nameB: m1[2] };
  const m2 = head.match(/\b([A-Z][a-z]{2,15})\s+&\s+([A-Z][a-z]{2,15})\b/);
  if (m2) return { nameA: m2[1], nameB: m2[2] };
  const m3 = head.match(/\b([A-Z][a-z]{2,15})\s+and\s+([A-Z][a-z]{2,15})\b/);
  if (m3) return { nameA: m3[1], nameB: m3[2] };
  return null;
}

// Extract Social Security tables and pension from master prompt text.
// Handles BOTH (a) plain-text from real .docx via mammoth (each cell on its own line)
// and (b) markdown table format (legacy plain-text-with-docx-extension files).
function extractIncomeSourcesFromDocx(text, names) {
  if (!text || typeof text !== "string") return null;
  const nameA = names?.nameA || "Spouse A";
  const nameB = names?.nameB || "Spouse B";
  const result = { ssA: null, ssB: null, pension: null };

  const parsePersonBlock = (personName) => {
    // Format C (the modular master-prompt layout): a compact line like
    //   **Spouse A — **62:$2,483  63:$2,676  64:$2,886  65:$3,160  **67:$3,716**  70:$4,707
    // appearing under a "Social Security Benefit Tables" heading. Planned age/amount is bolded with **.
    const esc = personName.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    const cRe = new RegExp(`${esc}\\s*[\\u2014\\-]+[^\\n]*?((?:\\*{0,2}\\d{2}\\*{0,2}\\s*:\\s*\\*{0,2}\\$[0-9,]+\\*{0,2}\\s*){4,})`, "i");
    const cMatch = text.match(cRe);
    if (cMatch) {
      // Strip a leading "**" that belongs to the bolded NAME (e.g. "**Spouse A — **62:..."),
      // so it isn't mistaken for bold around the first age token.
      let seg = cMatch[1].replace(/^\s*\*{1,2}\s*/, "");
      // A planned cell is bolded around the DOLLAR amount: **67:$3,716** or 63:**$1,458**.
      // Detect planned age from a token whose amount (or the age:amount pair) is wrapped in **.
      const tableByAge = {};
      let plannedAge = null;
      // First pass: build the full table (ignore bold).
      const allRe = /(\d{2})\s*:\s*\**\$([0-9,]+)\**/g;
      let m2;
      while ((m2 = allRe.exec(seg)) !== null) {
        tableByAge[Number(m2[1])] = Number(m2[2].replace(/,/g, ""));
      }
      // Second pass: find the planned age = the pair explicitly wrapped in ** around the $amount
      // or around the whole age:$amount token.
      const boldRe = /\*\*\s*(\d{2})\s*:\s*\$([0-9,]+)\s*\*\*|(\d{2})\s*:\s*\*\*\$([0-9,]+)\*\*/g;
      let mb;
      while ((mb = boldRe.exec(seg)) !== null) {
        const age = Number(mb[1] || mb[3]);
        if (!isNaN(age)) { plannedAge = age; break; }
      }
      if (Object.keys(tableByAge).length >= 4) {
        // If bold markers were stripped (e.g. mammoth on a real .docx), plannedAge may be null.
        // Fall back in order: (1) an explicit "planned age N" hint near this person, (2) FRA 67 if
        // present in the table, (3) the first age in the table. This keeps real data flowing even
        // when the markup that flagged the planned cell is gone.
        if (plannedAge === null) {
          const hintRe = new RegExp(`${personName}[\\s\\S]{0,300}?(?:planned|claim(?:ing)?)[^0-9]{0,20}(6[2-9]|70)`, "i");
          const hint = text.match(hintRe);
          if (hint) plannedAge = Number(hint[1]);
        }
        if (plannedAge === null || tableByAge[plannedAge] === undefined) {
          plannedAge = tableByAge[67] !== undefined ? 67 : Number(Object.keys(tableByAge)[0]);
        }
        const planned = tableByAge[plannedAge] ?? null;
        if (planned !== null) return { tableByAge, planned, plannedAge };
      }
    }

    const headerRe = new RegExp(`${personName}[\u2019']s\\s+Monthly\\s+Benefits\\s+by\\s+Claiming\\s+Age`, "i");
    const m = text.match(headerRe);
    if (!m) return null;
    const window = text.slice(m.index, m.index + 800);

    // Format A: plain text (mammoth on real .docx). Each cell on its own line; planned age has trailing "*".
    const ageBlock = window.match(/Age\s*62[\s\S]{0,400}?(?:\b70\b|70\*)/);
    const dollarBlock = window.match(/\$([0-9,]+)[\s\S]{0,80}?\$([0-9,]+)[\s\S]{0,80}?\$([0-9,]+)[\s\S]{0,80}?\$([0-9,]+)[\s\S]{0,80}?\$([0-9,]+)[\s\S]{0,80}?\$([0-9,]+)/);
    if (ageBlock && dollarBlock) {
      let plannedAge = null;
      const ageCells = ageBlock[0].match(/\b(6[2-7]|70)\*?/g) || [];
      for (const c of ageCells) {
        if (c.endsWith("*")) { plannedAge = Number(c.replace("*", "")); break; }
      }
      const amounts = [1,2,3,4,5,6].map(i => Number(dollarBlock[i].replace(/,/g, "")));
      const ages = [62, 63, 64, 65, 67, 70];
      const tableByAge = {};
      ages.forEach((age, i) => { tableByAge[age] = amounts[i]; });
      const planned = plannedAge !== null ? tableByAge[plannedAge] : null;
      if (planned !== null) return { tableByAge, planned, plannedAge };
    }

    // Format B: markdown table with bolded planned amount.
    const ageRowMatch = window.match(/\*\*Age\s*62\*\*[\s\S]+?\*\*70\*\*/);
    if (!ageRowMatch) return null;
    const ageRow = ageRowMatch[0];
    let plannedAge = null;
    const plannedAgeTokens = ageRow.match(/\*+\s*(?:Age\s*)?(\d{2})\*+/g);
    if (plannedAgeTokens) {
      for (const tok of plannedAgeTokens) {
        const inner = tok.match(/(\d{2})\*{3,}/);
        if (inner) { plannedAge = Number(inner[1]); break; }
      }
    }
    const afterAges = window.slice((ageRowMatch.index || 0) + ageRow.length);
    const dollarRowMatch = afterAges.match(/\|[^|\n]*\$[0-9,]+[\s\S]*?\|[^|\n]*\$[0-9,]+[\s\S]*?(?=\n\n|\n\*|\n[A-Z])/);
    if (!dollarRowMatch) return null;
    const dollarRow = dollarRowMatch[0];
    const dollarMatches = [...dollarRow.matchAll(/\$([0-9,]+)/g)].map(mm => Number(mm[1].replace(/,/g, "")));
    if (dollarMatches.length < 6) return null;
    const ages = [62, 63, 64, 65, 67, 70];
    const tableByAge = {};
    ages.forEach((age, i) => { tableByAge[age] = dollarMatches[i]; });
    let planned = null;
    const plannedMatch = dollarRow.match(/\*+\$\**([0-9,]+)\*+/);
    if (plannedMatch) {
      planned = Number(plannedMatch[1].replace(/,/g, ""));
      if (plannedAge === null) {
        const found = Object.entries(tableByAge).find(([, v]) => v === planned);
        if (found) plannedAge = Number(found[0]);
      }
    } else if (plannedAge !== null) {
      planned = tableByAge[plannedAge] || null;
    }
    return { tableByAge, planned, plannedAge };
  };

  result.ssA = parsePersonBlock(nameA);
  result.ssB = parsePersonBlock(nameB);

  const pensionHeader = text.match(/Pension[\s\S]{0,300}?\$([0-9.,]+)\s*\/?\s*month/i);
  if (pensionHeader) {
    const amount = Number(pensionHeader[1].replace(/,/g, ""));
    if (!isNaN(amount) && amount > 0 && amount < 50000) {
      result.pension = { amount, note: "joint & survivor — full to survivor" };
    }
  }
  return result;
}

function applyLoadedData({ portfolio, expenses, masterPrompt, useDefaults, incomeFromForm }) {
  if (portfolio) PORTFOLIO = portfolio;
  // v5.7 schema default: pre-ACA backups have no acaBridge — treat as feature-off, never crash.
  if (PORTFOLIO && !PORTFOLIO.acaBridge) PORTFOLIO.acaBridge = { premium: 0, size: 0 };
  // v5.8 schema default: pre-ownership backups have no owner on holdings. Retirement
  // rows default to person A (the pre-v5.8 model — flagged for review in My Data);
  // other accounts use the name as a hint ("(A)", "Spouse B ...") and default to JT.
  if (PORTFOLIO && Array.isArray(PORTFOLIO.positions)) {
    PORTFOLIO._ownerMigrated = PORTFOLIO.positions.some(p => !p.owner && ((p.trad || 0) > 0 || (p.roth || 0) > 0));
    PORTFOLIO.positions.forEach(p => { if (!p.owner) p.owner = "A"; });
  }
  // v5.9.1 (standing-audit A-2 subset): sanity clamps on imported years — a hand-edited
  // backup with an absurd retireYear/life expectancy previously hung the tab (engine loops
  // are input-bounded). Clamped at the same top-level fields the timeline actually reads.
  if (PORTFOLIO) {
    const thisYr = new Date().getFullYear();
    const clampNum = (v, lo, hi) => (Number.isFinite(Number(v)) ? Math.min(hi, Math.max(lo, Number(v))) : null);
    if (PORTFOLIO.retireYear != null) { const c = clampNum(PORTFOLIO.retireYear, 1950, thisYr + 60); if (c !== null) PORTFOLIO.retireYear = c; else delete PORTFOLIO.retireYear; }
    for (const k of ["lifeExpA", "lifeExpB"]) if (PORTFOLIO[k] != null) { const c = clampNum(PORTFOLIO[k], 50, 120); if (c !== null) PORTFOLIO[k] = c; else delete PORTFOLIO[k]; }
    for (const k of ["dobA", "dobB"]) if (PORTFOLIO[k] && PORTFOLIO[k].year != null) { const c = clampNum(PORTFOLIO[k].year, 1900, thisYr); if (c !== null) PORTFOLIO[k].year = c; }
  }
  if (PORTFOLIO && Array.isArray(PORTFOLIO.otherAccounts)) {
    PORTFOLIO.otherAccounts.forEach(a => {
      if (!a.owner) a.owner = /\(A\)|\bA -/.test(a.name || "") ? "A" : (/spouse b|\(B\)/i.test(a.name || "") ? "B" : "JT");
    });
  }
  // v5.10 schema migration: pre-tax/Roth contribution split. Old backups carry only the
  // undifferentiated monthly401k/spouseBMonthly — map them 100% pre-tax (the statistically
  // dominant default) with a one-time review notice in My Data. INVARIANT (tested): the
  // legacy fields are kept as MIRRORS of the per-bucket sums, so (a) the Monte Carlo /
  // Trajectory accumulation — which consumes the SUM via contributions.monthly401k /
  // spouseBMonthly — is byte-identical for every existing user, and (b) a v5.10 backup
  // still runs in v5.9.x, which reads contributions.monthly401k with no null guard.
  if (PORTFOLIO) {
    const c = PORTFOLIO.contributions || (PORTFOLIO.contributions = {});
    const hasNew = c.contribPreTaxA != null || c.contribRothA != null || c.contribPreTaxB != null || c.contribRothB != null;
    if (!hasNew) {
      c.contribPreTaxA = Number(c.monthly401k) || 0;
      c.contribRothA = 0;
      c.contribPreTaxB = Number(c.spouseBMonthly) || 0;
      c.contribRothB = 0;
      PORTFOLIO._contribMigrated = (c.contribPreTaxA > 0 || c.contribPreTaxB > 0);
    } else {
      PORTFOLIO._contribMigrated = false;
    }
    // Legacy mirrors = per-person totals (pre-tax + Roth). Single source of truth is the
    // four split fields; the mirrors are derived here and on Save & Apply, never edited.
    c.contribPreTaxA = Number(c.contribPreTaxA) || 0;
    c.contribRothA = Number(c.contribRothA) || 0;
    c.contribPreTaxB = Number(c.contribPreTaxB) || 0;
    c.contribRothB = Number(c.contribRothB) || 0;
    c.monthly401k = c.contribPreTaxA + c.contribRothA;
    c.spouseBMonthly = c.contribPreTaxB + c.contribRothB;
  }
  if (expenses) EXPENSES = expenses;
  if (masterPrompt) MASTER_PROMPT = masterPrompt;

  // Auto-detect investor names from the docx — but NOT when the form is the source of truth
  // (the form already set nameA/nameB on the portfolio, and the prompt text is just AI context).
  // Belt-and-suspenders: even when extraction runs, it only FILLS MISSING names — it never
  // overwrites names already present on the portfolio. This prevents cached prompt text from
  // silently reverting deliberate renames on startup (portfolios saved by older versions may
  // lack the _incomeFromForm flag, so the gate alone isn't enough).
  const _formIsSource = incomeFromForm || (portfolio && portfolio._incomeFromForm);
  if (masterPrompt && !_formIsSource) {
    const extracted = extractNamesFromDocx(masterPrompt);
    if (extracted) {
      if (!PORTFOLIO.nameA) PORTFOLIO.nameA = extracted.nameA;
      if (!PORTFOLIO.nameB) PORTFOLIO.nameB = extracted.nameB;
    }
  }
  if (!PORTFOLIO.nameA) PORTFOLIO.nameA = "Spouse A";
  if (!PORTFOLIO.nameB && !PORTFOLIO.single) PORTFOLIO.nameB = "Spouse B";

  // Extract Social Security and pension. Re-runs against cached MASTER_PROMPT so cached
  // sessions self-heal even without a fresh docx upload.
  // EXCEPTION: when income was entered via the in-app My Data form (incomeFromForm, or a
  // persisted portfolio flagged _incomeFromForm), trust the form values and do NOT let the
  // prompt parser overwrite them.
  const _incomeIsFromForm = incomeFromForm || (portfolio && portfolio._incomeFromForm);
  const _promptForSS = masterPrompt || MASTER_PROMPT;
  // The demo prompt must never masquerade as user income: if the only prompt on hand is
  // the built-in example (no user prompt this load, none cached), parsing it would silently
  // install the demo household's Social Security/pension into a REAL plan with no warning.
  // Skip the parse in that case (unless the user deliberately chose example data) so the
  // flagged-default path below runs and the red banner names the missing fields instead.
  const _promptIsDemoOnly = !masterPrompt && MASTER_PROMPT === DEFAULT_MASTER_PROMPT && !useDefaults;
  const _diag = { promptLen: _promptForSS ? _promptForSS.length : 0, ssAOk: false, ssBOk: false, penOk: false, fromForm: !!_incomeIsFromForm };
  if (_promptForSS && !_incomeIsFromForm && !_promptIsDemoOnly) {
    const sources = extractIncomeSourcesFromDocx(_promptForSS, { nameA: PORTFOLIO.nameA, nameB: PORTFOLIO.nameB });
    if (sources) {
      PORTFOLIO.incomeSources = PORTFOLIO.incomeSources || {};
      if (sources.ssA && sources.ssA.planned) { PORTFOLIO.incomeSources.ssA = sources.ssA; _diag.ssAOk = true; }
      if (sources.ssB && sources.ssB.planned) { PORTFOLIO.incomeSources.ssB = sources.ssB; _diag.ssBOk = true; }
      if (sources.pension && sources.pension.amount) { PORTFOLIO.incomeSources.pension = sources.pension; _diag.penOk = true; }
    }
  } else if (_incomeIsFromForm && PORTFOLIO.incomeSources) {
    // Income came from the form; mark diagnostics as satisfied so the banner stays silent.
    _diag.ssAOk = !!PORTFOLIO.incomeSources.ssA?.planned;
    _diag.ssBOk = !!PORTFOLIO.incomeSources.ssB?.planned;
    _diag.penOk = !!PORTFOLIO.incomeSources.pension?.amount;
  }
  // ── Silent-fallback detection ──
  // The definitive test for "we're showing example data" is whether the value sitting in
  // PORTFOLIO actually equals the example-household default AND was never overridden by a
  // real parse. We mark defaults with isDefault:true at the moment we insert them; a value
  // that came from parsing (or from cached real data) has no isDefault flag. We only warn
  // when a master prompt was available this load (so a missing value is a real failure,
  // not just an alternate load path).
  const _hadPromptToParse = !!_promptForSS;
  const _fellBackTo = [];
  if (!PORTFOLIO.incomeSources) PORTFOLIO.incomeSources = {};
  if (!PORTFOLIO.incomeSources.ssA) {
    PORTFOLIO.incomeSources.ssA = { tableByAge: {}, planned: 3300, plannedAge: 67, isDefault: true };
  }
  if (!PORTFOLIO.incomeSources.ssB) {
    PORTFOLIO.incomeSources.ssB = { tableByAge: {}, planned: 1300, plannedAge: 63, isDefault: true };
  }
  if (!PORTFOLIO.incomeSources.pension) {
    PORTFOLIO.incomeSources.pension = { amount: 400, isDefault: true };
  }
  // A field "fell back" only if it is flagged isDefault (i.e. we inserted the example value
  // because nothing real was present) AND there was a prompt that should have supplied it.
  // When income came from the in-app form, there is no parse failure to warn about.
  if (_hadPromptToParse && !_incomeIsFromForm) {
    if (PORTFOLIO.incomeSources.ssA?.isDefault) _fellBackTo.push(`${PORTFOLIO.nameA || "Person A"} Social Security`);
    if (!PORTFOLIO.single && PORTFOLIO.incomeSources.ssB?.isDefault) _fellBackTo.push(`${PORTFOLIO.nameB || "Person B"} Social Security`);
    if (PORTFOLIO.incomeSources.pension?.isDefault) _fellBackTo.push("Pension");
  }
  PORTFOLIO._incomeFellBack = _fellBackTo;  // fields that used example defaults despite a prompt being present
  PORTFOLIO._usingExampleData = !!useDefaults;  // true only when the user deliberately chose example data
  PORTFOLIO._incomeDiag = _diag;  // {promptLen, ssAOk, ssBOk, penOk} — surfaced in the banner when something failed

  // Heal cached data from older versions that lack total401k or have household-relative bucketActuals.
  if (!PORTFOLIO.total401k || PORTFOLIO.total401k <= 0) {
    if (Array.isArray(PORTFOLIO.positions) && PORTFOLIO.positions.length > 0) {
      PORTFOLIO.total401k = PORTFOLIO.positions
        .filter(p => p.bucket >= 1 && p.bucket <= 4)
        .reduce((s, p) => s + (p.balance || 0), 0);
    } else {
      PORTFOLIO.total401k = PORTFOLIO.household;
    }
  }
  if (PORTFOLIO.bucketActuals) {
    const sum = Object.values(PORTFOLIO.bucketActuals).reduce((s, v) => s + v, 0);
    if (sum > 0 && sum < 0.95) {
      // Renormalize household-relative actuals to 401k-relative
      if (Array.isArray(PORTFOLIO.positions) && PORTFOLIO.positions.length > 0 && PORTFOLIO.total401k > 0) {
        const sums = { 1: 0, 2: 0, 3: 0, 4: 0 };
        PORTFOLIO.positions.forEach(p => { if (sums[p.bucket] !== undefined) sums[p.bucket] += (p.balance || 0); });
        PORTFOLIO.bucketActuals = {
          1: sums[1] / PORTFOLIO.total401k,
          2: sums[2] / PORTFOLIO.total401k,
          3: sums[3] / PORTFOLIO.total401k,
          4: sums[4] / PORTFOLIO.total401k,
        };
      } else {
        const factor = 1 / sum;
        Object.keys(PORTFOLIO.bucketActuals).forEach(k => { PORTFOLIO.bucketActuals[k] *= factor; });
      }
    }
  }

  recomputeDerivedExpenses();

  // Re-derive the plan timeline (DOBs, retire year, SS dates, Medicare dates) and
  // rebuild RETIRE_OPTIONS so the three year choices reflect the loaded household.
  PLAN_TIMELINE = buildPlanTimeline();
  RETIRE_OPTIONS = buildRetireOptions();
}

// Try to load cached data from window.storage. Returns true if usable data found.
async function loadFromStorage() {
  if (typeof window === "undefined" || !window.storage) return false;
  try {
    const [p, e, m] = await Promise.all([
      window.storage.get(STORAGE_KEYS.portfolio).catch(() => null),
      window.storage.get(STORAGE_KEYS.expenses).catch(() => null),
      window.storage.get(STORAGE_KEYS.prompt).catch(() => null),
    ]);
    const portfolio = p?.value ? JSON.parse(p.value) : null;
    const expenses = e?.value ? JSON.parse(e.value) : null;
    const masterPrompt = m?.value || null;
    if (!portfolio && !expenses && !masterPrompt) return false;
    applyLoadedData({ portfolio, expenses, masterPrompt, incomeFromForm: portfolio && portfolio._incomeFromForm });
    return true;
  } catch (err) {
    console.error("loadFromStorage error:", err);
    return false;
  }
}

async function saveToStorage({ portfolio, expenses, masterPrompt }) {
  if (typeof window === "undefined" || !window.storage) return;
  const tasks = [];
  if (portfolio) tasks.push(window.storage.set(STORAGE_KEYS.portfolio, JSON.stringify(portfolio)));
  if (expenses) tasks.push(window.storage.set(STORAGE_KEYS.expenses, JSON.stringify(expenses)));
  if (masterPrompt) tasks.push(window.storage.set(STORAGE_KEYS.prompt, masterPrompt));
  tasks.push(window.storage.set(STORAGE_KEYS.meta, JSON.stringify({ loadedAt: new Date().toISOString() })));
  await Promise.allSettled(tasks);
}

async function clearStorage() {
  if (typeof window === "undefined" || !window.storage) return;
  await Promise.allSettled([
    window.storage.delete(STORAGE_KEYS.portfolio).catch(() => null),
    window.storage.delete(STORAGE_KEYS.expenses).catch(() => null),
    window.storage.delete(STORAGE_KEYS.prompt).catch(() => null),
    window.storage.delete(STORAGE_KEYS.meta).catch(() => null),
    window.storage.delete(STORAGE_KEYS.apikey).catch(() => null), // credentials never survive a wipe
    window.storage.delete(STORAGE_KEYS.skin).catch(() => null),   // theme resets with the plan
    window.storage.delete(STORAGE_KEYS.uiScale).catch(() => null), // UI size resets with the plan
    window.storage.delete(STORAGE_KEYS.acaRegime).catch(() => null), // ACA scenario resets with the plan
    window.storage.delete(STORAGE_KEYS.offline).catch(() => null),
    window.storage.delete(STORAGE_KEYS.localLLM).catch(() => null),
    // v5.10.2 (audit Finding B-2): the three keys below were missing from this list, so
    // "delete everything" left them in browser storage. The serious one is checklist —
    // it holds third-party names and phone numbers (attorney, CPA, insurance contact)
    // plus free-text notes. The wipe list must cover EVERY key in STORAGE_KEYS; t5
    // asserts that by looping the key map, so a future key can't silently drift out.
    window.storage.delete(STORAGE_KEYS.checklist).catch(() => null), // notes + third-party contacts
    window.storage.delete(STORAGE_KEYS.simple).catch(() => null),
    window.storage.delete(STORAGE_KEYS.ssCut).catch(() => null),
  ]);
}

// ═══════════════════════════════════════════════════════════════
// DATA LOADER UI — splash screen for first-time load
// ═══════════════════════════════════════════════════════════════

// ═══ GUIDED FIRST-RUN WIZARD ═══
// Six friendly steps → the same portfolio/expenses payload the My Data form produces →
// the same onLoaded pipeline the other entry paths use. Finishing also turns on SIMPLE
// MODE (six core tabs) so a brand-new user lands on a calm surface, not 25 tabs.
function GuidedWizard({ onDone, onCancel }) {
  const yr = new Date().getFullYear();
  const [step, setStep] = useState(0);
  const [single, setSingle] = useState(false);
  const [nA, setNA] = useState(""); const [nB, setNB] = useState("");
  const [byA, setByA] = useState(yr - 62); const [byB, setByB] = useState(yr - 60);
  const [retY, setRetY] = useState(yr + 3);
  const [leA, setLeA] = useState(88); const [leB, setLeB] = useState(90);
  const [retTotal, setRetTotal] = useState(""); const [rothAmt, setRothAmt] = useState("");
  const [outside, setOutside] = useState("");
  const [pStk, setPStk] = useState(60); const [pBnd, setPBnd] = useState(30); const [pCash, setPCash] = useState(10);
  const [ssAmtA, setSsAmtA] = useState(""); const [ssAgeA, setSsAgeA] = useState(67);
  const [ssAmtB, setSsAmtB] = useState(""); const [ssAgeB, setSsAgeB] = useState(67);
  const [pension, setPension] = useState("");
  const [spendPre, setSpendPre] = useState(""); const [spendPost, setSpendPost] = useState("");
  const [stCode, setStCode] = useState("");
  const n = (v) => Math.max(0, Number(String(v).replace(/[$,\s]/g, "")) || 0);
  const steps = ["WHO", "WHEN", "MONEY", "INCOME", "SPENDING", "STATE & BUILD"];
  const inp = { background: "var(--panel2)", border: "1px solid var(--line)", color: "var(--ink)", fontFamily: "'JetBrains Mono',monospace", fontSize: 11, padding: "8px 10px", borderRadius: 3, width: "100%", boxSizing: "border-box" };
  const lbl = { fontSize: 8, color: "var(--ink-faint)", letterSpacing: 0.5, display: "block", marginBottom: 3, marginTop: 10 };
  const canNext = step !== 2 || n(retTotal) > 0;
  const build = () => {
    const tot = n(retTotal);
    let ps = Math.max(0, pStk), pb = Math.max(0, pBnd), pc = Math.max(0, pCash);
    const sum = ps + pb + pc || 1; ps /= sum; pb /= sum; pc /= sum;
    const stB = Math.round(tot * ps), bdB = Math.round(tot * pb), csB = Math.max(0, tot - stB - bdB);
    const roth = Math.min(n(rothAmt), tot);
    const rStk = Math.min(roth, stB), rBnd = Math.min(roth - rStk, bdB);
    const positions = [];
    if (stB > 0) positions.push({ ticker: "STOCKS", name: "Stock funds (entered total)", balance: stB, bucket: 3, type: "equity-lb", roth: rStk, trad: stB - rStk, er: 0.05 });
    if (bdB > 0) positions.push({ ticker: "BONDS", name: "Bond funds (entered total)", balance: bdB, bucket: 2, type: "bond", roth: rBnd, trad: bdB - rBnd, er: 0.05 });
    if (csB > 0) positions.push({ ticker: "CASH", name: "Cash / money market", balance: csB, bucket: 1, type: "cash", roth: 0, trad: csB, er: 0 });
    const rules = stCode && STATE_RULES[stCode];
    const preM = n(spendPre) || n(spendPost), postM = n(spendPost) || n(spendPre);
    const expenses = [
      { cat: "Other", label: "Living expenses (wizard)", amount: preM, freq: "monthly", start: `${yr}-01`, end: `${retY}-06`, deductible: false, phase: "pre" },
      { cat: "Other", label: "Living expenses (wizard)", amount: postM, freq: "monthly", start: `${retY}-07`, end: "2079-12", deductible: false, phase: "post" },
    ];
    const portfolio = {
      asOf: `${yr}-01-01`, nameA: nA || "Spouse A", nameB: single ? "" : (nB || "Spouse B"), single,
      dobA: `${byA}-06`, dobB: single ? undefined : `${byB}-06`,
      retireYear: Number(retY), retireYearB: single ? undefined : Number(retY),
      lifeExpA: Number(leA), lifeExpB: single ? undefined : Number(leB),
      positions, otherAccounts: n(outside) > 0 ? [{ name: "Cash & taxable outside retirement (entered)", balance: n(outside) }] : [],
      household: tot + n(outside),
      bucketActuals: { 1: pc, 2: pb, 3: ps, 4: 0 },
      contributions: { monthly401k: 0, hsaMonthly: 0, spouseBMonthly: 0, contribPreTaxA: 0, contribRothA: 0, contribPreTaxB: 0, contribRothB: 0, allocations: {} },
      stateName: rules ? rules.name : "", stateTaxRate: rules ? rules.rate : 0, stateCode: stCode || null,
      _stateFromForm: !!stCode, _incomeFromForm: true,
      incomeSources: {
        ssA: { tableByAge: genSSTable(n(ssAmtA), Number(ssAgeA)), planned: n(ssAmtA), plannedAge: Number(ssAgeA) },
        ssB: single ? { tableByAge: {}, planned: 0, plannedAge: 67 }
                    : { tableByAge: genSSTable(n(ssAmtB), Number(ssAgeB)), planned: n(ssAmtB), plannedAge: Number(ssAgeB) },
        pension: { amount: n(pension), note: "joint & survivor" },
      },
    };
    try { window.storage && window.storage.set(STORAGE_KEYS.simple, "1").catch(() => {}); } catch (e) {}
    onDone({ portfolio, expenses });
  };
  return (
    <div style={{ maxWidth: 560, margin: "0 auto" }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", marginBottom: 4 }}>
        <div style={{ fontSize: 11, color: "var(--accent)", fontWeight: 700, letterSpacing: 2 }}>🧭 GUIDED SETUP — STEP {step + 1} OF 6: {steps[step]}</div>
        <button onClick={onCancel} style={{ background: "transparent", border: "none", color: "var(--ink-faint)", fontFamily: "inherit", fontSize: 9, cursor: "pointer" }}>✕ cancel</button>
      </div>
      <div style={{ display: "flex", gap: 3, marginBottom: 14 }}>
        {steps.map((s, i) => <div key={s} style={{ flex: 1, height: 3, background: i <= step ? "var(--accent)" : "var(--line)" }} />)}
      </div>
      <div style={{ background: "var(--panel)", border: "1px solid var(--line)", borderRadius: 4, padding: 18 }}>
        {step === 0 && (<div>
          <div style={{ fontSize: 9, color: "var(--ink-dim)", lineHeight: 1.6 }}>Rough answers are fine everywhere — everything is editable later on the My Data tab, and nothing leaves this browser.</div>
          <label style={lbl} className="lbl">Planning for</label>
          <div style={{ display: "flex", gap: 8 }}>
            {[["couple", false], ["just me", true]].map(([t, v]) => (
              <button key={t} onClick={() => setSingle(v)} style={{ flex: 1, padding: "9px 0", background: single === v ? "rgba(0,255,136,0.1)" : "transparent", border: `1px solid ${single === v ? "var(--accent)" : "var(--line)"}`, color: single === v ? "var(--accent)" : "var(--ink-dim)", fontFamily: "inherit", fontSize: 10, fontWeight: 600, cursor: "pointer", borderRadius: 3, letterSpacing: 1 }}>{t.toUpperCase()}</button>
            ))}
          </div>
          <div style={{ display: "grid", gridTemplateColumns: single ? "1fr" : "1fr 1fr", gap: 10 }}>
            <div><label style={lbl}>{single ? "YOUR FIRST NAME" : "FIRST NAME — YOU"}</label><input style={inp} value={nA} onChange={e => setNA(e.target.value)} placeholder="Sam" /></div>
            {!single && <div><label style={lbl} className="lbl">First name — spouse</label><input style={inp} value={nB} onChange={e => setNB(e.target.value)} placeholder="Pat" /></div>}
            <div><label style={lbl}>BIRTH YEAR{single ? "" : " — YOU"}</label><input style={inp} type="number" value={byA} onChange={e => setByA(e.target.value)} /></div>
            {!single && <div><label style={lbl} className="lbl">Birth year — spouse</label><input style={inp} type="number" value={byB} onChange={e => setByB(e.target.value)} /></div>}
          </div>
        </div>)}
        {step === 1 && (<div>
          <div><label style={lbl} className="lbl">Target retirement year</label><input style={inp} type="number" value={retY} onChange={e => setRetY(e.target.value)} /></div>
          <div style={{ display: "grid", gridTemplateColumns: single ? "1fr" : "1fr 1fr", gap: 10 }}>
            <div><label style={lbl}>PLAN-TO AGE{single ? "" : " — YOU"} (a 50/50 guess is fine)</label><input style={inp} type="number" value={leA} onChange={e => setLeA(e.target.value)} /></div>
            {!single && <div><label style={lbl} className="lbl">Plan-to age — spouse</label><input style={inp} type="number" value={leB} onChange={e => setLeB(e.target.value)} /></div>}
          </div>
          <div style={{ fontSize: 9, color: "var(--ink-faint)", marginTop: 8, lineHeight: 1.5 }}>The Monte Carlo tab can later treat these as the <em>median</em> of a real mortality curve — one toggle.</div>
        </div>)}
        {step === 2 && (<div>
          <div><label style={lbl}>ALL RETIREMENT ACCOUNTS COMBINED (401k / IRA / Roth, both of you)</label><input style={inp} value={retTotal} onChange={e => setRetTotal(e.target.value)} placeholder="e.g. 900,000" /></div>
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
            <div><label style={lbl}>OF THAT, HOW MUCH IS ROTH? (0 if unsure)</label><input style={inp} value={rothAmt} onChange={e => setRothAmt(e.target.value)} placeholder="e.g. 150,000" /></div>
            <div><label style={lbl} className="lbl">Cash + taxable outside retirement</label><input style={inp} value={outside} onChange={e => setOutside(e.target.value)} placeholder="e.g. 80,000" /></div>
          </div>
          <label style={lbl}>ROUGHLY HOW IS THE RETIREMENT MONEY INVESTED? (auto-normalized)</label>
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 10 }}>
            {[["STOCKS %", pStk, setPStk], ["BONDS %", pBnd, setPBnd], ["CASH %", pCash, setPCash]].map(([l, v, f]) => (
              <div key={l}><label style={lbl}>{l}</label><input style={inp} type="number" value={v} onChange={e => f(Number(e.target.value) || 0)} /></div>
            ))}
          </div>
        </div>)}
        {step === 3 && (<div>
          <div style={{ display: "grid", gridTemplateColumns: "2fr 1fr", gap: 10 }}>
            <div><label style={lbl}>SOCIAL SECURITY{single ? "" : " — YOU"} ($/mo AT THE CLAIM AGE →)</label><input style={inp} value={ssAmtA} onChange={e => setSsAmtA(e.target.value)} placeholder="from ssa.gov, e.g. 3,100" /></div>
            <div><label style={lbl} className="lbl">Claim age</label><input style={inp} type="number" min="62" max="70" value={ssAgeA} onChange={e => setSsAgeA(e.target.value)} /></div>
            {!single && <><div><label style={lbl}>SOCIAL SECURITY — SPOUSE ($/mo)</label><input style={inp} value={ssAmtB} onChange={e => setSsAmtB(e.target.value)} placeholder="e.g. 1,900" /></div>
            <div><label style={lbl} className="lbl">Claim age</label><input style={inp} type="number" min="62" max="70" value={ssAgeB} onChange={e => setSsAgeB(e.target.value)} /></div></>}
          </div>
          <div><label style={lbl}>PENSION, IF ANY ($/mo household — 0 if none)</label><input style={inp} value={pension} onChange={e => setPension(e.target.value)} placeholder="0" />
            {Number(String(pension).replace(/[^0-9.]/g, "")) > 25000 && (
              <div style={{ marginTop: 4, fontSize: 9, color: "var(--warn)", lineHeight: 1.5 }}>⚠ Monthly amount — a lump-sum pension goes in Holdings (rolled over) or Other Accounts (cash), not here.</div>
            )}</div>
        </div>)}
        {step === 4 && (<div>
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
            <div><label style={lbl}>SPENDING TODAY ($/mo, all-in)</label><input style={inp} value={spendPre} onChange={e => setSpendPre(e.target.value)} placeholder="e.g. 7,500" /></div>
            <div><label style={lbl}>EXPECTED SPENDING IN RETIREMENT ($/mo)</label><input style={inp} value={spendPost} onChange={e => setSpendPost(e.target.value)} placeholder="e.g. 7,000" /></div>
          </div>
          <div style={{ fontSize: 9, color: "var(--ink-faint)", marginTop: 8, lineHeight: 1.5 }}>One honest number beats ten precise guesses. The Expenses tab can split this into categories and time windows whenever you're ready.</div>
        </div>)}
        {step === 5 && (<div>
          <div><label style={lbl}>STATE OF RESIDENCE (drives the state-tax model)</label>
            <select style={inp} value={stCode} onChange={e => setStCode(e.target.value)}>
              <option value="">— skip for now —</option>
              {Object.entries(STATE_RULES).map(([c, r]) => <option key={c} value={c}>{r.name}{r.rate === 0 ? " (no income tax)" : ""}</option>)}
            </select>
          </div>
          <div style={{ marginTop: 12, padding: 10, background: "rgba(0,255,136,0.04)", border: "1px solid var(--line)", fontSize: 9, color: "var(--ink)", lineHeight: 1.7 }}>
            <div style={{ fontSize: 8, color: "var(--accent)", letterSpacing: 0.5, marginBottom: 4 }} className="lbl">Review</div>
            {single ? (nA || "You") : `${nA || "You"} & ${nB || "spouse"}`} · retire {retY} · ${n(retTotal).toLocaleString()} retirement (${n(rothAmt).toLocaleString()} Roth) + ${n(outside).toLocaleString()} outside · SS ${n(ssAmtA).toLocaleString()}/mo @{ssAgeA}{single ? "" : ` + ${n(ssAmtB).toLocaleString()}/mo @${ssAgeB}`} · spend ${(n(spendPost) || n(spendPre)).toLocaleString()}/mo in retirement{stCode ? ` · ${STATE_RULES[stCode].name}` : ""}
          </div>
          <div style={{ fontSize: 9, color: "var(--ink-faint)", marginTop: 8, lineHeight: 1.5 }}>Building starts you in <strong>SIMPLE MODE</strong> — six core tabs. The SHOW ALL TABS switch is always one click away, and every number here is editable on My Data.</div>
        </div>)}
        <div style={{ display: "flex", justifyContent: "space-between", marginTop: 16 }}>
          <button onClick={() => (step === 0 ? onCancel() : setStep(step - 1))} style={{ background: "transparent", border: "1px solid var(--line)", color: "var(--ink-dim)", fontFamily: "inherit", fontSize: 10, padding: "8px 16px", cursor: "pointer", borderRadius: 3, letterSpacing: 1 }}>◀ {step === 0 ? "BACK TO START" : "BACK"}</button>
          {step < 5
            ? <button onClick={() => canNext && setStep(step + 1)} disabled={!canNext} style={{ background: canNext ? "rgba(0,255,136,0.1)" : "transparent", border: "1px solid var(--accent)", color: "var(--accent)", fontFamily: "inherit", fontSize: 10, fontWeight: 700, padding: "8px 20px", cursor: canNext ? "pointer" : "not-allowed", opacity: canNext ? 1 : 0.4, borderRadius: 3, letterSpacing: 1 }}>NEXT ▶</button>
            : <button onClick={build} style={{ background: "rgba(0,255,136,0.12)", border: "1px solid var(--accent)", color: "var(--accent)", fontFamily: "inherit", fontSize: 10, fontWeight: 700, padding: "8px 20px", cursor: "pointer", borderRadius: 3, letterSpacing: 1 }}>▶ BUILD MY PLAN</button>}
        </div>
      </div>
    </div>
  );
}

function DataLoader({ onLoaded, hasData }) {
  const [showWizard, setShowWizard] = useState(false);
  const [xlsxStatus] = useState(null);
  const [promptStatus] = useState(null);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [nameA] = useState("");
  const [nameB] = useState("");

  const applyAndContinue = async (useDefaults = false) => {
    setBusy(true);
    setError("");
    try {
      const payload = {};
      if (!useDefaults && xlsxStatus?.ok) {
        payload.portfolio = xlsxStatus.data.portfolio;
        payload.expenses = xlsxStatus.data.expenses;
      }
      if (!useDefaults && promptStatus?.ok) {
        payload.masterPrompt = promptStatus.data.masterPrompt;
      }
      applyLoadedData({ ...payload, useDefaults });
      // Re-apply a form-set state-of-residence captured before "Load New Data" (the fresh
      // parse can't know about it; the docx may still say the pre-move state).
      if (!useDefaults && STATE_CARRYOVER && STATE_CARRYOVER.stateName) {
        PORTFOLIO.stateName = STATE_CARRYOVER.stateName;
        PORTFOLIO.stateTaxRate = STATE_CARRYOVER.stateTaxRate;
        PORTFOLIO.stateCode = STATE_CARRYOVER.stateCode || null;
        PORTFOLIO._stateFromForm = true;
        if (payload.portfolio) {
          payload.portfolio.stateName = STATE_CARRYOVER.stateName;
          payload.portfolio.stateTaxRate = STATE_CARRYOVER.stateTaxRate;
          payload.portfolio.stateCode = STATE_CARRYOVER.stateCode || null;
          payload.portfolio._stateFromForm = true;
        }
        PLAN_TIMELINE = buildPlanTimeline();
        RETIRE_OPTIONS = buildRetireOptions();
      }
      // Manual name override takes precedence over auto-detection
      if (!useDefaults) {
        if (nameA.trim()) PORTFOLIO.nameA = nameA.trim();
        if (nameB.trim()) PORTFOLIO.nameB = nameB.trim();
        if (payload.portfolio) {
          payload.portfolio.nameA = PORTFOLIO.nameA;
          payload.portfolio.nameB = PORTFOLIO.nameB;
        }
      }
      await saveToStorage(payload);
      onLoaded();
    } catch (err) {
      setError(err.message);
    }
    setBusy(false);
  };

  // Start with a blank plan and enter everything in the My Data tab — no files needed.
  const _hasExistingData = () => !!hasData;
  const startFresh = async () => {
    if (_hasExistingData() && !window.confirm("Start fresh?\n\nThis erases your currently saved plan (all holdings, income, expenses, and settings) and begins with a blank My Data form. This cannot be undone.\n\nTip: Cancel and use Export Backup first if you want to keep a copy.\n\nProceed with a blank plan?")) return;
    setBusy(true); setError("");
    try {
      const today = new Date().toISOString().slice(0, 10);
      const blank = {
        asOf: today, single: false, nameA: nameA.trim() || "", nameB: nameB.trim() || "",
        positions: [], otherAccounts: [],
        total401k: 0, household: 0,
        bucketActuals: { 1: 0, 2: 0, 3: 0, 4: 0 },
        contributions: { monthly401k: 0, hsaMonthly: 0, spouseBMonthly: 0, contribPreTaxA: 0, contribRothA: 0, contribPreTaxB: 0, contribRothB: 0, allocations: {} },
        incomeSources: {
          ssA: { tableByAge: {}, planned: 0, plannedAge: 67 },
          ssB: { tableByAge: {}, planned: 0, plannedAge: 67 },
          pension: { amount: 0 },
        },
        _incomeFromForm: true,
      };
      applyLoadedData({ portfolio: blank, expenses: [], masterPrompt: "", incomeFromForm: true });
      await saveToStorage({ portfolio: blank, expenses: [], masterPrompt: "" });
      onLoaded();
    } catch (err) { setError(err.message); }
    setBusy(false);
  };

  // Restore a previously exported backup (.json) — the full plan, no spreadsheet/prompt needed.
  const restoreBackup = async (f) => {
    if (_hasExistingData() && !window.confirm("Restore from backup?\n\nThis replaces your currently saved plan with the contents of the backup file. Your current data will be overwritten.\n\nProceed?")) return;
    setBusy(true); setError("");
    try {
      const text = await f.text();
      const data = JSON.parse(text);
      if (!data || !data.portfolio) throw new Error("Not a Danger Close backup file.");
      applyLoadedData({ portfolio: data.portfolio, expenses: data.expenses, masterPrompt: data.masterPrompt, incomeFromForm: !!(data.portfolio && data.portfolio._incomeFromForm) });
      await saveToStorage({ portfolio: data.portfolio, expenses: data.expenses, masterPrompt: data.masterPrompt });
      // Pass the checklist + theme up so they're restored too — the full backup carries them
      // (see handleExport), and this landing path must match the My Data import (handleImportData).
      onLoaded({ checklist: data.checklist, skin: data.skin });
    } catch (err) { setError("Restore failed — " + err.message); }
    setBusy(false);
  };

  if (showWizard) {
    return (
      <div style={{ background: "var(--bg)", color: "var(--ink)", fontFamily: "'JetBrains Mono', monospace", minHeight: "100vh", padding: "40px 24px" }}>
        <GuidedWizard
          onDone={async (p) => {
            // Same pipeline the other load paths use: apply to the live model, persist to
            // browser storage, THEN remount via onLoaded (which itself applies nothing).
            applyLoadedData({ portfolio: p.portfolio, expenses: p.expenses, incomeFromForm: true });
            await saveToStorage({ portfolio: p.portfolio, expenses: p.expenses });
            onLoaded();
          }}
          onCancel={() => setShowWizard(false)} />
      </div>
    );
  }
  return (
    <div style={{ background: "var(--bg)", color: "var(--ink)", fontFamily: "'JetBrains Mono', monospace", minHeight: "100vh", padding: 24 }}>
      <style>{`@keyframes pulse-ring { 0% { transform: translate(-50%,-50%) scale(1); opacity: 0.4; } 100% { transform: translate(-50%,-50%) scale(2); opacity: 0; } }`}</style>
      <div style={{ maxWidth: 720, margin: "0 auto" }}>
        <div style={{ fontSize: 18, fontWeight: 700, color: "var(--accent)", letterSpacing: 3, marginBottom: 4 }} className="lbl">DANGER CLOSE</div>
        <div style={{ fontSize: 10, color: "var(--ink-faint)", letterSpacing: 2, marginBottom: 24 }}>DATA LOAD │ v5.23</div>

        <div style={{ border: "1px solid var(--line)", padding: 18, marginBottom: 20, background: "rgba(0,255,136,0.02)" }}>
          <div style={{ fontSize: 10, color: "var(--ink)", lineHeight: 1.8 }}>
            Two ways in: <strong style={{ color: "var(--accent)" }}>start fresh</strong> and type your data into the My Data tab, or <strong style={{ color: "var(--info)" }}>restore a backup</strong> you exported earlier. Everything you enter is cached locally, so you won't be asked again next session. (You can also load the built-in example household to explore the app.) Hard on the eyes? Once you're in, the <strong style={{ color: "var(--info)" }}>Skins</strong> tab has seven themes — including light paper — and a UI size control.
          </div>
        </div>

        {error && <div style={{ color: "var(--crit)", fontSize: 10, marginBottom: 12 }}>ERROR: {error}</div>}

        <div style={{ display: "flex", gap: 10, justifyContent: "space-between", alignItems: "center", marginTop: 20, flexWrap: "wrap" }}>
          <div style={{ display: "flex", gap: 10 }}>
            <button
              disabled={busy}
              onClick={startFresh}
              style={{
                background: "rgba(0,255,136,0.12)", border: "1px solid var(--accent)", color: "var(--accent)",
                padding: "10px 16px", fontSize: 10, cursor: "pointer", fontFamily: "inherit", letterSpacing: 1, fontWeight: 600,
              }}
            >
              ✏ START FRESH — ENTER MY OWN DATA
            </button>
            <label style={{
              background: "transparent", border: "1px solid var(--info)", color: "var(--info)",
              padding: "10px 16px", fontSize: 10, cursor: "pointer", fontFamily: "inherit", letterSpacing: 1, display: "inline-block",
            }}>
              ↑ RESTORE FROM BACKUP
              <input type="file" accept="application/json,.json" style={{ display: "none" }}
                onChange={(e) => { const f = e.target.files?.[0]; if (f) restoreBackup(f); }} />
            </label>
          </div>
          <button
            disabled={busy}
            onClick={() => setShowWizard(true)}
            style={{
              background: "rgba(0,255,136,0.1)", border: "1px solid var(--accent)", color: "var(--accent)",
              padding: "10px 16px", fontSize: 10, fontWeight: 700, cursor: "pointer", fontFamily: "inherit", letterSpacing: 1,
            }}
          >
            🧭 GUIDED SETUP — BUILD MY OWN PLAN (3 MIN)
          </button>
          <button
            disabled={busy}
            onClick={() => applyAndContinue(true)}
            style={{
              background: "var(--panel2)", border: "1px solid var(--ink-dim)", color: "var(--ink)",
              padding: "10px 16px", fontSize: 10, fontWeight: 600, cursor: "pointer", fontFamily: "inherit", letterSpacing: 1,
            }}
          >
            {busy ? "LOADING..." : "USE EXAMPLE DATA"}
          </button>
        </div>

        <div style={{ fontSize: 10, color: "var(--ink)", marginTop: 32, textAlign: "center", lineHeight: 1.8 }}>
          No account, never shared. Everything you enter auto-saves privately in this browser on this device (clearing site data or switching browsers/devices erases it). The only time your data leaves this device is when you press ASK on the Ask AI tab — it sends the AI service a summary of your plan (totals, allocations, spending, income, settings, and projection results) plus your question and any files you attach, and only then.<br />
          Once you're in, use the Export / Import Backup buttons on the My Data tab to save or restore your plan.
        </div>
      </div>
    </div>
  );
}

const DOCS_HTML = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Danger Close — Field Manual</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Chakra+Petch:wght@400;500;600;700&family=Spline+Sans:wght@400;500;600&family=JetBrains+Mono:wght@400;500&display=swap\" rel=\"stylesheet\">\n<style>\n  :root{\n    --bg:#070b09; --bg2:#0b130f; --panel:#0d1611; --panel2:#101c15;\n    --line:#1a3a2a; --line2:#27513a;\n    --green:#00ff88; --green-dim:#3a7a5a; --amber:#ffaa00; --red:#ff4444; --cyan:#00ccff; --violet:#aa66ff; --orange:#ff6600;\n    --ink:#c0d8cc; --ink-dim:#6a8a7a; --ink-faint:#3a7a5a;\n    --mono:'JetBrains Mono',monospace; --disp:'Chakra Petch',sans-serif; --body:'Spline Sans',sans-serif;\n  }\n  *{box-sizing:border-box}\n  html{scroll-behavior:smooth}\n  body{\n    margin:0; background:#070b09; color:var(--ink); font-family:var(--body); font-size:15px; line-height:1.7;\n    background-image:\n      radial-gradient(circle at 15% 10%, rgba(0,255,136,0.05), transparent 40%),\n      radial-gradient(circle at 85% 90%, rgba(0,204,255,0.04), transparent 45%),\n      repeating-linear-gradient(0deg, transparent, transparent 2px, rgba(0,255,136,0.012) 3px, transparent 4px);\n  }\n  a{color:var(--cyan); text-decoration:none}\n  a:hover{text-decoration:underline}\n  .wrap{max-width:1000px; margin:0 auto; padding:0 22px}\n\n  /* ── HERO ── */\n  header.hero{\n    position:relative; padding:70px 0 46px; border-bottom:1px solid var(--line); overflow:hidden;\n    background:linear-gradient(180deg, rgba(0,255,136,0.04), transparent);\n  }\n  .reticle{position:absolute; top:50%; right:-60px; transform:translateY(-50%); width:340px; height:340px; opacity:.13; pointer-events:none}\n  .callsign{font-family:var(--mono); font-size:11px; letter-spacing:5px; color:var(--green-dim); margin-bottom:14px}\n  .byline{position:absolute; top:18px; right:22px; z-index:3; font-family:var(--mono); font-size:11px; letter-spacing:2px; color:var(--green-dim)}\n  h1{font-family:var(--disp); font-weight:700; font-size:62px; line-height:.95; margin:0 0 8px; letter-spacing:1px;\n     color:var(--green); text-shadow:0 0 30px rgba(0,255,136,0.25)}\n  h1 .lo{color:var(--ink); display:block; font-size:20px; letter-spacing:8px; font-weight:500; margin-top:12px}\n  .tagline{font-size:17px; color:var(--ink-dim); max-width:620px; margin-top:18px}\n  .meta-strip{display:flex; gap:26px; flex-wrap:wrap; margin-top:26px; font-family:var(--mono); font-size:11px; color:var(--green-dim)}\n  .meta-strip b{color:var(--ink); font-weight:500}\n\n  /* ── SECTION ── */\n  section{padding:46px 0; border-bottom:1px solid var(--line)}\n  h2{font-family:var(--disp); font-weight:600; font-size:30px; color:var(--green); margin:0 0 6px; letter-spacing:.5px;\n     display:flex; flex-wrap:wrap; align-items:center; gap:12px}\n  h2 .num{font-family:var(--mono); font-size:13px; color:var(--green-dim); border:1px solid var(--line2); padding:3px 8px; border-radius:3px}\n  h3{font-family:var(--disp); font-weight:600; font-size:20px; color:var(--ink); margin:30px 0 8px; letter-spacing:.3px}\n  h4{font-family:var(--disp); font-weight:600; font-size:15px; color:var(--amber); margin:18px 0 4px; letter-spacing:.5px; text-transform:uppercase}\n  p{margin:10px 0}\n  .lead{font-size:16px; color:var(--ink)}\n  strong{color:#e6f4ec; font-weight:600}\n  em{color:var(--ink-dim)}\n  code{font-family:var(--mono); font-size:.86em; background:rgba(0,255,136,0.07); border:1px solid var(--line); padding:1px 6px; border-radius:3px; color:var(--green)}\n\n  /* ── CARDS / HUD ── */\n  .card{position:relative; background:var(--panel); border:1px solid var(--line); border-radius:4px; padding:20px 22px; margin:16px 0}\n  .card::before,.card::after{content:\"\"; position:absolute; width:10px; height:10px; border:1.5px solid var(--green-dim)}\n  .card::before{top:-1px; left:-1px; border-right:0; border-bottom:0}\n  .card::after{bottom:-1px; right:-1px; border-left:0; border-top:0}\n  .danger{border-color:var(--red); background:linear-gradient(180deg, rgba(255,68,68,0.07), rgba(255,68,68,0.02))}\n  .danger::before,.danger::after{border-color:var(--red)}\n  .danger h3{color:var(--red)}\n  .note{border-left:3px solid var(--green); background:rgba(0,255,136,0.04); padding:14px 18px; margin:16px 0; border-radius:0 4px 4px 0}\n  .warn{border-left:3px solid var(--amber); background:rgba(255,170,0,0.05)}\n  .crit{border-left:3px solid var(--red); background:rgba(255,68,68,0.05)}\n\n  ul,ol{margin:10px 0; padding-left:22px}\n  li{margin:6px 0}\n  ul.tight li{margin:3px 0}\n\n  /* ── TABLES ── */\n  table{width:100%; border-collapse:collapse; margin:16px 0; font-size:13.5px}\n  th{font-family:var(--mono); font-size:10px; letter-spacing:1px; text-transform:uppercase; color:var(--ink-dim);\n     text-align:left; padding:9px 11px; background:rgba(0,255,136,0.05); border:1px solid var(--line)}\n  td{padding:9px 11px; border:1px solid var(--line); vertical-align:top; color:var(--ink)}\n  tr:nth-child(even) td{background:rgba(255,255,255,0.012)}\n\n  /* ── TOC ── */\n  .toc{columns:2; column-gap:40px; font-family:var(--mono); font-size:13px}\n  .toc a{display:block; padding:5px 0; color:var(--ink-dim); border-bottom:1px dotted var(--line)}\n  .toc a:hover{color:var(--green); text-decoration:none}\n  .toc .sub{padding-left:18px; font-size:12px}\n\n  /* ── BACK-TO-TOC LINK (sits at the right of every section heading) ── */\n  h2 .toclink{margin-left:auto; font-family:var(--mono); font-size:10px; font-weight:400; letter-spacing:1px;\n    color:var(--ink-faint); border:1px solid var(--line2); padding:5px 10px; border-radius:3px; text-transform:uppercase; white-space:nowrap}\n  h2 .toclink:hover{color:var(--green); border-color:var(--green-dim); background:rgba(0,255,136,0.05); text-decoration:none}\n  .totop-foot{display:inline-block; margin-top:20px; font-family:var(--mono); font-size:11px; letter-spacing:1px;\n    color:var(--ink-faint); border:1px solid var(--line2); padding:7px 13px; border-radius:3px; text-transform:uppercase}\n  .totop-foot:hover{color:var(--green); border-color:var(--green-dim); background:rgba(0,255,136,0.05); text-decoration:none}\n\n  /* ── PLAIN-ENGLISH CALLOUT (for readers who aren't finance pros) ── */\n  .plain{border-left:3px solid var(--cyan); background:rgba(0,204,255,0.05); padding:14px 18px; margin:18px 0; border-radius:0 4px 4px 0}\n  .plain .lbl{display:block; font-family:var(--mono); font-size:10px; letter-spacing:2px; color:var(--cyan); text-transform:uppercase; margin-bottom:7px}\n  .plain p{margin:6px 0}\n  .plain .analogy{color:var(--ink-dim); font-style:italic}\n\n  /* ── TAB MAP ── */\n  .tabmap{display:grid; grid-template-columns:repeat(auto-fit,minmax(150px,1fr)); gap:14px; margin:20px 0}\n  .tabgroup{border:1px solid var(--line); border-radius:4px; padding:14px; background:var(--panel)}\n  .tabgroup .glabel{font-family:var(--mono); font-size:10px; letter-spacing:2px; text-transform:uppercase; margin-bottom:10px; padding-bottom:6px; border-bottom:1px solid var(--line)}\n  .tabchip{display:block; font-family:var(--disp); font-size:13px; padding:5px 9px; margin:5px 0; border-radius:3px;\n           background:rgba(255,255,255,0.02); border-left:2px solid; color:var(--ink)}\n\n  /* ── TAB ENTRIES ── */\n  .tabentry{border:1px solid var(--line); border-radius:4px; margin:14px 0; padding:16px 20px; background:var(--panel)}\n  .tabentry h3{margin:0 0 4px; display:flex; align-items:center; gap:10px}\n  .tabentry h3 .tag{font-family:var(--mono); font-size:9px; letter-spacing:1px; padding:2px 7px; border-radius:3px; text-transform:uppercase}\n  .tabentry .purpose{color:var(--green); font-size:14px; margin:0 0 10px}\n  .tabentry .micro{font-family:var(--mono); font-size:11px; color:var(--ink-faint); margin-top:8px}\n\n  .pillrow{display:flex; gap:8px; flex-wrap:wrap; margin:8px 0}\n  .pill{font-family:var(--mono); font-size:10px; letter-spacing:.5px; padding:3px 9px; border:1px solid var(--line2); border-radius:20px; color:var(--ink-dim)}\n\n  figure{margin:24px 0; text-align:center}\n  figure svg{max-width:100%; height:auto}\n  figcaption{font-family:var(--mono); font-size:11px; color:var(--ink-faint); margin-top:8px; letter-spacing:.5px}\n\n  .glossary{column-count:2; column-gap:34px; font-size:13px}\n  .glossary .term{break-inside:avoid; margin:0 0 11px}\n  .glossary .term b{font-family:var(--disp); color:var(--green); font-weight:600}\n  @media(max-width:760px){ h1{font-size:42px} .toc,.glossary{column-count:1} .reticle{display:none} }\n\n  footer{padding:40px 0 60px; color:var(--ink-faint); font-size:12px; font-family:var(--mono)}\n  .kicker{font-family:var(--mono); font-size:11px; letter-spacing:3px; color:var(--green-dim); text-transform:uppercase; margin-bottom:4px}\n</style>\n</head>\n<body>\n\n<header class=\"hero\">\n  <div class=\"byline\">Steve T. · built with AI assistance, constants verified against IRS/CMS/SSA · 2026 · not financial advice</div>\n  <svg class=\"reticle\" viewBox=\"0 0 200 200\" fill=\"none\" stroke=\"#00ff88\" stroke-width=\"1\">\n    <circle cx=\"100\" cy=\"100\" r=\"90\"/><circle cx=\"100\" cy=\"100\" r=\"60\"/><circle cx=\"100\" cy=\"100\" r=\"30\"/>\n    <line x1=\"100\" y1=\"0\" x2=\"100\" y2=\"200\"/><line x1=\"0\" y1=\"100\" x2=\"200\" y2=\"100\"/>\n    <circle cx=\"100\" cy=\"100\" r=\"4\" fill=\"#00ff88\"/>\n  </svg>\n  <div class=\"wrap\">\n    <div class=\"callsign\">// FIELD MANUAL · v5.23 · PUBLIC BUILD</div>\n    <h1>DANGER CLOSE<span class=\"lo\">RETIREMENT STRESS-TEST CONSOLE</span></h1>\n    <p class=\"tagline\">A single-page tool that runs Monte Carlo simulations, historical backtests, and stress tests against your own portfolio — built to pressure-test a real retirement plan when the stakes are highest.</p>\n    <div class=\"meta-strip\">\n      <span>STATUS · <b>OPERATIONAL</b></span>\n      <span>TABS · <b>26</b></span>\n      <span>ENGINE · <b>REGIME-SWITCHING MC</b></span>\n      <span>DATA · <b>LOCAL / IN-BROWSER</b></span>\n    </div>\n  </div>\n</header>\n\n<!-- DISCLAIMER -->\n<section>\n  <div class=\"wrap\">\n    <div class=\"card danger\">\n      <h3>⚠ READ BEFORE USING — THIS IS NOT FINANCIAL ADVICE</h3>\n      <p>This software is provided for <strong>educational and entertainment purposes only</strong>. It is not financial, investment, tax, or legal advice.</p>\n      <ul class=\"tight\">\n        <li><strong>The author has no professional financial credentials</strong> — not a CFP, CFA, CPA, Enrolled Agent, or attorney, and has no formal training in finance, tax, or investment management. This is an amateur hobby project.</li>\n        <li><strong>Do not rely on this app to make any financial decision.</strong> Every projection is an estimate from simplified models that may contain bugs, errors, or omissions. Real markets, tax law, and life will differ — possibly by a lot.</li>\n        <li><strong>No fiduciary relationship, no warranty, no liability.</strong> The software is provided \"AS IS.\" You are responsible for your own decisions.</li>\n        <li><strong>Past performance does not predict the future.</strong> Real outcomes can be materially worse than the worst case shown.</li>\n        <li>The embedded AI assistant can be confidently wrong. Tax and law assumptions go stale. Peer rankings are approximate.</li>\n      </ul>\n      <p style=\"margin-bottom:0\">Before acting on anything here, consult a fee-only fiduciary advisor, a CPA, and an estate attorney, and verify every number against authoritative sources (IRS, SSA, your custodian). See the <a href=\"#final\">Final Disclaimer</a>.</p>\n    </div>\n  </div>\n</section>\n\n<!-- TOC -->\n<section id=\"toc\">\n  <div class=\"wrap\">\n    <h2><span class=\"num\">00</span> Table of Contents</h2>\n    <div class=\"toc\">\n      <a href=\"#what\">01 · What Danger Close Does</a>\n      <a href=\"#flow\">02 · How Data Flows Through It</a>\n      <a href=\"#start\">03 · Getting Started</a>\n      <a href=\"#banner\">04 · The Data-Integrity Warning Banner</a>\n      <a href=\"#map\">05 · The 26 Tabs at a Glance</a>\n      <a href=\"#controls\">06 · Top-Level Controls &amp; Modeling Approach</a>\n      <a href=\"#tabs\">07 · The Tabs in Detail</a>\n      <a href=\"#g-foundation\" class=\"sub\">Foundation · Scoring</a>\n      <a href=\"#g-strategy\" class=\"sub\">Strategy · Testing · Tools</a>\n      <a href=\"#xlsx\">08 · Entering Your Data (My Data tab)</a>\n      <a href=\"#docx\">09 · The Master Prompt &amp; AI Context</a>\n      <a href=\"#apikey\">10 · Ask AI &amp; Your API Key (Self-Hosted Copies)</a>\n      <a href=\"#reload\">11 · Reloading &amp; Resetting</a>\n      <a href=\"#hsa\">12 · HSA Contributions &amp; the Medicare Cutoff</a>\n      <a href=\"#limits\">13 · Limitations &amp; Known Issues</a>\n      <a href=\"#faq\">14 · Troubleshooting &amp; FAQ</a>\n      <a href=\"#glossary\">15 · Glossary</a>\n      <a href=\"#final\">16 · Final Disclaimer</a>\n    </div>\n  </div>\n</section>\n\n<!-- WHAT IT DOES -->\n<section id=\"what\">\n  <div class=\"wrap\">\n    <h2><span class=\"num\">01</span> What Danger Close Does <a class=\"toclink\" href=\"#toc\">↑ Contents</a></h2>\n    <div class=\"plain\">\n      <span class=\"lbl\">In plain English — start here</span>\n      <p>Picture your retirement as one long road trip where nobody can tell you the weather ahead of time. <strong>This app drives that whole trip thousands of times.</strong> Some runs get sunshine (strong markets); some hit storms (a crash, years of high inflation, a long illness). Each run, it checks whether you still have money when the trip ends.</p>\n      <p class=\"analogy\">So when you see \"success rate 90%,\" it means: across 10,000 imagined futures, your savings lasted in about 9,000 of them. Think of it as a weather forecast for your money — useful odds, never a promise.</p>\n    </div>\n    <p class=\"lead\">At its core, the app does six things, all locally in your browser:</p>\n    <ol>\n      <li><strong>Holds your portfolio and household context</strong> — positions, balances, Roth/Traditional split, asset classes, names, DOBs, Social Security, pension, housing, goals — which you type into the <strong>My Data</strong> tab or restore from a saved backup file.</li>\n      <li><strong>Runs Monte Carlo simulations</strong> at the asset-class level using six probability-weighted economic regimes (base, optimistic, pessimistic, recession, stagflation, crisis) at 5,000–10,000 iterations.</li>\n      <li><strong>Models the retirement transition</strong> quarter-by-quarter through year 30 — Social Security claiming, pension start, Roth conversions, home sale and cash purchase, Medicare and the ACA bridge, and long-term care.</li>\n      <li><strong>Builds a withdrawal schedule</strong> — a year-by-year plan of which account funds each year's spending, with account-priority sequencing.</li>\n      <li><strong>Stress-tests the plan</strong> against named adverse scenarios and reverse-solves for the break-points.</li>\n      <li><strong>Provides an Ask AI tab</strong> that sends a structured summary to an AI assistant for natural-language follow-up.</li>\n    </ol>\n    <div class=\"note\">This tool assumes you already have a retirement plan and want to pressure-test it. It is <em>not</em> a \"what is a 401(k)\" tool. Nothing is uploaded to any server except the calls you explicitly send from the Ask AI tab.</div>\n    <figure>\n      <svg viewBox=\"0 0 760 285\" font-family=\"'JetBrains Mono',monospace\">\n        <line x1=\"70\" y1=\"30\" x2=\"70\" y2=\"230\" stroke=\"#1a3a2a\"/>\n        <line x1=\"70\" y1=\"230\" x2=\"660\" y2=\"230\" stroke=\"#1a3a2a\"/>\n        <text x=\"62\" y=\"36\" fill=\"#6a8a7a\" font-size=\"10\" text-anchor=\"end\">MONEY</text>\n        <text x=\"70\" y=\"250\" fill=\"#6a8a7a\" font-size=\"10\">RETIRE</text>\n        <text x=\"660\" y=\"250\" fill=\"#6a8a7a\" font-size=\"10\" text-anchor=\"end\">END OF PLAN</text>\n        <line x1=\"70\" y1=\"185\" x2=\"660\" y2=\"185\" stroke=\"#27513a\" stroke-dasharray=\"4 4\"/>\n        <text x=\"664\" y=\"189\" fill=\"#6a8a7a\" font-size=\"9\">\"not broke\" line</text>\n        <path d=\"M70,150 C240,135 400,108 660,82\" fill=\"none\" stroke=\"#3a7a5a\" stroke-width=\"1\" opacity=\"0.55\"/>\n        <path d=\"M70,150 C240,158 400,168 660,150\" fill=\"none\" stroke=\"#3a7a5a\" stroke-width=\"1\" opacity=\"0.55\"/>\n        <path d=\"M70,150 C240,166 400,192 645,228\" fill=\"none\" stroke=\"#7a3a3a\" stroke-width=\"1\" opacity=\"0.55\"/>\n        <path d=\"M70,150 C220,120 360,80 660,46\" fill=\"none\" stroke=\"#00ff88\" stroke-width=\"2\"/>\n        <text x=\"664\" y=\"49\" fill=\"#00ff88\" font-size=\"9\">good markets</text>\n        <path d=\"M70,150 C240,150 420,138 660,120\" fill=\"none\" stroke=\"#ffaa00\" stroke-width=\"2\"/>\n        <text x=\"664\" y=\"123\" fill=\"#ffaa00\" font-size=\"9\">typical</text>\n        <path d=\"M70,150 C210,176 360,206 545,229\" fill=\"none\" stroke=\"#ff4444\" stroke-width=\"2\"/>\n        <text x=\"540\" y=\"221\" fill=\"#ff4444\" font-size=\"9\" text-anchor=\"end\">runs out ✗</text>\n        <text x=\"365\" y=\"278\" fill=\"#6a8a7a\" font-size=\"10\" text-anchor=\"middle\">one starting portfolio · 10,000 different futures · success = the share that finish above the line</text>\n      </svg>\n      <figcaption>FIG.0 — WHAT A \"MONTE CARLO\" ACTUALLY DOES</figcaption>\n    </figure>\n    <div class=\"note\">\n      <strong>Why \"Danger Close\"?</strong> In artillery, <em>danger close</em> is the call that supporting fire is landing near your own position — the moment that demands maximum precision because the stakes are highest. That's the metaphor, and the whole reason this tool exists: the years surrounding retirement are when a financial mistake lands closest to home, and the math deserves artillery-grade care. To be clear about the styling: the author is a civilian, has never served in the military, and claims no service — the name and the console aesthetic are a design theme borrowed with respect for what the term means.\n    </div>\n  \n    <h3>What's new in v5.7 / v5.7.1 (this build)</h3>\n    <p><em>v5.7.1:</em> the Roth <strong>break-even rebuilt</strong> as a wealth-crossover computed by the full 30-year engine (discounting and the opportunity cost of conversion tax included; <em>does not break even</em> is now a possible answer), a guard on the pension field against lump-sum entry, a notice when conversion-tax funding cannot be honored, the Mixed holdings label clarified to <em>Trad + Roth (split)</em>, and a stale Taxes-tab disclaimer corrected. <em>v5.7:</em> the headline changes: <strong>ACA premium-subsidy modeling</strong> on the Roth tab (bridge-year subsidy losses per strategy, a STAY UNDER ACA CLIFF solver, and a current-law-vs-enhanced scenario toggle — see the tab entry in §07); a <strong>🧭 Guided Setup wizard</strong> (landing screen + My Data) that builds a working plan from six questions; <strong>Simple Mode</strong> (six core tabs, one-click switch, remembered); a <strong>Dashboard</strong> tab answering the three questions retirees actually ask, now the default landing view; a <strong>51-jurisdiction state-tax model</strong>; Roth upgrades — a 25-cell <strong>solve-for optimizer</strong> and a <strong>conversion-tax funding</strong> model (cash vs appreciated-brokerage sale vs withholding from the conversion); Social Security upgrades — <strong>breakeven cards for both spouses</strong> (with the first-death horizon twist for the lower earner) and an <strong>81-cell joint claiming-age grid</strong>; Monte Carlo engine toggles for <strong>stochastic longevity</strong> and a realistic <strong>LTC duration distribution</strong> (§06 explains both); a threaded, memory-keeping <strong>Ask AI conversation</strong> with an <strong>Offline Mode</strong> hard switch and a <strong>local-model option</strong>; a first-class <strong>Other Income Streams</strong> module (rental, post-retirement work, annuities — flows through every engine); an <strong>SS trust-fund depletion scenario</strong> toggle on the SS tab; a <strong>data-vintage staleness system</strong> (§13); a first-open rendering bug fixed; the Compare tab and the FICO field retired; and a 53-check validation suite asserting every statutory constant against IRS/CMS/SSA/HHS sources.</p>\n</div>\n</section>\n\n<!-- DATA FLOW -->\n<section id=\"flow\">\n  <div class=\"wrap\">\n    <h2><span class=\"num\">02</span> How Data Flows Through It <a class=\"toclink\" href=\"#toc\">↑ Contents</a></h2>\n    <p>Everything starts from <strong>one in-memory model</strong> (<code>PORTFOLIO</code> + <code>PLAN_TIMELINE</code>), and every tab derives its numbers from that single source. You fill that model one of three ways: <strong>type your data</strong> into the My Data tab, <strong>restore a backup</strong> you exported earlier (a JSON file), or <strong>load the example household</strong> to explore. Whatever you enter is saved privately between visits so the app reopens to your plan, and you can export it to a JSON file to keep or move between devices. Nothing is ever shared, and the only transmission of plan data is the summary the <a href=\"#tabs\">Ask AI</a> tab sends when you explicitly ask a question.</p>\n    <div class=\"plain\">\n      <span class=\"lbl\">In plain English</span>\n      <p>There's no account and nothing to sign up for. The app keeps one private copy of your plan just for you. You either type it in or hand it a backup file you saved before — and everything else you see, every tab, chart, and score, is calculated from that one copy on the spot. Nobody else ever sees it; the only thing that transmits anything is the Ask AI tab, when you press ask.</p>\n    </div>\n    <figure>\n      <svg viewBox=\"0 0 920 360\" font-family=\"'JetBrains Mono',monospace\">\n        <defs>\n          <marker id=\"ar\" markerWidth=\"9\" markerHeight=\"9\" refX=\"7\" refY=\"4.5\" orient=\"auto\"><path d=\"M0,0 L9,4.5 L0,9 z\" fill=\"#3a7a5a\"/></marker>\n        </defs>\n        <rect x=\"20\" y=\"28\" width=\"214\" height=\"48\" rx=\"4\" fill=\"#0d1611\" stroke=\"#00ccff\"/>\n        <text x=\"127\" y=\"49\" fill=\"#00ccff\" font-size=\"12\" text-anchor=\"middle\">My Data tab</text>\n        <text x=\"127\" y=\"66\" fill=\"#6a8a7a\" font-size=\"9\" text-anchor=\"middle\">you type it in</text>\n        <rect x=\"20\" y=\"92\" width=\"214\" height=\"48\" rx=\"4\" fill=\"#0d1611\" stroke=\"#00ccff\"/>\n        <text x=\"127\" y=\"113\" fill=\"#00ccff\" font-size=\"12\" text-anchor=\"middle\">Restore backup</text>\n        <text x=\"127\" y=\"130\" fill=\"#6a8a7a\" font-size=\"9\" text-anchor=\"middle\">a .json file you saved</text>\n        <rect x=\"20\" y=\"156\" width=\"214\" height=\"48\" rx=\"4\" fill=\"#0d1611\" stroke=\"#27513a\"/>\n        <text x=\"127\" y=\"177\" fill=\"#c0d8cc\" font-size=\"12\" text-anchor=\"middle\">Example household</text>\n        <text x=\"127\" y=\"194\" fill=\"#6a8a7a\" font-size=\"9\" text-anchor=\"middle\">explore with demo data</text>\n        <rect x=\"340\" y=\"78\" width=\"200\" height=\"96\" rx=\"4\" fill=\"#101c15\" stroke=\"#00ff88\"/>\n        <text x=\"440\" y=\"110\" fill=\"#00ff88\" font-size=\"12\" text-anchor=\"middle\">PORTFOLIO +</text>\n        <text x=\"440\" y=\"127\" fill=\"#00ff88\" font-size=\"12\" text-anchor=\"middle\">PLAN_TIMELINE</text>\n        <text x=\"440\" y=\"148\" fill=\"#6a8a7a\" font-size=\"9\" text-anchor=\"middle\">one source of truth ·</text>\n        <text x=\"440\" y=\"161\" fill=\"#6a8a7a\" font-size=\"9\" text-anchor=\"middle\">derives all dates/ages</text>\n        <rect x=\"648\" y=\"78\" width=\"160\" height=\"96\" rx=\"4\" fill=\"#0d1611\" stroke=\"#27513a\"/>\n        <text x=\"728\" y=\"118\" fill=\"#c0d8cc\" font-size=\"13\" text-anchor=\"middle\">25 TABS</text>\n        <text x=\"728\" y=\"140\" fill=\"#6a8a7a\" font-size=\"9\" text-anchor=\"middle\">all read the</text>\n        <text x=\"728\" y=\"153\" fill=\"#6a8a7a\" font-size=\"9\" text-anchor=\"middle\">same model</text>\n        <line x1=\"234\" y1=\"52\" x2=\"338\" y2=\"108\" stroke=\"#3a7a5a\" marker-end=\"url(#ar)\"/>\n        <line x1=\"234\" y1=\"116\" x2=\"338\" y2=\"124\" stroke=\"#3a7a5a\" marker-end=\"url(#ar)\"/>\n        <line x1=\"234\" y1=\"180\" x2=\"338\" y2=\"142\" stroke=\"#3a7a5a\" marker-end=\"url(#ar)\"/>\n        <line x1=\"540\" y1=\"126\" x2=\"646\" y2=\"126\" stroke=\"#3a7a5a\" marker-end=\"url(#ar)\"/>\n        <rect x=\"300\" y=\"250\" width=\"448\" height=\"78\" rx=\"4\" fill=\"rgba(0,255,136,0.05)\" stroke=\"#27513a\" stroke-dasharray=\"4 3\"/>\n        <text x=\"524\" y=\"278\" fill=\"#00ff88\" font-size=\"11\" text-anchor=\"middle\">SAVED PRIVATELY · YOURS ALONE</text>\n        <text x=\"524\" y=\"298\" fill=\"#6a8a7a\" font-size=\"9\" text-anchor=\"middle\">reopens to your plan next visit · Export / Import a .json backup</text>\n        <text x=\"524\" y=\"313\" fill=\"#6a8a7a\" font-size=\"9\" text-anchor=\"middle\">to keep it or move between devices · never shared with anyone</text>\n        <line x1=\"440\" y1=\"174\" x2=\"440\" y2=\"248\" stroke=\"#27513a\" stroke-dasharray=\"4 3\" marker-end=\"url(#ar)\"/>\n      </svg>\n      <figcaption>FIG.1 — HOW YOUR DATA MOVES (TYPED OR RESTORED · STAYS PRIVATE)</figcaption>\n    </figure>\n    <p class=\"micro\" style=\"font-family:var(--mono);font-size:11px;color:var(--ink-faint)\">Because every tab derives from one model, the app is fully portable: load a different household and every visible number re-derives. Income figures route through single accessors, so there are no scattered hard-coded values.</p>\n  </div>\n</section>\n\n<!-- GETTING STARTED -->\n<section id=\"start\">\n  <div class=\"wrap\">\n    <h2><span class=\"num\">03</span> Getting Started <a class=\"toclink\" href=\"#toc\">↑ Contents</a></h2>\n    <p>All you need is a current browser. On first open you'll see the <strong>landing screen</strong>, which offers three ways to begin:</p>\n    <table>\n      <tr><th>Choice</th><th>What it does</th><th>Best for</th></tr>\n      <tr><td><strong>\ud83e\udded Guided Setup</strong></td><td>Six friendly questions (who, when, money, income, spending, state) build a complete working plan in about three minutes. Also launchable anytime from the My Data tab's 🧭 GUIDED SETUP button — building replaces the current plan; cancelling changes nothing — rough answers welcome, everything editable later in My Data. Finishing starts you in <strong>Simple Mode</strong> (below).</td><td>Your very first plan</td></tr>\n      <tr><td><strong>✏ Start Fresh</strong></td><td>Opens an empty plan; you type your household, holdings, income, and expenses into the My Data tab, then press <strong>Save &amp; Apply</strong>.</td><td>Your first real run</td></tr>\n      <tr><td><strong>↑ Restore from Backup</strong></td><td>Reads a <code>.json</code> backup you exported earlier and rebuilds every tab from it.</td><td>Returning, or new device</td></tr>\n      <tr><td><strong>Use Example Data</strong></td><td>Loads the built-in demo household so you can explore every tab with realistic numbers.</td><td>Kicking the tires</td></tr>\n    </table>\n    <p>After you Save &amp; Apply (or restore a backup), the app <strong>caches your plan in the browser</strong>, so the next visit skips the landing screen and reopens straight to your data. From the My Data tab you can <strong>Export Backup</strong> at any time to save a durable <code>.json</code> copy, and <strong>Clear All Data</strong> to wipe the cache and start over.</p>\n    <div class=\"note\"><strong>Export a backup regularly.</strong> The browser cache is convenient but not permanent — clearing browser data or switching devices loses it. The exported <code>.json</code> file is the durable copy; it carries your whole plan (holdings, income, expenses, the AI context, your estate checklist, and your chosen theme). Curious where your data actually lives — and how to prove the file itself stores nothing? <a href=\"#reload\">§11</a> includes tests you can run yourself.</div>\n  </div>\n</section>\n\n<!-- WARNING BANNER -->\n<section id=\"banner\">\n  <div class=\"wrap\">\n    <h2><span class=\"num\">04</span> The Data-Integrity Warning Banner <a class=\"toclink\" href=\"#toc\">↑ Contents</a></h2>\n    <p>To keep the app from quietly showing you someone else's numbers, it tracks where each income figure (Social Security, pension) came from. A banner appears at the top of every tab in two flavors — and understanding <em>when each one can fire</em> tells you how the protection actually works:</p>\n    <div class=\"card crit\" style=\"border-radius:4px\">\n      <h4 style=\"color:var(--red);margin-top:0\">⚠ WARNING — USING EXAMPLE NUMBERS, NOT YOUR DATA (red)</h4>\n      <p style=\"margin:6px 0\">Fires when your plan arrived <em>without income figures of its own</em> — typically an older backup, or a plan saved before the My Data income section existed — and the app had to substitute the demo household's numbers to keep the engines running. It names exactly which fields were substituted (e.g. \"Spouse B Social Security, Pension\") and includes a small diagnostics line showing what it looked for and what it found. Until you enter the real amounts in <strong>My Data → Income</strong> and press Save &amp; Apply, every projection that uses income — taxes, IRMAA, survivor, withdrawals — is unreliable.</p>\n    </div>\n    <div class=\"card warn\" style=\"border-radius:4px\">\n      <h4 style=\"color:var(--amber);margin-top:0\">ⓘ EXAMPLE DATA MODE (amber)</h4>\n      <p style=\"margin:6px 0\">The gentle version. Fires when you deliberately chose \"Use Example Data.\" All figures are illustrative placeholders; no alarm needed.</p>\n    </div>\n    <p><strong>What about income you simply haven't entered yet?</strong> That's the third case, and it works differently by design: an income field left blank in My Data is saved as an honest <strong>$0</strong> — the app never swaps a demo number in behind your form entries. A zero is your number, just probably not your <em>final</em> number, so instead of a banner you'll see it plainly as $0 on the Income tab and in the header's income floor. The red banner is reserved for the genuinely dangerous case: figures that <em>look</em> real but belong to the demo household.</p>\n    <p>When your own numbers are all in place, <strong>no banner appears</strong> — the check costs nothing day-to-day but flags instantly if a demo figure ever stands in for yours.</p>\n  </div>\n</section>\n\n<!-- TAB MAP -->\n<section id=\"map\">\n  <div class=\"wrap\">\n    <h2><span class=\"num\">05</span> The 26 Tabs at a Glance <a class=\"toclink\" href=\"#toc\">↑ Contents</a></h2>\n    <p>Tabs are grouped by function. Color marks the family; detail on each is in section <a href=\"#tabs\">07</a>. Feeling like 25 is a lot? The <strong>◑ SHOW FEWER TABS</strong> switch at the end of the tab strip turns on <strong>Simple Mode</strong> — just the six core tabs (My Data, Dashboard, Trajectory, Monte Carlo, SS, Docs) — and remembers your choice. Guided Setup starts new plans there automatically; the full set is always one click away.</p>\n    <div class=\"tabmap\">\n      <div class=\"tabgroup\">\n        <div class=\"glabel\" style=\"color:#00ccff\">FOUNDATION</div>\n        <span class=\"tabchip\" style=\"border-color:#00ccff\">Dashboard</span>\n        <span class=\"tabchip\" style=\"border-color:#00ccff\">My Data</span>\n        <span class=\"tabchip\" style=\"border-color:#00ccff\">Trajectory</span>\n        <span class=\"tabchip\" style=\"border-color:#00ccff\">Expenses</span>\n        <span class=\"tabchip\" style=\"border-color:#00ccff\">Income</span>\n        <span class=\"tabchip\" style=\"border-color:#00ccff\">SS</span>\n        <span class=\"tabchip\" style=\"border-color:#00ccff\">Positions</span>\n      </div>\n      <div class=\"tabgroup\">\n        <div class=\"glabel\" style=\"color:#aa66ff\">SCORING</div>\n        <span class=\"tabchip\" style=\"border-color:#aa66ff\">Grade</span>\n        <span class=\"tabchip\" style=\"border-color:#aa66ff\">Ranking</span>\n      </div>\n      <div class=\"tabgroup\">\n        <div class=\"glabel\" style=\"color:#ffaa00\">STRATEGY</div>\n        <span class=\"tabchip\" style=\"border-color:#ffaa00\">Guardrails</span>\n        <span class=\"tabchip\" style=\"border-color:#ffaa00\">Withdrawal</span>\n        <span class=\"tabchip\" style=\"border-color:#ffaa00\">Roth</span>\n        <span class=\"tabchip\" style=\"border-color:#ffaa00\">Taxes</span>\n        <span class=\"tabchip\" style=\"border-color:#ffaa00\">IRMAA</span>\n        <span class=\"tabchip\" style=\"border-color:#ffaa00\">Exit Plan</span>\n      </div>\n      <div class=\"tabgroup\">\n        <div class=\"glabel\" style=\"color:#ff6600\">TESTING</div>\n        <span class=\"tabchip\" style=\"border-color:#ff6600\">Monte Carlo</span>\n        <span class=\"tabchip\" style=\"border-color:#ff6600\">Backtest</span>\n        <span class=\"tabchip\" style=\"border-color:#ff6600\">What Breaks</span>\n        <span class=\"tabchip\" style=\"border-color:#ff6600\">Survivor</span>\n        <span class=\"tabchip\" style=\"border-color:#ff6600\">Stress</span>\n      </div>\n      <div class=\"tabgroup\">\n        <div class=\"glabel\" style=\"color:#ff4444\">TOOLS</div>\n        <span class=\"tabchip\" style=\"border-color:#ff4444\">Ask AI</span><span class='tabchip' style='border-color:#00ccff'>Checklist</span><span class='tabchip' style='border-color:#6a8a7a'>Skins</span><span class='tabchip' style='border-color:#6a8a7a'>Docs</span><span class='tabchip' style='border-color:#aa66ff'>Verify</span><span class='tabchip' style='border-color:#ffaa00'>Events</span>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- CONTROLS + MODELING -->\n<section id=\"controls\">\n  <div class=\"wrap\">\n    <h2><span class=\"num\">06</span> Top-Level Controls &amp; Modeling Approach <a class=\"toclink\" href=\"#toc\">↑ Contents</a></h2>\n    <h3>Controls</h3>\n    <ul>\n      <li><strong>Retirement Date Selector</strong> — switches the modeled retirement quarter; recomputes the whole plan.</li>\n      <li><strong>Scenario Prior Selector</strong> — BASE / BEAR-LEANING / BULL-LEANING. Re-weights the six economic regimes feeding the Monte Carlo.</li>\n      <li><strong>Roth Conversion Amount (Roth tab)</strong> — $0–$400,000 (step $5,000), default $70,000/yr. The single biggest lever: it drives <em>four</em> tabs at once — Roth ladder, Withdrawal schedule, Taxes, and IRMAA — all from one shared value.</li>\n      <li><strong>SS Claim-Age slider (SS tab)</strong> — 62–70, drives the claiming optimizer. The spouse names shown are read from your data (My Data tab), not hard-coded.</li>\n      <li><strong>Guardrails Toggle (Trajectory tab)</strong> — show/hide the Guyton-Klinger spending bands.</li>\n    </ul>\n\n    <h3>Modeling Approach — read this</h3>\n    <p>Danger Close uses a <strong>regime-switching mixture model</strong> — with two optional engine toggles on the Monte Carlo tab: <em>stochastic longevity</em> (Gompertz-sampled death ages anchored to your entered life expectancy as the median) and an <em>LTC distribution</em> (a drawn care-duration tail replacing the single shock) — not the classical mean-plus-standard-deviation Monte Carlo most tools use. Each year the simulator picks one of six regimes (under BASE: base 45%, optimistic 20%, pessimistic 15%, recession 10%, stagflation 7%, crisis 3%) and holds it for all four quarters — the regime means are annual outcomes — then applies that regime's return plus a small quarterly noise term. Variance comes mostly from regime-switching, so the AAGR-vs-CAGR \"variance drag\" double-counting bug that affects some tools does <em>not</em> apply here.</p>\n    <div class=\"plain\">\n      <span class=\"lbl\">In plain English</span>\n      <p>Most calculators picture the market as one bumpy \"average\" year repeated over and over. Danger Close instead <strong>rolls a die each year to decide what kind of year it is</strong> — normal, boom, slump, recession, 1970s-style high-inflation, or 2008-style crisis — and uses that year's typical result. Real economies move in streaks (good years cluster together, so do bad ones), and picking a year-type each turn captures that far better than one fixed average.</p>\n    </div>\n    <p><strong>But the BASE prior is deliberately conservative</strong> versus historical US equity performance. Probability-weighted across regimes:</p>\n    <figure>\n      <svg viewBox=\"0 0 760 260\" font-family=\"'JetBrains Mono',monospace\">\n        <!-- axis -->\n        <line x1=\"150\" y1=\"20\" x2=\"150\" y2=\"210\" stroke=\"#1a3a2a\"/>\n        <line x1=\"150\" y1=\"210\" x2=\"720\" y2=\"210\" stroke=\"#1a3a2a\"/>\n        <!-- zero line -->\n        <line x1=\"300\" y1=\"20\" x2=\"300\" y2=\"210\" stroke=\"#27513a\" stroke-dasharray=\"3 3\"/>\n        <text x=\"300\" y=\"232\" fill=\"#6a8a7a\" font-size=\"9\" text-anchor=\"middle\">0%</text>\n        <!-- scale: x = 300 + realReturn*px, px=40 per 1% -->\n        <!-- historical 7.5 -->\n        <text x=\"140\" y=\"50\" fill=\"#6a8a7a\" font-size=\"11\" text-anchor=\"end\">HISTORICAL</text>\n        <rect x=\"300\" y=\"38\" width=\"300\" height=\"22\" fill=\"rgba(0,255,136,0.3)\" stroke=\"#00ff88\"/>\n        <text x=\"610\" y=\"53\" fill=\"#00ff88\" font-size=\"11\">+7.5% real (since 1926)</text>\n        <!-- BULL 2.6 -->\n        <text x=\"140\" y=\"92\" fill=\"#6a8a7a\" font-size=\"11\" text-anchor=\"end\">BULL-LEAN</text>\n        <rect x=\"300\" y=\"80\" width=\"104\" height=\"22\" fill=\"rgba(0,204,255,0.3)\" stroke=\"#00ccff\"/>\n        <text x=\"414\" y=\"95\" fill=\"#00ccff\" font-size=\"11\">+2.6% real</text>\n        <!-- BASE 0.4 -->\n        <text x=\"140\" y=\"134\" fill=\"#6a8a7a\" font-size=\"11\" text-anchor=\"end\">BASE</text>\n        <rect x=\"300\" y=\"122\" width=\"16\" height=\"22\" fill=\"rgba(255,170,0,0.35)\" stroke=\"#ffaa00\"/>\n        <text x=\"326\" y=\"137\" fill=\"#ffaa00\" font-size=\"11\">+0.4% real</text>\n        <!-- BEAR -7.7 -->\n        <text x=\"140\" y=\"176\" fill=\"#6a8a7a\" font-size=\"11\" text-anchor=\"end\">BEAR-LEAN</text>\n        <rect x=\"192\" y=\"164\" width=\"108\" height=\"22\" fill=\"rgba(255,68,68,0.3)\" stroke=\"#ff4444\"/>\n        <text x=\"186\" y=\"179\" fill=\"#ff4444\" font-size=\"11\" text-anchor=\"end\">−7.7% real</text>\n      </svg>\n      <figcaption>FIG.2 — EXPECTED REAL EQUITY RETURN BY PRIOR vs HISTORY</figcaption>\n    </figure>\n    <p>Even the BULL-LEANING prior sits well below realized history. <strong>This is a modeling choice, not a bug</strong> — it follows the conservative-academic tradition (Pfau and others advocate 2–4% forward real returns for planning). In practice, your success rates here will read <em>lower</em> than Boldin/ProjectionLab/Pralana at their defaults, sometimes by 10–20 points. Cross-check critical results against one commercial tool; the gap is the prior's conservatism, not an error. For history-like output, use BULL-LEANING.</p>\n    \n    <h3>Inflation assumptions — one map, three different numbers on purpose</h3>\n    <p>Three inflation figures appear in the app, and the differences are deliberate, each erring conservative in its own direction: <strong>(1) Household inflation ~2.7% expected</strong> — the simulators (Monte Carlo, Trajectory, Stress) don't use a single rate at all; each simulated quarter draws the regime's rate (2.0% in booms, 2.8% base, 3.5% pessimistic, 6.5% in stagflation — probability-weighted ≈2.7% under the BASE prior, between the last 30 years' ~2.5% and the full-century ~3.0%). Spending and Social Security's COLA ride these draws; the pension deliberately doesn't (no COLA). <strong>(2) Tax-threshold indexation 2.0%</strong> — brackets, deductions, and IRMAA tiers grow at 2%/yr in the deterministic tax engines. Law indexes these by <em>chained</em> CPI, which historically runs ~0.3 points below regular CPI — and for thresholds, assuming <em>slower</em> growth is the conservative choice: income outgrowing brackets produces bracket creep, so the model <em>overstates</em> your future taxes rather than flattering them. Raising this number would make Roth math look better, not safer. <strong>(3) LTC costs: inflation +1.5%</strong> — long-term-care costs escalate <em>above</em> whatever inflation each path draws, reflecting decades of care-cost growth outrunning CPI. Same philosophy every time: where an assumption must be picked, pick the direction that makes the plan look slightly worse than reality.</p>\n\n    <h3 id=\"longevity\">Why stochastic longevity matters — the STOCHASTIC LONGEVITY toggle</h3>\n    <p>By default, the simulator assumes both of you live to <em>exactly</em> the life expectancies you entered — clean, transparent, and quietly unrealistic, because nobody dies on schedule. The <strong>STOCHASTIC LONGEVITY</strong> toggle on the Monte Carlo tab replaces that with something closer to life: each of the 10,000 runs <strong>samples a different death age for each spouse</strong> from a Gompertz mortality curve anchored so the life expectancy you entered is the <strong>median</strong> — a 50/50 over-under, not a guarantee. (Anchored at 88, for example, the sampled tenth percentile lands near 74 and the ninetieth near 98.) Your number keeps its meaning; the tails around it become real.</p>\n    <p>That matters because the two tails stress <em>completely different parts of the plan</em>:</p>\n    <ul>\n      <li><strong>Long-life runs — the portfolio stress test.</strong> Live well past the median — late 90s, even past 100 — and the danger is simply outliving the money: more spending years than planned, sequence-of-returns risk compounding over decades, inflation quietly halving purchasing power roughly every 24 years at 3%, and long-term-care odds rising exactly when the balance is smallest.</li>\n      <li><strong>Short-life runs — the survivor stress test.</strong> One spouse dying early triggers the <strong>widowhood penalty</strong>: the household keeps only the larger Social Security check, most fixed expenses (housing, property taxes, insurance, utilities) barely shrink, the survivor is pushed into Single filing's narrower brackets and smaller standard deduction, and healthcare costs often rise. The Survivor tab dissects this case; the toggle folds thousands of variations of it into the headline success rate.</li>\n    </ul>\n    <div class=\"plain\">\n      <span class=\"lbl\">In plain English</span>\n      <p>Instead of asking <em>\"what happens if we live exactly to our life expectancies?\"</em>, the toggle asks the better question: <strong>\"what fraction of thousands of realistic lifetimes — some short, some very long — does this plan survive?\"</strong> Expect the success number to move when you flip it; that movement <em>is</em> the information. One honest limit: the two spouses' lifespans are sampled independently — the real-world correlation of couples' health is not modeled.</p>\n    </div>\n\n    <h3 id=\"ltcdist\">The real shape of long-term-care risk — the LTC DISTRIBUTION toggle</h3>\n    <p>Long-term-care duration is one of the most <strong>right-skewed</strong> risks in retirement — the average hides everything that matters. The research picture: roughly <strong>a third of today's 65-year-olds will never need long-term-care support at all</strong>; the median formal (nursing-home) stay is startlingly brief — often days or weeks of post-acute rehab after a surgery or illness; yet about <strong>20% will need care for more than five years</strong>, and roughly 5% will spend over four years in a nursing home. Duration also splits sharply by sex — women average about <strong>3.7 years</strong> of care need versus <strong>2.2 for men</strong>, largely because women live longer (and spend about 6.1 adult years <em>giving</em> care besides). It is why the long-term-care insurance industry standardized on a <strong>3-year benefit period</strong>: it covers the great majority of claims at a payable premium — while dementia care, the classic budget-breaker, routinely outruns it.</p>\n    <p>The default engine models care as one $150K–$300K event per spouse — the <em>median-ish</em> experience. The <strong>LTC DISTRIBUTION</strong> toggle swaps in the real shape: each run <strong>draws a paid-care duration per spouse</strong> (usually zero, occasionally many years, at ~$120K/yr in today's dollars escalating 1.5%/yr <em>above</em> inflation), anchored to the final years before that run's own death. The expected cost is similar to the single shock; the <strong>ruin tail is far fatter</strong> — because multi-year care lands at the worst possible moment: portfolio at its smallest, one Social Security check already gone.</p>\n    <div class=\"plain\">\n      <span class=\"lbl\">In plain English — and one number reconciled</span>\n      <p>Most people pay little for care; a few pay catastrophically. Averages mislead; the toggle models the lottery instead. One apparent conflict worth squaring: research says ~33% never need <em>any</em> care, while this model draws \"no <em>paid</em> care\" 45% of the time — different measures, not a contradiction, since a large share of real care is unpaid family care that never touches a portfolio. Both agree on the part that matters: <strong>the tail, not the average, is the risk</strong>. Pair the toggle with the Stress tab's LTC Marathon — and if you are evaluating LTC insurance, this is exactly the distribution a 3-year benefit period is priced against.</p>\n    </div>\n\n  </div>\n</section>\n\n<!-- TABS DETAIL -->\n<section id=\"tabs\">\n  <div class=\"wrap\">\n    <h2><span class=\"num\">07</span> The Tabs in Detail <a class=\"toclink\" href=\"#toc\">↑ Contents</a></h2>\n    <div class=\"pillrow\" style=\"margin:14px 0 4px\">\n      <a class=\"pill\" href=\"#g-foundation\" style=\"color:#00ccff;border-color:#00ccff\">▍Foundation</a>\n      <a class=\"pill\" href=\"#g-scoring\" style=\"color:#aa66ff;border-color:#aa66ff\">▍Scoring</a>\n      <a class=\"pill\" href=\"#g-strategy\" style=\"color:#ffaa00;border-color:#ffaa00\">▍Strategy</a>\n      <a class=\"pill\" href=\"#g-testing\" style=\"color:#ff6600;border-color:#ff6600\">▍Testing</a>\n      <a class=\"pill\" href=\"#g-tools\" style=\"color:#ff4444;border-color:#ff4444\">▍Tools &amp; Reference</a>\n    </div>\n\n    <h3 id=\"g-foundation\" style=\"color:#00ccff\">▍Foundation</h3>\n\n    <div class=\"tabentry\">\n      <h3>Dashboard <span class=\"tag\" style=\"background:rgba(0,204,255,.15);color:#00ccff\">foundation</span></h3>\n      <p class=\"purpose\">One screen, the three questions retirees actually ask.</p>\n      <p><strong>Will my money last?</strong> (Monte Carlo success and median outcome) · <strong>How much can I spend?</strong> (modeled spending, the guaranteed-income floor, and the resulting portfolio draw rate) · <strong>Can I survive a crash?</strong> (success with poor returns forced into the first three retirement years, vs the no-crash base). Each card links to the tab with the full workings. It's the default landing view once a plan is loaded — and a good place to send a spouse who wants the answer without the other tabs.</p>\n    </div>\n    <div class=\"tabentry\">\n      <h3>My Data <span class=\"tag\" style=\"background:rgba(0,204,255,.15);color:#00ccff\">foundation</span></h3>\n      <p class=\"purpose\">Where your plan lives — the forms every other tab reads from.</p>\n      <p>Household (names, birth dates, retirement year, life expectancies, state tax), holdings, Social Security &amp; pension, contributions, and expenses — plus <strong>Save &amp; Apply</strong>, <strong>Export / Import Backup</strong>, and <strong>Clear All Data</strong>. Section <a href=\"#xlsx\">08</a> walks through every field. If a projection ever looks wrong, this tab is where to look first.</p>\n    </div>\n    <div class=\"tabentry\">\n      <h3>Trajectory <span class=\"tag\" style=\"background:rgba(0,204,255,.15);color:#00ccff\">foundation</span></h3>\n      <p class=\"purpose\">The headline balance-over-time chart from now through year 30.</p>\n      <p>Shows the projected portfolio path with optional Guyton-Klinger guardrail bands. The first read for \"does the line trend up, drift, or deplete?\"</p>\n    </div>\n    <div class=\"tabentry\">\n      <h3>Expenses <span class=\"tag\" style=\"background:rgba(0,204,255,.15);color:#00ccff\">foundation</span></h3>\n      <p class=\"purpose\">Pre- vs post-retirement spending, item by item.</p>\n      <p>Each expense shows its category, amount, and active window (start → end · duration). A delta block shows what <strong>drops off</strong> at retirement (e.g. mortgage), what <strong>adds on</strong> (LTC, ACA, Medicare), and what continues unchanged (marked ↻), with no double-counting.</p>\n      <p class=\"micro\">Tip: recurring \"for-life\" costs (housing, food, utilities, Medicare) should run all the way to the end of the plan. If any stop early, the Events tab raises an alarm — otherwise the simulator treats those later years as free and every success rate looks rosier than it should.</p>\n    </div>\n    <div class=\"tabentry\">\n      <h3>Income <span class=\"tag\" style=\"background:rgba(0,204,255,.15);color:#00ccff\">foundation</span></h3>\n      <p class=\"purpose\">Income stack: Social Security, pension, and your entered income streams (rental, work, annuities).</p>\n      <p>Shows when each stream starts and the combined floor. The key insight it surfaces appears below.</p>\n      <figure>\n        <svg viewBox=\"0 0 720 150\" font-family=\"'JetBrains Mono',monospace\">\n          <text x=\"10\" y=\"30\" fill=\"#6a8a7a\" font-size=\"11\">SPENDING NEED</text>\n          <rect x=\"10\" y=\"40\" width=\"690\" height=\"30\" fill=\"rgba(255,255,255,0.04)\" stroke=\"#27513a\"/>\n          <text x=\"700\" y=\"60\" fill=\"#c0d8cc\" font-size=\"11\" text-anchor=\"end\">~$95K/yr</text>\n          <text x=\"10\" y=\"100\" fill=\"#6a8a7a\" font-size=\"11\">COVERED BY</text>\n          <rect x=\"10\" y=\"110\" width=\"436\" height=\"30\" fill=\"rgba(0,255,136,0.25)\" stroke=\"#00ff88\"/>\n          <text x=\"228\" y=\"130\" fill=\"#00ff88\" font-size=\"11\" text-anchor=\"middle\">GUARANTEED ~$60K (63%)</text>\n          <rect x=\"446\" y=\"110\" width=\"254\" height=\"30\" fill=\"rgba(255,170,0,0.25)\" stroke=\"#ffaa00\"/>\n          <text x=\"573\" y=\"130\" fill=\"#ffaa00\" font-size=\"11\" text-anchor=\"middle\">PORTFOLIO DRAW ~$35K</text>\n        </svg>\n        <figcaption>FIG.3 — INCOME COVERAGE (EXAMPLE HOUSEHOLD): ~2.1% STEADY-STATE WITHDRAWAL RATE</figcaption>\n      </figure>\n      <p class=\"micro\">When guaranteed income covers most of spending, the portfolio draw is tiny — the difference between \"income-replacement capital\" and \"legacy capital.\" This single fact drives most of the app's reassuring results.</p>\n    </div>\n    <div class=\"tabentry\">\n      <h3>SS (Social Security) <span class=\"tag\" style=\"background:rgba(0,204,255,.15);color:#00ccff\">foundation</span></h3>\n      <p class=\"purpose\">Claiming-age optimizer for both spouses.</p>\n      <p>A <strong>trust-fund depletion scenario</strong> panel sits at the top: per the 2026 Trustees Report, the retirement fund alone depletes in late 2032 (then ~78% of scheduled benefits payable — the legal default), or 2034/~83% if Congress merges it with the disability fund. Depletion is not bankruptcy — checks continue at the covered percentage — and Congress has always acted before a cut landed, which is why this is a <em>scenario toggle</em>, not a prediction: flip it and every simulation, the Roth tax engine, the Dashboard, and the claiming grid recompute with post-depletion checks at your chosen percentage (benefit tables and breakeven cards keep showing scheduled amounts for clarity). Three one-click choices — <strong>NO CUT</strong> (scheduled benefits, what your statement shows), <strong>2033 → 78%</strong> (the OASI retirement fund alone — the legal default absent new law), <strong>2034 → 83%</strong> (OASI+DI combined, which requires an act of Congress) — plus custom year/percent fields. When active, a readout shows exactly what happens to each spouse's check and the household total in dollars, with a guide to where the cut ripples. Persisted across sessions. Below it: benefit-by-claiming-age tables (62–70), crossover ages, and the lifetime trade-off of claiming early vs delaying. Names and amounts read from your data. For couples, a dedicated <strong>Spouse B breakeven card</strong> runs the same claim-early-vs-FRA arithmetic on the second record and adds the couple's twist: the <em>smaller</em> check only pays until the first death (the survivor keeps the larger one), so the lower earner's honest breakeven horizon is the joint first death — usually years shorter than their own life expectancy — while a higher-earning Spouse B's delay protects the survivor and runs to the second death. And a <strong>spousal claiming-age grid</strong> sweeps all 81 combinations of both spouses\' claiming ages and scores household lifetime benefits (today\'s dollars, survivor step-up included, deaths at your entered life expectancies), marking the model\'s best cell against your current plan — with its approximations listed right under the grid (no discounting; spousal top-up benefits not modeled).</p>\n    </div>\n    <div class=\"tabentry\">\n      <h3>Positions <span class=\"tag\" style=\"background:rgba(0,204,255,.15);color:#00ccff\">foundation</span></h3>\n      <p class=\"purpose\">The raw holdings table behind everything.</p>\n      <p>Every position with its balance, account type, Roth/Traditional split, and asset class — the audit trail for the rest of the app.</p>\n    </div>\n\n    <h3 id=\"g-scoring\" style=\"color:#aa66ff\">▍Scoring</h3>\n\n    <div class=\"tabentry\">\n      <h3>Grade <span class=\"tag\" style=\"background:rgba(170,102,255,.15);color:#aa66ff\">scoring</span></h3>\n      <p class=\"purpose\">A composite retirement-readiness letter grade.</p>\n      <p>A radar chart across weighted dimensions (portfolio size, income floor, sequence buffer, LTC/tail risk, tax efficiency, diversification, estate readiness), with the evidence and the drag behind each grade.</p>\n    </div>\n    <div class=\"tabentry\">\n      <h3>Ranking <span class=\"tag\" style=\"background:rgba(170,102,255,.15);color:#aa66ff\">scoring</span></h3>\n      <p class=\"purpose\">Where you sit versus US peers.</p>\n      <p>Approximate \"Top N%\" tiers built from public survey data. The Federal Reserve Survey of Consumer Finances (SCF, currently the 2022 survey) is the backbone, with EBRI, SSA, and AALTCI filling in the rest. Heuristic context, not precise statistics — the percentile cut-points and the \"Nx the average\" ratios all trace back to these benchmarks.</p>\n      <p class=\"micro\">Why two savings benchmarks? The SCF surveys the <em>whole population</em> of Americans 55–64, so it includes the ~25% with essentially nothing saved — which drags the average and median down and flatters anyone who has saved consistently. So the tab pairs it with an Empower Personal Dashboard benchmark: balances for people who <em>actively track their money</em> on that platform — a self-selected crowd whose balances run far higher. Read the SCF as the easy mirror (you'll be several multiples of the average) and Empower as the honest one (the savers you actually resemble). Two limits to keep in mind: the figures are hand-entered approximations, not live microdata, and the SCF refreshes only every three years — the 2025 survey publishes ~fall 2026, when the Events tab flags these benchmarks as due for a refresh.</p>\n    </div>\n\n    <h3 id=\"g-strategy\" style=\"color:#ffaa00\">▍Strategy</h3>\n\n    <div class=\"tabentry\">\n      <h3>Guardrails <span class=\"tag\" style=\"background:rgba(255,170,0,.15);color:#ffaa00\">strategy</span></h3>\n      <p class=\"purpose\">Guyton-Klinger dynamic spending rules.</p>\n      <p>Cut spending if the portfolio falls to the lower band (default 80% of plan); raise it if it reaches the upper band (120%). Shows when each band triggers across scenarios.</p>\n    </div>\n    <div class=\"tabentry\">\n      <h3>Withdrawal Strategy <span class=\"tag\" style=\"background:rgba(255,170,0,.15);color:#ffaa00\">strategy</span></h3>\n      <p class=\"purpose\">A year-by-year operational drawdown plan.</p>\n      <p>Three sections: the year-by-year schedule, the account-priority order (Taxable → Traditional → Roth, with an 8-step order-of-operations), and a 3-strategy comparison. Growth rates link to the active scenario prior; the Roth-conversion column reads the shared slider.</p>\n    </div>\n    <div class=\"tabentry\">\n      <h3>Roth <span class=\"tag\" style=\"background:rgba(255,170,0,.15);color:#ffaa00\">strategy</span></h3>\n      <p class=\"purpose\">The Roth conversion ladder from retirement until the year before RMDs begin (RMD age 73 or 75 by birth year — SECURE 2.0).</p>\n      <p>Projects conversions year by year, the resulting RMD reduction at RMD age (73 for 1951–59 births, 75 for 1960+), and current Traditional/Roth balances (derived from your positions). The <strong>break-even</strong> (v5.7.1) appears under the strategy comparator as a WEALTH CROSSOVER card: your slider strategy and NO CONVERSIONS both run through the full 30-year engine and the card reports the first year your after-tax wealth catches up — so discounting and the opportunity cost of the conversion tax are included mechanically, and for some households the honest answer is that it never does. The conversion window and RMD start are below.</p>\n      <figure>\n        <svg viewBox=\"0 0 720 130\" font-family=\"'JetBrains Mono',monospace\">\n          <line x1=\"30\" y1=\"70\" x2=\"690\" y2=\"70\" stroke=\"#1a3a2a\"/>\n          <rect x=\"60\" y=\"56\" width=\"430\" height=\"28\" fill=\"rgba(0,204,255,0.18)\" stroke=\"#00ccff\"/>\n          <text x=\"275\" y=\"75\" fill=\"#00ccff\" font-size=\"11\" text-anchor=\"middle\">ROTH CONVERSION WINDOW</text>\n          <circle cx=\"60\" cy=\"70\" r=\"5\" fill=\"#00ff88\"/><text x=\"60\" y=\"40\" fill=\"#00ff88\" font-size=\"10\" text-anchor=\"middle\">RETIRE</text>\n          <circle cx=\"490\" cy=\"70\" r=\"5\" fill=\"#ffaa00\"/><text x=\"490\" y=\"40\" fill=\"#ffaa00\" font-size=\"10\" text-anchor=\"middle\">AGE 74</text>\n          <circle cx=\"560\" cy=\"70\" r=\"5\" fill=\"#ff4444\"/><text x=\"560\" y=\"40\" fill=\"#ff4444\" font-size=\"10\" text-anchor=\"middle\">AGE 75</text>\n          <text x=\"620\" y=\"74\" fill=\"#ff4444\" font-size=\"10\">RMDs begin</text>\n          <text x=\"275\" y=\"105\" fill=\"#6a8a7a\" font-size=\"9\" text-anchor=\"middle\">low-income gap years — convert at low brackets, before RMDs force income up</text>\n        </svg>\n        <figcaption>FIG.5 — THE ROTH CONVERSION WINDOW (EXAMPLE HOUSEHOLD, BORN 1964 → RMD AGE 75; 1951–59 BIRTHS START AT 73)</figcaption>\n      </figure>\n      <div class='card warn' style='border-radius:4px;margin-top:14px'><h4 style='margin-top:0;color:var(--amber)'>⚠ PAY CONVERSION TAX FROM OUTSIDE FUNDS — NOT FROM RETIREMENT ASSETS</h4><p style='margin:6px 0'>When you convert, the IRS wants its tax. <strong>Where that tax money comes from changes the math of the whole conversion.</strong> Pay it from a taxable (brokerage/savings) account and the full conversion lands in the Roth. Pay it by withholding from the conversion itself and you shrink the very tax shelter you are building — and if you are under 59½, you get fined for it.</p><h4>Example 1 — age 59½+, $100K conversion at a 24% marginal rate, 20 years at 4.5% growth</h4><ul class='tight'><li><strong>Tax paid from outside funds:</strong> $100,000 enters the Roth → grows to <strong>$241,171, all tax-free</strong>. The $24,000 tax came from your taxable account.</li><li><strong>Tax withheld from the conversion:</strong> only $76,000 enters the Roth → $183,290. The $24,000 you kept in taxable grows to about $52,800 <em>after</em> capital-gains tax. Total ≈ <strong>$236,089 — about $5,100 less</strong>, and that understates it because taxable dividends are taxed every year along the way.</li></ul><p style='margin:6px 0'>The clean way to see it: paying from outside funds is equivalent to <strong>moving an extra $24,000 of taxable money inside the Roth wrapper</strong> — something contribution limits would never otherwise let you do. Withholding throws that free shelter space away.</p><h4>Example 2 — the same conversion under age 59½: now it costs real money</h4><p style='margin:6px 0'>The $24,000 withheld never reaches the Roth, so the IRS treats it as an <strong>early distribution: a 10% penalty = $2,400 in cash, gone immediately</strong>. Add the lost growth on that penalty and the wrapper loss from Example 1, and the total cost is roughly <strong>$10,900 per $100K converted</strong>. On a multi-year ladder this compounds: withholding 24% on a $70K/yr conversion costs $1,680/yr in pure penalty alone. This is the case where <em>never</em> really means never.</p><h4>Example 3 — what if you have no taxable account?</h4><p style='margin:6px 0'>Some households (including the built-in example) hold nearly everything in retirement accounts. Honest answer: conversions can <em>still</em> be worth doing — the Conversion Strategy Comparator on the Roth tab models taxes paid from the taxable account first and Roth second, and conversions still beat doing nothing for the example household — the benefit is simply smaller than with outside funds. If you are under 59½, avoid <em>withholding</em> specifically: pay the tax from current cash flow via estimated payments so the full conversion reaches the Roth and no penalty applies. If you are 59½+ with no outside funds, size conversions so the reduced benefit still clears the bar (low brackets, widow-penalty avoidance, RMD reduction).</p><p class='micro' style='margin-bottom:0'>Rule of thumb: under 59½, never withhold from a conversion. At any age, prefer outside funds — every tax dollar paid from inside the shelter is shelter you permanently lose.</p></div>\n    </div>\n    <div class=\"tabentry\">\n      <h3>Taxes <span class=\"tag\" style=\"background:rgba(255,170,0,.15);color:#ffaa00\">strategy</span></h3>\n      <p class=\"purpose\">Lifetime tax estimate: federal income, capital gains, FICA, state.</p>\n      <p>Lifetime summary cards plus a clickable year-by-year table. Each year breaks gross taxable income into its sources (SS taxable portion, pension, earned income, RMD, Roth conversion, cap gains) via a stacked bar, then subtracts deductions to net taxable and shows the bracket-by-bracket fill. State tax uses a <strong>51-jurisdiction module</strong> (2026 approximations): each state's effective rate, Social Security treatment (only 8 states partially tax SS in 2026), full retirement-income exemptions (IL/MS/PA/IA/MI + the 9 no-tax states), and major 65+ exclusions (e.g. Georgia's $65K/person). Pick your state in My Data — or leave it on manual and the legacy flat rate applies unchanged. It is an approximation layer: effective rates stand in for progressive brackets and several income-limited exclusions are treated as unconditional — verify your state. The Roth slider drives the conversion column live, and a QCD what-if slider models charitable IRA distributions (income exclusion, RMD offset, lower MAGI). The tab reads as <strong>four numbered steps</strong> with a 30-second explainer up top: ① the conversion slider (your what-if dial — the comparator reads it live and names its row after it), ② the tax-funding selector, ③ the six-strategy comparator, ④ the solve-for grid. A <strong>conversion-tax funding</strong> control models where the tax money actually comes from — the question most calculators skip. Three honest cases: a sale that creates no taxable profit (cash, money markets, or an account holding little growth), an <em>appreciated brokerage</em> sale (the engine grosses the sale up to cover the capital-gains tax the sale itself creates — long-term rates stacked on that year's income — and feeds the realized gains into MAGI so the IRMAA lookback two years later sees them), or <em>withholding from the conversion itself</em> for households with no outside money (no sale, no gains tax, permanently smaller Roth — sometimes still the winning move; \"never pay conversion tax from the IRA\" assumes outside cash you may not have). Approximations, stated plainly: one blended gain share for the whole account, all long-term, no per-lot selection, no loss harvesting, no wash-sale logic, 59½+ assumed (no early-withdrawal penalty on the withheld slice). The Roth tab also carries a <strong>solve-for grid</strong>: 25 conversion policies swept through the deterministic engine and ranked against your chosen objective (after-tax estate, lifetime tax+IRMAA, or widow-year tax) — reported as the model's best cell, never a directive. <span class=\"plain\" style=\"display:block;margin-top:8px\"><span class=\"lbl\">Why the ranked amounts look shuffled</span> The cards are sorted by the <em>result</em> (your chosen goal), not by the conversion amount — so the dollar figures won't climb in order. That's because the relationship between conversion size and the goal is <strong>U-shaped</strong>: there's a sweet-spot amount in the middle, and moving away from it in <em>either</em> direction scores worse. Convert too little and you leave too much in the Traditional account, so bigger future RMDs force up your later taxes; convert too much and you voluntarily push income into higher brackets and IRMAA tiers now. So a small amount and a large amount can land next to each other with nearly the same score — one on each side of the valley. The green <strong>YOU</strong> card is your live slider amount scored the same way, with its rank among all 25 cells and a <strong>&plusmn;$ vs #1</strong> gap on every card so you can see how far each sits from the best. The whole spread is usually small (often $10–40K of lifetime tax+IRMAA on a multi-million-dollar estate), so treat it as fine-tuning — and check the IRMAA tab for which years a bigger conversion trips a Medicare cliff before acting.</span> <div class=\"plain\" style=\"margin-top:8px\"><span class=\"lbl\">The three sliders, in plain English</span><p><strong>Taxable-account yield</strong> — money in a regular brokerage account pays dividends and interest that are taxed every year even if you never sell; the slider is your estimate of that payout rate (last year's 1099-DIV ÷ account balance; ≈1.5% for stock index funds, 3–5% for bonds and cash). No brokerage account? It does nothing. <strong>QCD modeler</strong> — only for charitable givers age 70½+: gifts sent directly from a Traditional IRA to charity never appear on your tax return and still count toward the RMD. If you don't give, leave it at $0. <strong>Roth conversion slider</strong> — lives on the Roth tab; this tab's Roth Conv column follows it live. Set the yield honestly, leave the other two at zero, and the tab is simply your projected tax life as-is.</p></div></p>\n      <p class=\"micro\">Honest limits: SS taxation uses a simplified provisional-income test; realized cap gains default to $0 unless a sale is modeled; NIIT (3.8% on estimated investment income, unindexed thresholds), a simplified AMT check, and QCDs (a what-if slider: excluded from income and MAGI, counts toward the RMD, per-person indexed cap) are modeled.</p>\n    </div>\n    <div class=\"tabentry\">\n      <h3>IRMAA Cliff <span class=\"tag\" style=\"background:rgba(255,170,0,.15);color:#ffaa00\">strategy</span></h3>\n      <p class=\"purpose\">Medicare premium-surcharge cliffs vs your projected income.</p>\n      <p>The tier table, then a year-by-year view of MAGI vs the next cliff with a <strong>2-year lookback</strong> (\"Affects\" column), headroom coloring (amber within $40K, red within $15K), and lifetime surcharge total. Driven by the Roth slider — it shows when a conversion is about to push you over a cliff and cost ~$1,000+/yr per person.</p>\n    </div>\n\n    <div class=\"tabentry\">\n      <h3>ACA Premium Subsidy <span class=\"tag\" style=\"background:rgba(0,204,255,.15);color:#00ccff\">v5.7 · strategy</span></h3>\n      <p class=\"purpose\">Marketplace subsidy vs Roth conversions for anyone retiring before Medicare.</p>\n      <p>If you retire before 65, health coverage comes from the ACA marketplace, and the premium tax credit is set by your MAGI. The enhanced credits expired at the end of 2025, so under <strong>current law</strong> eligibility ends at a hard cliff: one dollar of MAGI over 400% of the prior year's federal poverty level and the entire subsidy — often $10,000–$25,000/yr for a couple in their early 60s — is gone. Roth conversions are MAGI, so a conversion strategy that wins on lifetime tax can quietly lose more in forfeited subsidies. This is frequently a <em>bigger</em> conversion penalty than IRMAA.</p>\n      <p><strong>How to use it:</strong> enter your household's benchmark silver premium (the second-lowest-cost silver plan from healthcare.gov) under My Data → ACA BRIDGE. <strong style=\"color:#ffaa00\">Enter the GROSS premium there and keep your expense rows as what you actually pay</strong> — the field feeds only the Roth tab's subsidy math, so nothing double-counts. The strategy table then gains an <strong>ACA SUB LOST</strong> column (each strategy charged, in real cash, for the subsidy it destroys versus converting nothing) and a <strong>STAY UNDER ACA CLIFF</strong> strategy that converts up to the cliff minus a $500 margin during bridge years, then fills the 24% bracket after Medicare. When that strategy converts $0 in a bridge year, that's the finding, not a bug: any conversion at all clears the cliff for your household.</p>\n      <p><strong>Law scenario toggle:</strong> Congress may restore the enhanced credits. Like the Social Security depletion scenario, this is your choice to stress, not a forecast — CURRENT LAW (400% cliff) or ENHANCED EXTENDED (the ARPA structure: no cliff, benchmark capped at 8.5% of income). Under ENHANCED the cliff strategy is hidden, since no cliff exists to stay under.</p>\n      <p><strong>What the model assumes (and its honest limits):</strong> ACA MAGI counts your <em>full</em> Social Security — the untaxed portion adds back, which is a different MAGI than IRMAA uses, and it can put you on the wrong side of the cliff while your tax return looks fine. Bridge premiums grow at household inflation plus 2 points (medical trend). In years where one spouse has reached Medicare, half the household premium is assumed. Below 100% of FPL the model shows $0 and defers to Medicaid rules it does not model. Alaska/Hawaii poverty levels, cost-sharing reductions, and plan choice are not modeled — this prices the subsidy, not your healthcare. Constants come from IRS Rev. Proc. 2025-25 and the HHS poverty guidelines, and are checked on the Verify tab.</p>\n    </div>\n\n    <div class=\"tabentry\">\n      <h3>Exit Plan <span class=\"tag\" style=\"background:rgba(255,170,0,.15);color:#ffaa00\">strategy</span></h3>\n      <p class=\"purpose\">A five-phase operational countdown for the retirement transition itself.</p>\n      <p>Turns the plan into a sequence of moves with target dates derived from your timeline: <strong>1</strong> Confirm the money works (final Monte Carlo / guardrail check) → <strong>2</strong> Lock in health coverage (ACA bridge / Medicare) → <strong>3</strong> Decide &amp; file Social Security (SSA accepts filings 4 months ahead) → <strong>4</strong> Put in your notice (HR checklist: PTO payout, final match, vesting) → <strong>5</strong> Turn on the portfolio paycheck (cash reserve → checking autopay, withholding/estimates). Each phase shows a live status chip wired to the same engine as the <strong>Events</strong> tab, plus the landmines to avoid.</p>\n    </div>\n\n    <h3 id=\"g-testing\" style=\"color:#ff6600\">▍Testing</h3>\n\n    <div class=\"tabentry\">\n      <h3>Monte Carlo <span class=\"tag\" style=\"background:rgba(255,102,0,.15);color:#ff6600\">testing</span></h3>\n      <p class=\"purpose\">The probability engine — thousands of randomized futures.</p>\n      <p>Success rate at multiple thresholds, outcome dispersion, and the shape of the 10th-percentile (bad-case) path. Uses the regime-switching model described in section 06 — plus two engine toggles, <strong>STOCHASTIC LONGEVITY</strong> and <strong>LTC DISTRIBUTION</strong>, whose full explanations (and why flipping them moves the success number) live in <a href=\"#longevity\">§06</a>.</p>\n      <p>Five runs build the picture: <strong>A</strong> accumulation up to retirement, <strong>B</strong> the first decade, <strong>C</strong> the full 30 years (with a single long-term-care shock and deaths at life expectancy), <strong>C (no LTC)</strong> the same minus that shock so its cost is visible, and <strong>D — probabilistic long-term care</strong>, which draws a <em>random</em> number of care years for each spouse every run (often zero, occasionally many) instead of one fixed shock. Run D reads the harshest on purpose: it surfaces the late-life \"what if care drags on for years\" risk that a single early shock hides.</p>\n    </div>\n    <div class=\"tabentry\">\n      <h3>Historical Backtest <span class=\"tag\" style=\"background:rgba(255,102,0,.15);color:#ff6600\">testing</span></h3>\n      <p class=\"purpose\">Replays your plan against real market history (1928–2025).</p>\n      <p>Survival rate across every historical start year, a stock/bond cross-check, and the infamous start years (1929, 1966, 1973, 2000, 2008, plus 1982 for contrast) with end balance, low point, and depletion year. A 1966 real-balance chart shows the worst-case grind. Complements the Monte Carlo: it replays real pasts including their actual sequencing.</p>\n      <p class=\"micro\">Holds your asset mix constant; doesn't model taxes, RMDs, Roth, or LTC — it isolates pure sequence-of-returns risk.</p>\n    </div>\n    <div class=\"tabentry\">\n      <h3>What Breaks the Plan <span class=\"tag\" style=\"background:rgba(255,102,0,.15);color:#ff6600\">testing</span></h3>\n      <p class=\"purpose\">Reverse stress test — solves for the break-points.</p>\n      <p>Four plain answers under the active prior: how much more you could spend, how large a one-time LTC/emergency shock you can absorb, how bad returns can get, and how many consecutive crash years at retirement you survive. Switch to BEAR to watch the edges tighten.</p><p>The modeled outflow includes <strong>estimated taxes</strong> (an annual average from the Taxes engine, including Roth-conversion taxes), claim-month-accurate Social Security, and the <strong>survivor transition</strong> (larger SS check only, plus a 25% spending drop, after the first projected death). Not modeled: recurring long-term care, IRMAA surcharges, and market sequence — the Monte Carlo tab covers that.</p><div class='note'><strong>How bad is the return break-point, historically?</strong> The worst rolling <em>decade</em> for US stocks — 2000–2009, the dot-com bust followed by the financial crisis — ran about −3.4%/yr real. In 150+ years of data, <strong>no 20-year stretch has ever produced a negative real total return</strong>: the weakest windows (starting 1929, or 2000) still earned roughly +2%/yr, and every 30-year window on record has been positive (the worst ≈ +3.6%/yr, and that window ended in the depths of 1932). A break-point of several percent <em>negative</em>, sustained for the entire plan, therefore sits far outside anything US market history has produced. One honest caveat: those are <em>stock</em> figures — bonds did suffer negative multi-decade real stretches (roughly 1941–1981), which is exactly the blended-portfolio risk the Monte Carlo's stagflation regime exists to probe.</div>\n    </div>\n    <div class=\"tabentry\">\n      <h3>Survivor Scenario <span class=\"tag\" style=\"background:rgba(255,102,0,.15);color:#ff6600\">testing</span></h3>\n      <p class=\"purpose\">The financial picture when one spouse dies — both cases.</p>\n      <p>Models the loss of the smaller SS check, the flip to Single filing (the \"widow's penalty\"), and the ~25% spending drop. Each case shows income before/after, the SS step-up-vs-loss mechanics, and <strong>years alone</strong> (from life expectancies) — which differ sharply between the two cases and drive how long the higher single-filer taxes apply. Argues for front-loading Roth conversions while both file jointly.</p>\n    </div>\n    <div class=\"tabentry\">\n      <h3>Stress <span class=\"tag\" style=\"background:rgba(255,102,0,.15);color:#ff6600\">testing</span></h3>\n      <p class=\"purpose\">Named adverse scenarios.</p>\n      <p>Runs the plan through named shocks side by side — AI-bubble burst, stagflation, sequence-of-returns, a single LTC event, and the newer <strong>LTC Marathon</strong> — against a no-shock base, with Riskalyze-style risk metrics (volatility, Sharpe/Sortino, max drawdown).</p>\n      <figure>\n        <svg viewBox=\"0 0 760 250\" font-family=\"'JetBrains Mono',monospace\">\n          <text x=\"20\" y=\"24\" fill=\"#6a8a7a\" font-size=\"10\">RETIRE</text>\n          <text x=\"740\" y=\"24\" fill=\"#6a8a7a\" font-size=\"10\" text-anchor=\"end\">DEATH</text>\n          <text x=\"20\" y=\"70\" fill=\"#ffaa00\" font-size=\"11\">SINGLE LTC EVENT</text>\n          <line x1=\"20\" y1=\"92\" x2=\"740\" y2=\"92\" stroke=\"#1a3a2a\"/>\n          <rect x=\"150\" y=\"80\" width=\"46\" height=\"24\" fill=\"rgba(255,170,0,0.3)\" stroke=\"#ffaa00\"/>\n          <text x=\"173\" y=\"124\" fill=\"#6a8a7a\" font-size=\"9\" text-anchor=\"middle\">one bill, early</text>\n          <text x=\"173\" y=\"138\" fill=\"#6a8a7a\" font-size=\"9\" text-anchor=\"middle\">$150-300K · pot still big</text>\n          <text x=\"20\" y=\"180\" fill=\"#aa66ff\" font-size=\"11\">LTC MARATHON</text>\n          <line x1=\"20\" y1=\"202\" x2=\"740\" y2=\"202\" stroke=\"#1a3a2a\"/>\n          <rect x=\"560\" y=\"190\" width=\"30\" height=\"24\" fill=\"rgba(170,102,255,0.22)\" stroke=\"#aa66ff\"/>\n          <rect x=\"592\" y=\"190\" width=\"30\" height=\"24\" fill=\"rgba(170,102,255,0.3)\" stroke=\"#aa66ff\"/>\n          <rect x=\"624\" y=\"190\" width=\"30\" height=\"24\" fill=\"rgba(170,102,255,0.4)\" stroke=\"#aa66ff\"/>\n          <rect x=\"656\" y=\"190\" width=\"30\" height=\"24\" fill=\"rgba(170,102,255,0.5)\" stroke=\"#aa66ff\"/>\n          <text x=\"623\" y=\"234\" fill=\"#6a8a7a\" font-size=\"9\" text-anchor=\"middle\">years of care, late · $120K/yr and rising · pot small, one SS check left</text>\n        </svg>\n        <figcaption>FIG.6 — SAME-ISH TOTAL COST, VERY DIFFERENT TIMING → VERY DIFFERENT RISK</figcaption>\n      </figure>\n      <div class=\"plain\">\n        <span class=\"lbl\">In plain English — why two LTC scenarios?</span>\n        <p>The original \"LTC event\" assumes one big care bill ($150K-300K) fairly early, while your savings are still large. But real long-term care usually arrives <strong>at the very end of life and can drag on for years</strong> — exactly when the pot is smallest and one Social Security check has already stopped. The <strong>LTC Marathon</strong> models that long, late, rising cost. It can add up to a similar total as the single shock yet do far more damage, purely because of <em>when</em> it lands.</p>\n      </div>\n    </div>\n\n    <h3 id=\"g-tools\" style=\"color:#ff4444\">▍Tools &amp; Reference</h3>\n\n    <div class=\"tabentry\">\n      <h3>Ask AI <span class=\"tag\" style=\"background:rgba(255,68,68,.15);color:#ff4444\">ai</span></h3>\n      <p class=\"purpose\">An AI assistant with full context on your plan.</p>\n      <p>Sends a structured summary of your data and results to a language model for natural-language follow-up. It's a real <strong>conversation</strong>: if the AI answers with a question of its own, type your reply in the same box and EXECUTE — the session transcript is re-sent each turn (last 12 messages), so it remembers what it asked. ⟲ NEW SESSION starts fresh. (Self-hosted key users: longer sessions re-send more context, so each turn costs slightly more.) Ships with five universal starter questions:</p>\n      <div class=\"pillrow\">\n        <span class=\"pill\">Will my money last as long as I do?</span>\n        <span class=\"pill\">What if I live longer than expected?</span>\n        <span class=\"pill\">Can I survive a crash right after I retire?</span>\n        <span class=\"pill\">How much can I safely spend each year?</span>\n        <span class=\"pill\">What if inflation stays high?</span>\n      </div>\n      <p class=\"micro\">The assistant can be confidently wrong. Always verify before acting. Self-hosted copies (running outside claude.ai) power this tab with a personal API key via the LOCAL API KEY panel — stored only in that browser, never in the app file or backups, and wiped by Clear All Data. Full guide: <a href=\"#apikey\">§10</a>.</p></div><div class='tabentry'><h3>Checklist <span class='tag' style='background:rgba(0,204,255,.15);color:#00ccff'>tools</span></h3><p class='purpose'>An estate &amp; retirement-readiness checklist.</p><p>Grouped action items (estate documents, beneficiaries, account access, insurance, a survivor playbook) with notes and a contact per item. Survivor-critical items are flagged, progress is tracked, and the completion of the critical items feeds an <strong>Estate Readiness</strong> dimension on the Grade tab. Your checks and notes persist locally and travel in the Export Backup.</p></div><div class='tabentry'><h3>Skins <span class='tag' style='background:rgba(106,138,122,.18);color:#6a8a7a'>tools</span></h3><p class='purpose'>Display themes.</p><p>Seven color palettes built on a CSS-variable token system — the original Tactical Green console, three softer darks (Soft Dark Mode, Warm Executive, Low-Glare Dark), and three light paper themes: Field Manual (red, white &amp; green), Reading Paper (warm sepia), and E-Ink Gray. The light themes are the easiest on the eyes in bright rooms and for long text-heavy sessions; the darks suit low light. Each tile previews its own colors; the choice persists in the browser cache and travels in the Export Backup.</p></div><div class='tabentry'><h3>Docs <span class='tag' style='background:rgba(106,138,122,.18);color:#6a8a7a'>tools</span></h3><p class='purpose'>This field manual.</p><p>The full documentation, viewable in-app and downloadable as HTML or printable to PDF from the toolbar above.</p></div><div class=\"tabentry\">\n      <h3>Verify <span class=\"tag\" style=\"background:rgba(170,102,255,.15);color:#aa66ff\">trust</span></h3>\n      <p class=\"purpose\">A live audit of this copy's statutory constants — run in your browser, every visit.</p>\n      <p>Every tax bracket, deduction, IRMAA tier, RMD divisor, QCD cap, wage base, and state-module fact the math depends on is re-checked against its primary-source value (IRS Rev. Proc. 2025-32, CMS, SSA, IRS Pub. 590-B) the moment you open the tab, with a ✓ or ✗ per line and the citation beside it. Green across the board means <em>this file, in your hands, right now</em> carries the correct law — a tampered or corrupted copy fails loudly. Two longevity checks are statistical and re-sample live. Honest scope: constants, not every formula using them; the source distribution's Node suite, the behavioral tests, and eventually independent professional review cover that ground.</p>\n    </div>\n    <div class='tabentry'><h3>Events <span class='tag' style='background:rgba(255,170,0,.15);color:#ffaa00'>tools</span></h3><p class='purpose'>Every dated obligation in the plan, as live alarms.</p><p>A live alarm for every dated obligation, derived from your timeline and the shared constants (eighteen for a two-person household — several are per-spouse) — the annual tax-constant refresh, the backtest-data append, Roth-conversion and RMD deadlines, Social Security filing windows (SSA accepts applications four months ahead), Medicare initial enrollment and annual Open Enrollment, ACA-bridge open enrollment, estimated quarterly taxes during conversion years, the peer-benchmark refresh behind the Ranking tab (the Fed SCF is triennial), quarterly backup nudges, the annual SSA earnings-record check, a January plan review, and an alarm if your for-life expenses stop before the plan horizon (which would otherwise make the simulator treat your final years as free). Statuses recompute from today's date on every load — <strong>yellow</strong> = getting close (prepare), <strong>green</strong> = action window open (go), <strong>red</strong> = action required or verify, dim = tracking / past — and nothing is stored, so alarms can never go stale or be dismissed and forgotten. The most urgent tier also surfaces as a colored strip above the tabs on every view; clicking it opens this tab. Each event carries plain-language instructions and points at the authoritative source (irs.gov, ssa.gov, cms.gov, medicare.gov, healthcare.gov). Deadlines are informational — verify with the agencies before acting.</p></div>\n    </div>\n    <a class=\"totop-foot\" href=\"#toc\">↑ Back to Table of Contents</a>\n  </div>\n</section>\n\n<!-- XLSX -->\n<section id=\"xlsx\">\n  <div class=\"wrap\">\n    <h2><span class=\"num\">08</span> Entering Your Data — the My Data Tab <a class=\"toclink\" href=\"#toc\">↑ Contents</a></h2>\n    <p>The <strong>My Data</strong> tab is where you build or edit your plan. It's a set of plain forms — no file formats to get right. Fill in what applies, then press <strong>Save &amp; Apply</strong> to rebuild every tab from it.</p>\n    <table>\n      <tr><th>Section</th><th>What you enter</th></tr>\n      <tr><td><strong>Household</strong></td><td>Names, single or couple, birth dates, target retirement year, life expectancies, state and its income-tax rate</td></tr>\n      <tr><td><strong>Holdings</strong></td><td>One row per position: ticker/name, balance, asset type, Roth vs Traditional, expense ratio — plus any non-retirement \"other accounts\"</td></tr>\n      <tr><td><strong>Income</strong></td><td>Social Security for each person (monthly amount, planned claim age, and the full benefit-by-age table), any pension, and an <strong>Other Income Streams</strong> table — rental, post-retirement jobs, annuities, royalties — each with owner, start/end years, COLA flag, and taxable vs tax-free treatment</td></tr>\n      <tr><td><strong>Contributions</strong></td><td>Salaries and ongoing 401(k)/HSA contributions while still working</td></tr>\n      <tr><td><strong>Expenses</strong></td><td>One row per expense: category, label, amount, frequency (monthly / annual / one-time), start and end dates, deductible flag, and whether it applies before, after, or across retirement</td></tr>\n    </table>\n    <div class=\"note\"><strong>Save &amp; Apply</strong> caches everything in your browser and re-derives all 26 tabs. <strong>Export Backup</strong> writes the same data to a <code>.json</code> file; <strong>Import Backup</strong> reads one back. That JSON backup is the only file format the app reads or writes — there's no spreadsheet or Word-document import.</div>\n  </div>\n</section>\n\n<!-- DOCX -->\n<section id=\"docx\">\n  <div class=\"wrap\">\n    <h2><span class=\"num\">09</span> The Master Prompt &amp; AI Context <a class=\"toclink\" href=\"#toc\">↑ Contents</a></h2>\n    <p>The <strong>master prompt</strong> is the plain-language briefing the <a href=\"#tabs\">Ask AI</a> tab sends to the language model so its answers are grounded in <em>your</em> plan. You no longer write or upload it — the app <strong>builds it automatically</strong> from your My Data entries (household, portfolio, income) each time you ask a question.</p>\n    <p>It reads like a short situation report. The generated context includes:</p>\n    <table>\n      <tr><th>What the AI sees about your plan</th></tr>\n      <tr><td>Names, ages, filing status, target retirement year, and state</td></tr>\n      <tr><td>Portfolio total, retirement-vs-taxable split, asset mix, weighted expense ratio</td></tr>\n      <tr><td>Social Security (by claim age), pension, and any other income streams you entered</td></tr>\n      <tr><td>Headline results — success rate, median outcome, and the key risks</td></tr>\n    </table>\n    <div class=\"note\">Because it's generated from your data, the AI context stays current automatically and travels inside your exported backup — there's nothing to keep in sync by hand. (Older backups may still contain a <code>masterPrompt</code> field; it's loaded for continuity but the live context is always regenerated from your current numbers.)</div>\n  </div>\n</section>\n\n<!-- API KEY -->\n<section id=\"apikey\">\n  <div class=\"wrap\">\n    <h2><span class=\"num\">10</span> Ask AI &amp; Your API Key (Self-Hosted Copies) <a class=\"toclink\" href=\"#toc\">↑ Contents</a></h2>\n    <p class=\"lead\">This section only matters if you run Danger Close <strong>on your own computer</strong> — the downloaded single-file HTML or a local dev server. Inside claude.ai, the platform signs the Ask AI call for you: there is no key, no billing setup, and the LOCAL API KEY panel doesn't even appear. On your own machine, the app has no way to prove to the AI service that anyone should pay for the answer — so you bring your own key.</p>\n    <div class=\"plain\">\n      <span class=\"lbl\">In plain English</span>\n      <p>An API key works like a <strong>prepaid calling card for the AI</strong>. You open a small account with Anthropic (the AI company), put a few dollars on it, and get a secret code starting with <code>sk-ant-</code>. When you ask a question, the code tells Anthropic whose card to charge — typically <em>a fraction of a cent per question</em>. Guard the code the way you'd guard a card number: anyone who has it can spend your balance.</p>\n    </div>\n\n    <h3>Getting a key (one-time, ~5 minutes)</h3>\n    <ol>\n      <li><strong>Create a developer account</strong> at <a href=\"https://console.anthropic.com\">console.anthropic.com</a>. This is <em>separate</em> from a claude.ai login — a Claude Pro or Max subscription does not include API access. You'll verify a phone number during signup.</li>\n      <li><strong>Add a payment method and ~$5 of credit</strong> on the Billing page. Keys don't work until billing exists; the first $5 also raises your rate limit. <strong>Set a monthly spending limit while you're there</strong> — it's the single best protection against surprises.</li>\n      <li><strong>Create the key:</strong> Settings → API keys → Create Key. Name it something identifiable like <code>danger-close</code>. <strong>Copy it immediately</strong> — Anthropic shows the full key exactly once. If you lose it, you don't recover it; you revoke it and make a new one (painless — see rotation below).</li>\n    </ol>\n\n    <h3>Using it in the app</h3>\n    <p>Open the <strong>Ask AI</strong> tab. In any self-hosted copy you'll see the <strong>🔑 LOCAL API KEY</strong> panel just under the \"exactly what's sent\" disclosure. Paste the key, press <strong>SAVE KEY</strong>, and Ask AI is live. The panel then shows the key masked (<code>sk-ant-••••••••1234</code>) with a <strong>FORGET KEY</strong> button that removes it instantly.</p>\n\n    <h3>What it costs &amp; watching your usage</h3>\n    <p>Billing is pay-per-token (a token is roughly ¾ of a word). A typical Danger Close question — your plan context in, a one-screen answer out — costs <strong>well under a cent</strong>; $5 of credit realistically lasts months of regular use. Check the <strong>Usage</strong> and <strong>Billing</strong> pages at console.anthropic.com occasionally: they show spend by day and by key. If usage ever looks unfamiliar, rotate the key (below) first and investigate second.</p>\n\n    <h3>Where the key lives — and whether it survives closing the file</h3>\n    <p>The key is kept in your <strong>browser's private storage for this app</strong> — the same place your plan data lives. It is <em>never written into the HTML or JSX file itself</em>, and it is <em>never included in Export Backup</em>. Practical consequences:</p>\n    <ul>\n      <li><strong>Normal use survives:</strong> Save &amp; Apply, close the file, reopen the same file in the same browser → your plan <em>and</em> your key are still there. Nothing to re-enter day to day.</li>\n      <li><strong>Sharing is safe by construction:</strong> sending someone the HTML file, or one of your <code>.json</code> backups, cannot leak your key — it isn't in either.</li>\n      <li><strong>Some things reset it:</strong> a different browser, a private/incognito window, clearing the browser's site data, or the app's own <strong>Clear All Data</strong> all wipe the key (Clear All Data does so deliberately). Moving or renaming the HTML file <em>may</em> also start a fresh store, depending on how your browser scopes local files. In every such case the fix is 10 seconds: paste the key again (and Import Backup for the plan).</li>\n    </ul>\n\n    <h3>How safe is this? Honest answer: safe design, real residual risks</h3>\n    <table>\n      <tr><th>Built-in protections</th><th>What they don't cover</th></tr>\n      <tr><td>Key travels only over HTTPS, only to <code>api.anthropic.com</code> — nowhere else, ever.</td><td rowspan=\"4\"><strong>Anyone who can use this browser profile can use the key.</strong> For the app to send it, it must be readable — so a family member on your login, a browser extension with page access, IT management software on an employer-owned machine, or malware that owns the computer could all reach it. No design eliminates this class of risk; the mitigations on the left shrink the blast radius to pocket change.</td></tr>\n      <tr><td>Never embedded in the file, never in backups, masked on screen.</td></tr>\n      <tr><td>FORGET KEY removes it instantly; Clear All Data wipes it too.</td></tr>\n      <tr><td>Revocable in seconds at console.anthropic.com — a stolen key dies the moment you kill it.</td></tr>\n    </table>\n    <div class=\"note\"><strong>The three-part habit that makes this genuinely low-risk:</strong> use a <strong>dedicated key</strong> that does nothing but power this app, put a <strong>low monthly spending cap</strong> on it ($5–10), and press <strong>FORGET KEY</strong> whenever you leave the app on a shared or work machine. Worst realistic case then: someone burns a few dollars of AI credit before you revoke.</div>\n\n    <h3>Rotating the key (replacing it)</h3>\n    <p>Rotation is cheap insurance — do it immediately if you ever pasted the key somewhere by mistake, suspect the machine, or see unfamiliar usage, and consider doing it every few months purely out of caution. The whole cycle takes under a minute:</p>\n    <ol>\n      <li>At <a href=\"https://console.anthropic.com/settings/keys\">console.anthropic.com/settings/keys</a>: <strong>revoke</strong> the old key (it stops working within moments), then <strong>Create Key</strong> for a fresh one.</li>\n      <li>In the app: <strong>FORGET KEY</strong>, paste the new key, <strong>SAVE KEY</strong>.</li>\n    </ol>\n    \n    <h3>Exactly what an Ask AI call transmits — the complete list</h3>\n    <table>\n      <tr><th>Item</th><th>Sent?</th><th>Detail</th></tr>\n      <tr><td><strong>Destination</strong></td><td>—</td><td><code>api.anthropic.com</code> over HTTPS — or, if you've configured a Local Model, <code>your-machine/v1/chat/completions</code> and nothing touches Anthropic at all.</td></tr>\n      <tr><td><strong>Your structured plan summary</strong></td><td>YES</td><td>The generated context you can read verbatim under \"EXACTLY WHAT'S SENT\" on the Ask AI tab: names, ages, filing status, state, retirement year, portfolio totals and asset mix, account-type split, Social Security/pension amounts and claim ages, and headline simulation results.</td></tr>\n      <tr><td><strong>Your questions and the running conversation</strong></td><td>YES</td><td>Ask AI is a conversation: each turn re-sends the session so far (your questions and the AI's replies, capped at the last 12 messages) so the model can remember its own follow-up questions and your answers. ⟲ NEW SESSION forgets everything; nothing is stored after you leave.</td></tr>\n      <tr><td><strong>Attachments you added</strong></td><td>YES</td><td>Only files you explicitly attached (images/PDF/text; up to 8). On the Local Model route, images/PDFs are skipped — text only.</td></tr>\n      <tr><td><strong>Account numbers, logins, SSNs</strong></td><td>NO</td><td>The app never collects them, so they cannot transmit.</td></tr>\n      <tr><td><strong>Your API key</strong></td><td>Header only</td><td>Self-hosted copies send it as an HTTPS header to api.anthropic.com only — never in the message body, never to a local model, never anywhere else.</td></tr>\n      <tr><td><strong>Anything from any other tab</strong></td><td>NO</td><td>Only the summary above — not your full expense list, not position-level detail beyond the mix, not your checklist notes.</td></tr>\n      <tr><td><strong>Anything, while Offline Mode is on</strong></td><td>NO</td><td>The toggle at the top of the Ask AI tab hard-disables the feature; the EXECUTE button is dead and the call cannot fire.</td></tr>\n    </table>\n\n    <h3>Offline Mode — the hard switch</h3>\n    <p>Every tab except Ask AI already runs fully offline. The <strong>✈ OFFLINE MODE</strong> toggle at the top of the Ask AI tab closes that last door: while it's on, Ask AI is disabled outright, nothing can transmit, and the app is completely air-gapped. The setting persists between sessions and works everywhere — including inside claude.ai. Use it if you want a guarantee stronger than \"I just won't press EXECUTE.\"</p>\n\n    <h3>Local Model — Ask AI without Anthropic (self-hosted copies)</h3>\n    <p>Self-hosted copies can point Ask AI at an <strong>OpenAI-compatible server on your own computer</strong>, so your plan summary and questions go to your machine and never leave it:</p>\n    <ol>\n      <li><strong>Ollama:</strong> install from ollama.com, pull a model (<code>ollama pull llama3.1</code>), and start the server with browser access allowed: <code>OLLAMA_ORIGINS=\"*\" ollama serve</code>. Endpoint URL: <code>http://localhost:11434/v1</code>.</li>\n      <li><strong>LM Studio:</strong> load a model, start the local server, and <strong>enable CORS</strong> in its server settings. Endpoint URL: <code>http://localhost:1234/v1</code>.</li>\n      <li>In the app: Ask AI → <strong>🖥 LOCAL MODEL</strong> → paste the URL and model name → USE LOCAL MODEL. A violet ACTIVE badge confirms the route; BACK TO ANTHROPIC restores the default.</li>\n    </ol>\n    <div class=\"card warn\"><strong>Honest trade-offs.</strong> Local models here are text-only (image/PDF attachments are skipped), slower on ordinary hardware, and — bluntly — <strong>markedly weaker at tax and retirement reasoning</strong> than the hosted model. The privacy is real; so is the quality drop. Whatever route answers you, verify against the tabs and authoritative sources before acting. If the call fails instantly, it's almost always CORS — revisit step 1/2.</div>\n\n    <p class=\"micro\">Rotating or losing a key never touches your plan data — the two live in separate storage, and the plan's durable copy is always your exported <code>.json</code> backup.</p>\n\n    <div class=\"card warn\"><strong>Never put the key anywhere except the panel (or a git-ignored <code>.env</code> on the dev-server build).</strong> Not in the HTML file, not in a backup, not in an email, chat, screenshot, or code repository. Keys are personal: if someone else wants Ask AI, they create their own in five minutes. If a key ever does escape, revoke it first and ask questions after.</div>\n    <p class=\"micro\">Running the developer (Vite) build instead? The <code>.env</code> proxy in the project README is the stronger option there — the key stays on the server side and never enters the browser at all.</p>\n  </div>\n</section>\n\n\n<!-- RELOAD -->\n<section id=\"reload\">\n  <div class=\"wrap\">\n    <h2><span class=\"num\">11</span> Reloading &amp; Resetting <a class=\"toclink\" href=\"#toc\">↑ Contents</a></h2>\n    <ul>\n      <li><strong>Save &amp; Apply</strong> (My Data tab) — writes your edits to the browser cache and rebuilds every tab.</li>\n      <li><strong>Export Backup</strong> / <strong>Import Backup</strong> (My Data tab) — save your whole plan to a <code>.json</code> file, or load one back.</li>\n      <li><strong>Clear All Data</strong> (My Data tab) — wipes the browser cache — everything, including your checklist notes and contacts, display preferences, and any saved API key — and returns you to the landing screen.</li>\n      <li>Your plan is cached in the browser between visits, so the app reopens straight to it — no reloading needed day to day.</li>\n    </ul>\n    <div class=\"note\">The browser cache is the convenience copy; the exported <code>.json</code> is the durable one. Export a fresh backup after any significant change so you can always rebuild on a new browser or device.</div>\n    <h3>Where to keep the backup file — and what to call it</h3>\n    <p>The backup is a plain <code>.json</code> file containing <strong>your real figures</strong> — balances, income, Social Security, pension, and spending. The app never transmits it; pressing Export Backup simply saves it to your device. From that moment it is an ordinary file, so give it the same care you'd give a bank statement: keep it somewhere private — your Documents folder, a personal cloud drive, or a USB stick — rather than a folder you share with other people, and think twice before emailing it.</p>\n    <p>The app fills in a sensible filename for you (<code>dangerclose-backup-</code> plus the date and time), so you can simply press Export. If you'd rather name it yourself, keeping the word <strong>backup</strong> somewhere in the name makes it easy to find later — and, for the small number of people who keep a copy of the app's source folder from GitHub, filenames containing <code>backup</code> are already on that project's ignore list, so a backup saved into that folder stays out of anything published. Nobody using the app normally needs to think about this; the suggested name already handles it.</p>\n    <div class=\"note\">If you maintain the project repository yourself, the ignore rule <code>*[Bb]ackup*.json</code> covers every backup this app produces (and any you rename), while leaving <code>package.json</code> and friends untouched.</div>\n    <h3>Where your data actually lives — and how to prove it to yourself</h3>\n    <p>A point worth being crystal-clear about, especially for the downloaded single-file copy: <strong>your data is never written into the HTML file itself.</strong> The file is a fixed program — you can open it, enter thirty years of financial detail, press Save &amp; Apply a hundred times, and not one byte of the file changes. Everything you enter goes into your <strong>browser's private storage compartment</strong> for that file. That's why your plan reappears when you reopen the same file in the same browser — and why handing the file to someone else, or posting it anywhere, can never hand over your numbers.</p>\n    <p>Don't take this manual's word for it. Any of these takes under two minutes:</p>\n    <table>\n      <tr><th>Test</th><th>How</th><th>What you'll see</th></tr>\n      <tr><td><strong>Two-browser test</strong></td><td>Open the file in Chrome, enter some data, Save &amp; Apply. Leave it open, then open the <em>same file</em> in Microsoft Edge (or Firefox).</td><td>Edge shows the fresh landing screen — no trace of your data. It lives in Chrome's storage, not in the file. (Windows ships with Edge built in, so most machines do have a second browser even if you only ever use one.)</td></tr>\n      <tr><td><strong>Private-window test</strong> (one browser is enough)</td><td>With data saved, open the same file in an incognito / InPrivate window of the same browser.</td><td>Fresh landing screen again — private windows get their own separate, throwaway storage.</td></tr>\n      <tr><td><strong>File-properties test</strong></td><td>Right-click the file in File Explorer → Properties, and note its size and \"Date modified.\" Use the app heavily, Save &amp; Apply, then check Properties again.</td><td>Identical size, identical date — nothing was ever written to the file.</td></tr>\n      <tr><td><strong>Copy test</strong></td><td>Copy the HTML file to a USB stick and open it on another computer.</td><td>Landing screen — the copy carries the program, never the data.</td></tr>\n    </table>\n    <div class=\"card warn\"><strong>The flip side of that privacy:</strong> browser storage is convenient but perishable. Clearing the browser's site data, a browser reset or reinstall, a different browser, a different device — and the plan is simply gone, with no recovery. The exported <code>.json</code> backup is the <strong>only durable copy</strong> of your data. Export one after every meaningful change (My Data → Export Backup); Import Backup rebuilds everything from it in seconds.</div>\n    <p class=\"micro\">The same storage model applies everywhere the app runs — claude.ai and the local dev server included. Your API key (<a href=\"#apikey\">§10</a>) follows the same rule, with one deliberate difference: the key is excluded even from backups.</p>\n  </div>\n</section>\n\n<!-- HSA & MEDICARE CUTOFF -->\n<section id=\"hsa\">\n  <div class=\"wrap\">\n    <h2><span class=\"num\">12</span> HSA Contributions &amp; the Medicare Cutoff <a class=\"toclink\" href=\"#toc\">↑ Contents</a></h2>\n    <p class=\"lead\">A Health Savings Account is the most tax-advantaged account there is — pre-tax going in, tax-free growth, tax-free coming out for medical costs. But the <em>contribution</em> side has a hard stop tied to Medicare, not to your retirement date. Miss it and the contributions become penalized excess. This section explains exactly when each of you has to stop.</p>\n\n    <h3>The rule that matters</h3>\n    <p>You <strong>cannot contribute to an HSA for any month you are enrolled in Medicare</strong> — Part A or Part B, and free Part A counts. Retiring changes nothing on its own; <em>Medicare enrollment</em> is the trigger. The two usually land close together, which is why this feels like a retirement rule when it isn't.</p>\n    <div class=\"note\">Being on Medicare only stops <em>new</em> contributions — the account stays fully usable. Withdrawals for qualified medical costs, including Medicare Part B / Part D / Advantage premiums (but <strong>not</strong> Medigap), remain tax-free for life.</div>\n\n    <h3>Two ways Medicare starts — and when you must stop</h3>\n    <table>\n      <tr><th>Situation</th><th>When Part A is effective</th><th>Last HSA-eligible month</th></tr>\n      <tr><td>Claiming Social Security <strong>at or before 65</strong></td><td>Automatically at 65 — and it can't be declined while you're drawing SS</td><td>The month before your 65th-birthday month</td></tr>\n      <tr><td>Claiming SS / enrolling <strong>after 65</strong></td><td>Back-dated up to 6 months from your application (never before 65)</td><td>About 6 months before you file — at the latest</td></tr>\n      <tr><td>Working past 65 on an <strong>employer HDHP</strong></td><td>Deferred until you actually enroll</td><td>You can keep contributing right up to enrollment</td></tr>\n    </table>\n\n    <h3>The 6-month look-back trap</h3>\n    <p>If you delay Social Security and Medicare past 65 and then file, Part A is made <strong>retroactive up to six months</strong> (but never earlier than your 65th birthday). Any HSA contribution that falls inside that retroactive window turns into an excess contribution after the fact. The safe move: <strong>stop contributing at least six months before you file for Medicare or Social Security.</strong></p>\n\n    <h3>The year you stop is prorated</h3>\n    <p>Your annual limit is prorated by the number of HSA-eligible months in that final year — eligible for 4 of 12 months means 4/12 of the limit, and the age-55+ $1,000 catch-up prorates the same way. (The IRS \"last-month rule\" can let you fund a full year if you're eligible on December 1, but it triggers a 13-month testing period — losing eligibility to Medicare the next year claws part of it back — so don't lean on it right at your cutoff.)</p>\n\n    <h3>It can come even earlier than Medicare</h3>\n    <p>Medicare is the <em>latest</em> possible cutoff, not the only one. Contributing also requires that you're covered by a <strong>qualifying high-deductible health plan (HDHP)</strong>. If you drop the HDHP at retirement — moving onto an ACA marketplace plan, a non-HDHP retiree plan, or a spouse's plan — HSA eligibility ends that month regardless of Medicare.</p>\n\n    <h3>Where your actual dates live</h3>\n    <p>The <strong>Events</strong> tab computes each spouse's exact cutoff from the Social Security claiming ages in <strong>My Data</strong>: it shows the last eligible month, whether that final year is full or prorated, and a countdown, and it raises an alarm as the date nears. Change a claiming age and the cutoff moves with it. Treat the rules here as the explanation and the Events tab as the live answer for your plan.</p>\n\n    <div class=\"card warn\"><strong>Not tax advice.</strong> Excess HSA contributions are taxed and carry a 6% annual excise tax until they're withdrawn. Confirm the exact stop date — and any late-year contribution — with your HSA custodian and CPA before acting.</div>\n  </div>\n</section>\n\n<!-- LIMITATIONS -->\n<section id=\"limits\">\n  <div class=\"wrap\">\n    <h2><span class=\"num\">13</span> Limitations &amp; Known Issues <a class=\"toclink\" href=\"#toc\">↑ Contents</a></h2>\n    <ul>\n      <li><strong>Tax brackets are simplified.</strong> Federal bracket / standard-deduction logic is approximate; bracket inflation is modeled at 2%/yr. NIIT uses an estimated taxable-account yield (not actual dividends); the AMT check is simplified (standard-deduction add-back only); QCDs are a simplified what-if (a flat annual amount from the year each spouse turns 71; the one-time CRT/CGA election isn't modeled).</li>\n      <li><strong>State tax is an approximation layer.</strong> The 51-jurisdiction module (see the Taxes tab entry) uses effective flat rates in place of progressive state brackets, treats several income-limited exclusions as unconditional, and skips county/city taxes — pick your state in My Data, then verify against your state's own rules.</li>\n      <li><strong>Mortality is deterministic by default</strong> — deaths at exactly the entered life expectancies — with an optional <strong>STOCHASTIC LONGEVITY</strong> toggle on the Monte Carlo tab that samples death ages per run (see §06). The stochastic mode still samples the spouses independently — no joint-mortality correlation.</li>\n      <li><strong>Long-term care is modeled two ways, both simplified.</strong> The default is a single $150K–$300K shock at a fixed age; an optional sustained model (the <strong>LTC DISTRIBUTION</strong> toggle on the Monte Carlo tab, the Stress \"LTC Marathon\", and Run D) draws a multi-year care duration ending at death and escalates it at inflation +1.5%/yr. Neither is a full actuarial care distribution, and insurance payouts and home equity are not credited against the cost — so the sustained figures are deliberately gross (worst-case) numbers.</li>\n      <li><strong>Auto-replacement is a fixed example schedule</strong> and won't match every household. The old fixed part-time-work taper now applies only to the demo data — entering your own income streams (My Data → Other Income Streams) replaces it entirely.</li>\n      <li><strong>Peer benchmarks are point-in-time approximations</strong> from public surveys and will go stale.</li>\n      <li><strong>The Ask AI tab requires network access</strong> to the AI API; offline or rate-limited, it won't return results. Self-hosted copies also need a personal API key (<a href=\"#apikey\">§10</a>).</li>\n      <li><strong>US-only.</strong> No non-US tax residencies, accounts, Social Security analogues, or currencies.</li>\n      <li><strong>The temporary OBBBA \"senior bonus\" deduction (up to $6,000/person 65+, tax years 2025–2028, income-phased) is NOT modeled.</strong> Its omission makes near-term tax projections slightly conservative (overstated) for moderate-income 65+ households — a deliberate simplification for a provision that expires mid-plan. Every other 2026 constant — brackets, deductions, IRMAA tiers, QCD cap, RMD table and ages, wage base — has been verified against IRS Rev. Proc. 2025-32, CMS, and SSA and is asserted by the validation suite that ships with the project.</li>\n      <li><strong>The BASE prior is meaningfully more conservative than historical US equity performance</strong> (see section 06). Success rates read lower than commercial tools at default settings — by design.</li>\n    </ul>\n    \n    \n    <h3>Two kinds of dated information — one updates itself, one needs a new file</h3>\n    <p>Everything time-sensitive in this app falls into exactly two buckets, and knowing which is which tells you what maintenance it needs (short answer: almost none, and none of it is your data).</p>\n    <table>\n      <tr><th></th><th>Your personal timeline</th><th>The baked-in constants</th></tr>\n      <tr><td><strong>What it covers</strong></td><td>Every alarm on the Events tab that's about <em>you</em>: Medicare enrollment windows, your HSA contribution cutoff, Social Security filing windows, Roth-conversion and RMD deadlines, quarterly backup nudges, the January plan review.</td><td>The law-and-data numbers the math runs on: federal tax brackets and deductions, IRMAA tiers, the QCD cap, the Social Security wage base, the state-tax module, peer benchmarks, the backtest history.</td></tr>\n      <tr><td><strong>How it stays current</strong></td><td><strong>By itself, automatically, forever.</strong> Nothing is stored — every alarm is recalculated on every load from the dates in your plan plus today's date. Change a claiming age in My Data and every affected deadline moves instantly.</td><td><strong>Only with a new copy of the file.</strong> These numbers are printed into the app like figures in a book — the file cannot rewrite itself (that immutability is also why it's safe to share). Washington changes them about once a year.</td></tr>\n      <tr><td><strong>What you have to do</strong></td><td>Nothing. Keep your plan accurate in My Data; the alarms follow.</td><td>When the ⌛ STALE DATA strip appears (the January after this build's tax year), you need the current <strong>HTML file</strong>. The current build always lives at <a href=\"https://stextor.github.io/danger-close\">stextor.github.io/danger-close</a> — run it in your browser there, or save a fresh offline HTML copy from that page. (If someone handed you this file directly, you no longer need to go back to them for updates.) Once you have the new HTML file, open it in place of the old one: your plan survives the swap — it lives in your browser, not the file. Export a backup first as cheap insurance.</td></tr>\n    </table>\n    <div class=\\\"plain\\\">\n      <span class=\\\"lbl\\\">In plain English</span>\n      <p>Think of the app as a <strong>calculator with this year's tax tables printed on the back</strong>. The calculator part never goes stale — your deadlines and alarms are computed fresh from your own dates every time you open it. The printed tables do go stale, once a year, when the IRS publishes new ones — and since the file can't reprint itself, the fix is a fresh copy of the file. You'll never have to guess when: the app tells you, loudly, with a strip across the top that won't go away until the tables are current. The fresh copy is always one click away at <a href=\"https://stextor.github.io/danger-close\">stextor.github.io/danger-close</a> — no need to track down whoever gave you this file. If you maintain it yourself, the Events tab's tax-refresh alarm carries the update workflow.</p>\n    </div>\n\n    <h3>Data vintages — what is baked into this build, and how it stays current</h3>\n    <p>A single-file app cannot quietly update itself — a privacy feature with a maintenance cost. Every dated dataset in this build is listed here, and the app makes their age impossible to miss rather than pretending at an auto-updater:</p>\n    <table>\n      <tr><th>Dataset</th><th>Vintage in this build</th><th>Source</th><th>Refresh cadence</th></tr>\n      <tr><td>Federal tax brackets, deductions, LTCG, QCD cap</td><td>Tax year 2026</td><td>IRS Rev. Proc. 2025-32</td><td>Annual (late Oct)</td></tr>\n      <tr><td>IRMAA tiers &amp; surcharges</td><td>2026</td><td>CMS</td><td>Annual (Nov)</td></tr>\n      <tr><td>Social Security wage base</td><td>2026 ($184,500)</td><td>SSA</td><td>Annual (Oct)</td></tr>\n      <tr><td>State tax module</td><td>2026 approximations</td><td>State DORs / surveys</td><td>Annual</td></tr>\n      <tr><td>RMD Uniform Lifetime Table</td><td>2022 revision (current)</td><td>IRS Pub. 590-B</td><td>Rarely changes</td></tr>\n      <tr><td>Peer benchmarks (Ranking)</td><td>2022 SCF + EBRI/SSA/AALTCI</td><td>Federal Reserve et al.</td><td>SCF is triennial — the 2025 survey publishes ~fall 2026</td></tr>\n      <tr><td>Backtest return/CPI series</td><td>Through 2025</td><td>Damodaran (NYU Stern) + BLS</td><td>Annual (Jan)</td></tr>\n      <tr><td>LTC cost/duration parameters</td><td>2022-24 research vintage</td><td>ASPE / Urban Institute</td><td>Occasional</td></tr>\n    </table>\n    <p><strong>The three-layer freshness system:</strong> <em>(1)</em> the <strong>Events tab</strong> carries a live alarm for each refresh cycle (tax constants, backtest append, SCF release) with paste-in instructions and the authoritative source for each; <em>(2)</em> starting the January after this build's tax year ends, a <strong>⌛ STALE DATA strip</strong> appears above the tabs on every view — amber the first year, red from the second — and cannot be dismissed, because stale tax law silently corrupts every projection; <em>(3)</em> the <strong>validation suite</strong> in the project folder asserts the constants against their cited sources, so a refreshed build proves itself. The update path is deliberately simple: download the current build and Import Backup — your data lives in the browser, not the file, so swapping the file loses nothing.</p>\n\n    <p class=\"micro\">The Historical Backtest tab now provides the historical-replay capability (\"what if I retired in 1966?\") that earlier versions lacked.</p>\n  </div>\n</section>\n\n<!-- FAQ -->\n<section id=\"faq\">\n  <div class=\"wrap\">\n    <h2><span class=\"num\">14</span> Troubleshooting &amp; FAQ <a class=\"toclink\" href=\"#toc\">↑ Contents</a></h2>\n    <p>The most common \"is it broken?\" moments, decoded. Almost all of them trace back to one of three things: no simulation has run yet, the browser cache was cleared, or the Ask AI tab can't reach the network.</p>\n    <table>\n      <tr><th>Symptom</th><th>Likely cause</th><th>Fix</th></tr>\n      <tr><td>Will Social Security run out? Should I plan on a cut?</td><td>Reserve depletion is not bankruptcy — payroll taxes keep funding checks, just not the full scheduled amount (2026 Trustees Report: ~78% from late 2032 on the retirement fund alone, or ~83% from 2034 if Congress merges in the disability fund). Whether Congress acts — it always has before a cut landed — is unknowable, so the SS tab\'s <strong>Trust-Fund Depletion Scenario</strong> panel lets you model it instead of guessing: pick a preset or custom cut and every simulation, the Roth engine, the Dashboard, and the claiming grid recompute. Try your plan both ways; the gap between them is your personal exposure.</td></tr>\n      <tr><td>How do I model rental income, part-time work, an annuity, or other income?</td><td>First-class support now</td><td>My Data → <strong>OTHER INCOME STREAMS</strong>: one row per stream (rental / job / annuity / other) with a monthly amount in today’s dollars, inclusive start and end years (blank end = for life), owner (either spouse or joint — an owner’s stream stops at that person’s projected death), a COLA flag, and taxable vs tax-free treatment. Streams flow through every engine — Monte Carlo, Trajectory, Withdrawal, Taxes (job rows also pay FICA), IRMAA, and the Roth optimizer. For a job after retirement, enter the year the work starts and the last year you expect to work. Entering any stream replaces the built-in example part-time schedule. If you used the old negative-expense-row workaround, move that row here so the tax engines see it.</td></tr>\n      <tr><td>A tab is blank or a chart is missing</td><td>No simulation has run for the selected retirement date yet</td><td>Pick a retirement date at the top — Monte Carlo and Stress auto-run on first visit.</td></tr>\n      <tr><td>Ask AI does nothing when clicked</td><td>It refuses to send until at least one simulation has completed</td><td>Open the Monte Carlo tab once, let it finish, then ask again.</td></tr>\n      <tr><td>Ask AI shows <code>ERROR [4xx/5xx]</code></td><td>The AI API received the request but refused it (rate limit, oversized attachment, outage)</td><td>Wait a minute and retry. Trim attachments — 8-file cap; images, PDF, and text only (no HEIC, no Office files — export those to PDF/CSV).</td></tr>\n      <tr><td>Ask AI shows <code>COMMS ERROR</code></td><td>No network path to the AI API (offline, blocked, or a changed endpoint)</td><td>Check the connection. Self-hosted copy? Paste a personal API key into the LOCAL API KEY panel on the Ask AI tab (see its warning text). Everything else in the app runs fully offline — only Ask AI needs the network.</td></tr>\n      <tr><td><code>REQUEST TIMED OUT (45s)</code></td><td>The question was very broad or the service is slow</td><td>Ask a narrower question and retry.</td></tr>\n      <tr><td>All my data vanished</td><td>The browser cache was cleared, or this is a new browser/device</td><td>My Data → <strong>Import Backup</strong> with your exported <code>.json</code>. Export one regularly — the cache is a convenience copy, not storage (see <a href=\"#start\">§03</a>).</td></tr>\n      <tr><td>A red banner sits on every tab</td><td>An income figure is missing, so an example value was substituted</td><td>Enter the missing Social Security / pension numbers in My Data (see <a href=\"#banner\">§04</a>).</td></tr>\n      <tr><td>My success rate is far below other tools</td><td>The BASE prior is deliberately conservative (see <a href=\"#controls\">§06</a>)</td><td>Not a bug. Switch the scenario prior to BULL-LEANING for history-like assumptions and compare.</td></tr>\n      <tr><td>One edit changed numbers everywhere</td><td>By design — every tab derives from one model (see <a href=\"#flow\">§02</a>)</td><td>Re-check the edit in My Data; Save &amp; Apply rebuilds all 26 tabs from it.</td></tr>\n      <tr><td>My API key vanished from the Ask AI tab</td><td>The key lives in browser storage — a different browser, incognito window, cleared site data, Clear All Data, or (in some browsers) a moved/renamed file starts a fresh store</td><td>Paste the key again (10 seconds) and Import Backup for the plan. By design the key is never inside a backup — see <a href=\"#apikey\">§10</a>.</td></tr>\n      <tr><td>I think my API key leaked</td><td>Keys are instantly revocable — a leaked key is only dangerous while it lives</td><td>Revoke it at console.anthropic.com/settings/keys, create a new one, FORGET KEY in the app, paste the new one, and check the Console usage page (see <a href=\"#apikey\">§10</a>).</td></tr>\n      <tr><td>The HSA cutoff date looks wrong</td><td>It derives from the Social Security claiming ages in My Data</td><td>Fix the claim ages — the Events tab recomputes the cutoff automatically (see <a href=\"#hsa\">§12</a>).</td></tr>\n    </table>\n    <div class=\"note\"><strong>Keeping a copy of this manual:</strong> use the toolbar above the Docs tab to download it as HTML or print it to PDF — useful if you want the reference open while working in another tab.</div>\n  </div>\n</section>\n\n<!-- GLOSSARY -->\n<section id=\"glossary\">\n  <div class=\"wrap\">\n    <h2><span class=\"num\">15</span> Glossary <a class=\"toclink\" href=\"#toc\">↑ Contents</a></h2>\n    <p>Concise reference. Many terms have nuances this glosses over — verify against authoritative sources before acting.</p>\n    <div class=\"glossary\">\n      <p class=\"term\"><b>4% Rule</b> — Bengen's heuristic: withdrawing 4% of a starting portfolio (inflation-adjusted thereafter) historically lasted 30 years across most US periods. Often quoted, rarely the right answer for everyone.</p>\n      <p class=\"term\"><b>ACA</b> — Affordable Care Act. The \"ACA bridge\" covers a spouse between job-based coverage and Medicare at 65.</p>\n      <p class=\"term\"><b>API Key</b> — the secret code (starts <code>sk-ant-</code>) that identifies your Anthropic developer account when a self-hosted copy calls the AI service. Created at console.anthropic.com; treat it like a card number and see §10 for the full guide.</p>\n      <p class=\"term\"><b>Agency MBS</b> — Mortgage-backed securities guaranteed by Fannie/Freddie/Ginnie; Treasury-level credit quality with extra yield for prepayment risk.</p>\n      <p class=\"term\"><b>Asset Class</b> — A category of investments with similar behavior (equities, bonds, cash, commodities). The MC classifies holdings this way.</p>\n      <p class='term'><b>Beneficiary Designation</b> — The named recipient on a retirement account or policy; it overrides your will, so keep it current.</p>\n      <p class='term'><b>Bengen / 4% Rule origin</b> — William Bengen's 1994 study established the 4% safe-withdrawal heuristic; later refined by the Trinity Study (Cooley, Hubbard, Walz 1998).</p>\n      <p class=\"term\"><b>Beta</b> — How much a holding moves relative to the market. 1.0 = moves with it; 1.5 = 50% more; 0.5 = 50% less.</p>\n      <p class=\"term\"><b>Bond</b> — A debt instrument paying interest and returning principal at maturity; provides stability and income.</p>\n      <p class='term'><b>Bond Tent</b> — Pfau/Kitces idea of dipping equity exposure right around retirement, then rising again — the shape that defends the fragile early years against sequence risk.</p>\n      <p class=\"term\"><b>Bond Vigilantes</b> — Investors who sell long government bonds (pushing yields up) to protest fiscal policy.</p>\n            <p class='term'><b>CAPE (Shiller P/E)</b> — Cyclically-adjusted price/earnings ratio; high CAPE has historically predicted lower forward real returns, part of the rationale for the conservative BASE prior.</p>\n      <p class='term'><b>Capital Gains</b> — Profit on a sold asset. Long-term (held &gt;1yr) is taxed at 0/15/20%; short-term is taxed as ordinary income.</p>\n      <p class=\"term\"><b>CFA / CFP / CPA</b> — Professional designations for investment analysts / financial planners / accountants. The author holds <strong>none</strong> of these.</p>\n      <p class='term'><b>COLA</b> — Cost-of-living adjustment; the annual inflation raise applied to Social Security and some pensions.</p>\n      <p class='term'><b>Cost Basis</b> — What you paid for a holding; sale proceeds above basis are capital gains. Inherited assets generally get a step-up to date-of-death value.</p>\n      <p class=\"term\"><b>Crisis Scenario</b> — Low-probability severe shock (2008-style). Default 3%/yr under BASE.</p>\n      <p class=\"term\"><b>Crossover Age</b> — The age at which delayed SS claiming's cumulative benefit overtakes earlier claiming. Living past it favors delaying.</p>\n      <p class=\"term\"><b>DCA</b> — Dollar-cost averaging: investing a fixed amount on a schedule regardless of price.</p>\n      <p class=\"term\"><b>Drawdown</b> — Percentage decline from a peak to a trough. \"Max drawdown\" is the worst such decline.</p>\n      <p class=\"term\"><b>Duration</b> — A bond's price sensitivity to rates. 6-yr duration ≈ −6% if rates rise 1%.</p>\n      <p class=\"term\"><b>EBRI</b> — Employee Benefit Research Institute; publishes the Retirement Readiness Index. Cited in Ranking.</p>\n      <p class='term'><b>Effective vs Marginal Rate</b> — Marginal is the rate on your next dollar; effective is total tax ÷ total income. Roth-conversion decisions hinge on the marginal rate.</p>\n      <p class=\"term\"><b>Equity</b> — Stock ownership; \"equities\" = stock holdings collectively.</p>\n      <p class='term'><b>Estate Documents</b> — Will, revocable living trust, durable power of attorney, healthcare proxy/advance directive, and beneficiary designations. Tracked on the Checklist tab.</p>\n      <p class=\"term\"><b>ETF</b> — Exchange-traded fund; a pooled fund trading like a stock. Most index funds are ETFs.</p>\n      <p class=\"term\"><b>Expense Ratio</b> — A fund's annual fee as a % of assets. 0.10% = $10/yr per $10K. Compounds over decades.</p>\n      <p class=\"term\"><b>Fed SCF</b> — Federal Reserve Survey of Consumer Finances; the authoritative US wealth-comparison source. Used in Ranking.</p>\n      <p class=\"term\"><b>Fiduciary</b> — Someone legally bound to act in your best interest. A fee-only fiduciary is paid only by you. The author is <strong>not</strong> your fiduciary.</p>\n      <p class=\"term\"><b>FRA</b> — Full Retirement Age; the age for full Social Security (67 for those born 1960+). Earlier reduces, later increases.</p>\n      <p class=\"term\"><b>Glidepath</b> — A planned allocation change over time. A <em>reverse</em> glidepath (Pfau/Kitces) starts retirement lower-equity, then raises equity to combat sequence risk.</p>\n      <p class=\"term\"><b>Guyton-Klinger Guardrails</b> — Dynamic spending rules: cut if the portfolio falls to a lower band (80% of plan), raise at an upper band (120%).</p>\n      <p class=\"term\"><b>High Yield</b> — Below-investment-grade corporate bonds (\"junk\"); higher yield for higher default risk.</p>\n      <p class=\"term\"><b>HSA</b> — Health Savings Account. Tax-deductible in, tax-free growth, tax-free for qualified medical use; after 65, non-medical use is taxed but not penalized.</p>\n      <p class=\"term\"><b>Index Fund</b> — A fund that passively tracks an index; typically far cheaper than active funds.</p>\n      <p class=\"term\"><b>Investment Grade</b> — Corporate bonds rated BBB-/Baa3 or higher; lower risk and yield than high-yield.</p>\n      <p class=\"term\"><b>IRA</b> — Individual Retirement Account; Traditional (pre-tax in, taxed out) or Roth (after-tax in, tax-free out).</p>\n      <p class=\"term\"><b>IRMAA</b> — Income-Related Monthly Adjustment Amount; a Medicare surcharge based on MAGI two years prior. Cliffs — crossing by $1 can cost thousands.</p>\n      <p class=\"term\"><b>Kitces, Michael</b> — Planning researcher; with Pfau, established the reverse-glidepath work.</p>\n      <p class=\"term\"><b>LTC</b> — Long-Term Care; help with daily activities, largely not covered by Medicare. A major risk — can run $80K–$150K+/yr/person.</p>\n      <p class=\"term\"><b>LTC Duration Tail</b> — The risk that care lasts many years and clusters at the very end of life, when the portfolio is smallest and one spouse's Social Security has stopped. A single early \"LTC shock\" misses it; the Stress LTC Marathon and Monte Carlo Run D exist to show it.</p>\n      <p class=\"term\"><b>MAGI</b> — Modified Adjusted Gross Income; used for IRMAA, Roth limits, and credits. Slightly different from AGI.</p>\n      <p class=\"term\"><b>MBS</b> — Mortgage-backed securities; bonds backed by pools of home mortgages.</p>\n      <p class=\"term\"><b>MFJ</b> — Married Filing Jointly; wider brackets and a higher standard deduction than other statuses.</p>\n      <p class=\"term\"><b>Money Market</b> — Cash-like instruments aiming for a stable $1 NAV; lowest risk and yield.</p>\n      <p class=\"term\"><b>Monte Carlo</b> — Running thousands of randomized projections to estimate the distribution of outcomes.</p>\n      <p class=\"term\"><b>NAPFA</b> — National Association of Personal Financial Advisors; a directory of fee-only fiduciaries (napfa.org).</p>\n      <p class='term'><b>NIIT</b> — Net Investment Income Tax; an extra 3.8% on investment income above MAGI (unindexed) thresholds. Modeled on the Taxes tab from an estimated taxable-account yield.</p>\n      <p class=\"term\"><b>Pension</b> — A defined-benefit income stream from a former employer. The example has a small one; most private workers don't.</p>\n      <p class=\"term\"><b>Percentile</b> — The value below which a stated % of outcomes fall. The 10th-percentile outcome is worse than 90% of cases.</p>\n      <p class=\"term\"><b>Pfau, Wade</b> — Retirement-income researcher (safe withdrawal rates, reverse glidepaths, retirement-income frameworks).</p>\n      <p class='term'><b>Provisional Income</b> — The figure (other income + half of SS) that determines how much of your Social Security is taxable.</p>\n      <p class='term'><b>QCD</b> — Qualified Charitable Distribution; a direct Traditional-IRA→charity gift (age 70½+), excluded from income and MAGI, that can satisfy RMDs. Modeled as a what-if on the Taxes tab (also lowers MAGI on the IRMAA tab); 2026 cap $111K/person, indexed. Roth QCDs are permitted but pointless — Roth withdrawals are already tax-free.</p>\n      <p class=\"term\"><b>Real Yield</b> — Bond yield after expected inflation; TIPS yields are the common reference.</p>\n      <p class=\"term\"><b>Recession Scenario</b> — Moderate contraction (equity ≈ −15%). Default 10%/yr under BASE.</p>\n      <p class=\"term\"><b>RMD</b> — Required Minimum Distribution; forced taxable withdrawals from Traditional accounts starting at 73/75. A key motivation for Roth conversions.</p>\n      <p class=\"term\"><b>Roth Conversion</b> — Moving Traditional money to Roth, paying tax now for tax-free growth later. Common in low-income gap years.</p>\n      <p class=\"term\"><b>Roth IRA / 401(k)</b> — After-tax contributions; growth and qualified withdrawals are tax-free.</p>\n      <p class='term'><b>Roth Ladder</b> — A multi-year sequence of Roth conversions in low-income gap years to shrink future RMDs and the widow's-penalty bracket jump.</p>\n      <p class=\"term\"><b>Ruin Rate</b> — The % of MC paths that hit $0 before the horizon ends.</p>\n      <p class=\"term\"><b>Sequence-of-Returns Risk</b> — The risk that poor early-retirement returns permanently impair the portfolio even if averages are fine. The first 5–10 years are highest-risk.</p>\n      <p class=\"term\"><b>Sharpe Ratio</b> — Excess return over the risk-free rate ÷ standard deviation. Higher is better.</p>\n      <p class=\"term\"><b>Social Security</b> — Federal retirement benefit, claimable 62 (reduced) to 70 (max). Depends on claiming age, work history, longevity.</p>\n      <p class=\"term\"><b>SSA</b> — Social Security Administration; ssa.gov is the authoritative benefit-estimate source.</p>\n      <p class=\"term\"><b>Stagflation</b> — Low growth + high inflation (1970s). The MC scenario uses negative real returns with 6–8% inflation. Default 7%/yr under BASE.</p>\n      <p class='term'><b>Standard Deduction</b> — The flat amount subtracted from income before tax; larger for Married Filing Jointly than Single — the core of the widow's penalty.</p>\n      <p class='term'><b>Step-Up in Basis</b> — At death, taxable assets reset to current market value, erasing the heir's capital-gains liability on prior appreciation.</p>\n      <p class=\"term\"><b>Success Rate</b> — % of MC paths ending above a threshold ($500K/$800K/$1.5M here). Not the same as ruin rate.</p>\n      <p class='term'><b>Survivor Benefit</b> — When a spouse dies, the survivor keeps the larger of the two Social Security checks (not both) — a benefit cut the Survivor tab models.</p>\n      <p class=\"term\"><b>TCJA</b> — 2017 Tax Cuts and Jobs Act; many individual provisions expire after 2025 unless extended.</p>\n      <p class=\"term\"><b>Term Premium</b> — Extra yield long bonds offer over short ones for duration risk.</p>\n      <p class=\"term\"><b>TIPS</b> — Treasury Inflation-Protected Securities; principal adjusts with CPI, giving a real yield.</p>\n      <p class=\"term\"><b>Token (AI billing)</b> — the unit AI usage is billed in, roughly ¾ of a word. A full Ask AI question and answer runs a few thousand tokens — well under a cent.</p>\n      <p class=\"term\"><b>Trad / Traditional</b> — Pre-tax retirement accounts; contributions reduce taxable income, withdrawals taxed, RMDs apply. Opposite of Roth.</p>\n      <p class=\"term\"><b>Treasury</b> — US government debt. T-bills &lt;1yr, T-notes 2–10yr, T-bonds 20–30yr. Lowest credit risk.</p>\n      <p class=\"term\"><b>Volatility</b> — Variation in returns, usually standard deviation. Higher = wider range of outcomes.</p>\n      <p class='term'><b>Widow's Penalty</b> — The tax hit when a surviving spouse files Single: narrower brackets and a smaller standard deduction on often-similar income.</p>\n      <p class=\"term\"><b>Yield Curve</b> — Yields across maturities. \"Steepening\" = long yields rising vs short; \"inverted\" = short above long (a recession signal).</p>\n      <p class='term'><b>Authoritative sources</b> — Verify against <a href='https://www.ssa.gov'>ssa.gov</a> (benefits), <a href='https://www.irs.gov'>irs.gov</a> (tax), <a href='https://www.medicare.gov'>medicare.gov</a> (IRMAA/premiums), and find a fee-only fiduciary at <a href='https://www.napfa.org'>napfa.org</a>.</p>\n    \n    </div>\n    <a class=\"totop-foot\" href=\"#toc\">↑ Back to Table of Contents</a>\n  </div>\n</section>\n\n<!-- FINAL -->\n<section id=\"final\">\n  <div class=\"wrap\">\n    <h2><span class=\"num\">16</span> Final Disclaimer <a class=\"toclink\" href=\"#toc\">↑ Contents</a></h2>\n    <div class=\"card danger\">\n      <p>This software is a personal modeling tool the author built for their own use and decided to share. <strong>It is not a product. No support, no warranty, no service commitment, no guarantee of correctness.</strong></p>\n      <p>If you use this software and lose money, miss a tax deadline, claim Social Security at the wrong age, buy the wrong house, run out of money, or experience any other setback — that is your responsibility, not the author's. <strong>The author has no professional financial credentials of any kind</strong> — no CFP, CFA, CPA, Series 65, Enrolled Agent, or law license — and is a stranger on the internet who wrote some JavaScript as a hobby.</p>\n      <p style=\"margin-bottom:0\"><strong>Before any decision this app informs:</strong> consult a fee-only fiduciary advisor (NAPFA.org), a CPA for tax planning (Roth conversions, IRMAA, RMDs), and an estate attorney; verify every input against your statements (custodian, SSA, employer, insurer); and verify every output against a second opinion. If you cannot accept these terms, close the app and use a tool from a regulated provider.</p>\n    </div>\n    <p style=\"font-style:italic;color:var(--ink-faint);font-size:12px\">Danger Close is provided \"AS IS.\" The author retains no responsibility for outcomes resulting from its use.</p>\n  </div>\n</section>\n\n<footer>\n  <div class=\"wrap\">\n    <div class=\"kicker\">// END OF FIELD MANUAL</div>\n    DANGER CLOSE v5.23 · documentation regenerated · not financial advice · guardrails: Guyton-Klinger (80% / 120%)\n  </div>\n</footer>\n\n</body>\n</html>\n";

